window.__TRANSKY_ATLAS_DATA__=window.__TRANSKY_ATLAS_DATA__||[];window.__TRANSKY_ATLAS_DATA__.push("{\"meta\":{\"title\":\"药娘的天空\",\"version\":\"1.0\",\"sourcePages\":2934,\"coverage\":{\"main\":665,\"extras\":79}},\"canon\":{\"tagline\":\"从离家的一天，到那些再也回不来的人。\\n循着相遇、选择与失去，读懂整部小说。\",\"essence\":\"这是一部以苏雨晴的离家、谋生、相爱、归家与死亡为主轴的群像小说。她得到过真切的温柔，也见证伙伴们被偏见、家庭压力、暴力与误解推向不同结局。它的核心张力在于：一个人想按自己的意愿生活，需要什么；而当身份被看见之后，那些承诺还会不会成立。这里是文学归纳，并不把所有角色压成同一种命运。\",\"volumes\":[{\"id\":1,\"name\":\"朦胧的世界\",\"start\":1,\"end\":60,\"brief\":\"出走与立足，面馆、出租屋和最初的朋友。\"},{\"id\":2,\"name\":\"迷茫地前行\",\"start\":61,\"end\":200,\"brief\":\"再次逃离、合租谋生，群像与亲密关系展开。\"},{\"id\":3,\"name\":\"同行的远路\",\"start\":201,\"end\":400,\"brief\":\"爱情渐近，创伤、家庭重担与复仇暗流积累。\"},{\"id\":4,\"name\":\"抓不住的幸福\",\"start\":401,\"end\":600,\"brief\":\"接连决裂、死亡与离散，旧生活逐步瓦解。\"},{\"id\":5,\"name\":\"爱情到底是什么呢\",\"start\":601,\"end\":665,\"brief\":\"回家、转变、收养、婚礼，最终仍面对失去。\"}],\"layerOverview\":[{\"title\":\"正文的生活与终局\",\"text\":\"五卷665章是基本时间轴；其中也有梦境、幻觉与超自然悬疑，需要按后文揭示校正。\"},{\"title\":\"正式外传的后续\",\"text\":\"死后外传回应雨晴的来生愿望；方莜莜篇继续交代她与安念的关系结局。\"},{\"title\":\"幸福假设 IF\",\"text\":\"《假如一切都还在》改写若干关键选择，是独立假设线。不能拿它覆盖正文的死亡与分离。\"},{\"title\":\"前传与作者附录\",\"text\":\"前传补足来历；《故事之外》是作者以现实素材口吻写的文本，须与小说人物正史分开。\"}],\"keyQuestions\":[{\"question\":\"苏雨晴到底经历了什么？\",\"answer\":\"她15岁从杭州出走，在小城市做面馆、超市、加油站与宠物店等工作，经历合租、相恋和朋友离散。后来与父母和解，接受家庭支持，迁台复学、与莫空养育语默并成婚；正文最终写她病逝。幸福是真的，失去也没有被正文撤销。\",\"refs\":[\"c001\",\"c107\",\"c503\",\"c595\",\"c620\",\"c634\",\"c657\",\"c662\",\"c665\"]},{\"question\":\"谁是她最重要的爱人？\",\"answer\":\"林夕晨与莫空分别处在她生命中不同阶段。夕晨从室友、画友成为恋人，死后仍留在她的画、习惯与梦里；莫空最早以陌生旅人出现，长期帮助她，后来成为伴侣、丈夫与共同养育女儿的人。两段关系都需要按自己的经历理解。\",\"refs\":[\"c156\",\"c160\",\"c421\",\"c584\",\"c617\",\"c660\",\"c662\"]},{\"question\":\"为什么要把群像一起看？\",\"answer\":\"胡玉牛、天语遥、张思凡、方莜莜面对的起点、资源与愿望并不一样。有的是主动追求女性生活，有的最初遭到强迫，有的后来选择另一种社会生活；亲密关系也可能带来接纳、隐瞒、背叛或沉重压力。比较这些差异，比给所有人物套同一个结论更接近原书。\",\"refs\":[\"c098\",\"c296\",\"c302\",\"c450\",\"c561\",\"c652\",\"x035\"]},{\"question\":\"结尾的“来生”有定论吗？\",\"answer\":\"正文止于雨晴死亡、曲奇随后死亡，莫空与语默继续生活。死后外传另写太阴帮助雨晴转生为叶洛夜，并让她失去前世记忆。c660里夕晨出现是梦，幸福IF的双婚礼则是另一条假设线；三者不能合写成“正文大家最终团圆”。\",\"refs\":[\"c660\",\"c665\",\"x001\",\"x043\"]}],\"synopsis\":[\"2004年，15岁的苏雨晴在药物与女装被父母发现后遭到暴力对待与强制剃发，带着少量钱离开杭州。她抵达浙江一座被原文称为“小城市”的地方，丢失钱包，挨饿、求职，在面馆老板娘张阿姨的帮助下得到第一份工作和一间能关上门的小屋。最初的生活很小：一顿饭、一份工资、能保存秘密的抽屉、一朵给自己的勿忘我。黑猫曲奇与灰鼠咖啡进入她的日常，陌生男子莫空则在旅途、河边与危急时刻反复出现。\",\"在网上，雨晴认识了“月橙”，现实见面才发现对方就是张思凡。思凡成为姐姐般的陪伴者，也把她带进更广的人际圈。父母追到小城市后，雨晴再度逃走，先住进思凡家，随后与思凡、方莜莜、胡玉牛合租白兔小区七楼的房子。大家找工作、分房租、学做饭、过节、争吵又互相照顾。房子把互不相同的人暂时组成了一个家，但日常的热闹并没有消除工作里的排斥、钱的匮乏和各人的秘密。\",\"林夕晨搬来后，雨晴在绘画、赠画和共同生活中逐渐靠近她。夕晨外表温和、沉静，背后却是暴力父亲、被轻视的姐姐们，以及持续向家里汇款的责任。她们在新年确认恋爱。与此同时，胡玉牛与柳韵相爱，却隐瞒自己的女性愿望；方莜莜与安念从网络游戏走到现实相见；张思凡把未来托付给孙昊，而孙昊的态度早已埋下轻慢和背叛的迹象。\",\"复仇线把这些温柔日常撕开。天冲云曾参与对柳韵的侵害，在胡玉牛反击中受重伤，之后又被家人强行推向女性化生活，改名天语遥。她经历抵抗、自伤、妥协、与夏归月重新接近，也逐步找回对胡玉牛的仇恨。她搜集证据向柳韵揭露胡玉牛的秘密；柳韵一度放下报复，却把信意外遗落在胡家。家庭拒绝、误会分手、工作场所公开羞辱接踵而至，胡玉牛最终自伤、抢救无效死亡。柳韵再把仇恨转向天语遥，造成更严重的侵害；获救的天语遥长期失去正常生活能力，夏归月与父母继续照护她。\",\"合租生活逐步解散。张思凡发现孙昊背叛后离开，后文写他回到男性社会生活、结婚并寻求领养；方莜莜与安念同居开店，但家庭婚育压力在正式外传中最终使二人分离。夕晨为父亲治疗费用身陷剥削与伤害，雨晴发现后想承担她的痛苦，却也把自己置于危险之中。回乡后的夕晨遭暴力与禁闭，最终杀害父母后自杀。雨晴面对遗物、死讯和再也不能等到的人，开始学习带着悼念继续生活。与此同时，自己曾视为无人援助的漂泊，逐渐显露父母和亲属暗中照看的一面。\",\"失去咖啡后，莫空越来越稳定地走入雨晴的生活。他的家族、与秋易的往来、占卜和疑似超常能力，构成一条没有全部解释的悬疑线。雨晴终于决定回杭州，得到父母公开接纳；父亲为保护全家脱离宗族，支持她完成手术、变更身份并迁居台湾。莫空追随而来，她重新进入高中，结识新朋友，也保留夕晨赠画和旧友的信物。\",\"回访小城市时，旧店铺消失，朋友失联，天语遥仍需照护。随后，雨晴与莫空在福利院遇见已婚的张思凡：两家最终分别收养林清雾与林清云兄妹，妹妹改名莫语默。2011年7月23日，雨晴与莫空在海边举行婚礼；她从被照顾的少女变成妻子与母亲。在婚前的梦中，她清楚知道夕晨已经离世，仍愿意让记忆与爱陪伴自己。\",\"正文最后把时间推到2016年。雨晴重病，家人与莫空尽力救治仍未能留住她；4月4日是正文明确写出的安葬日。曲奇在她墓前守候，三天后死去。莫空带着语默离开墓地，承诺替雨晴好好爱护女儿。正式死后外传则进一步写她在太阴帮助下转生为叶洛夜，并失去前世记忆；幸福IF另提供若干不同的选择与团聚，供读者看到“如果当时有人拉住他们”的另一种可能。\"],\"synopsisRefs\":[\"c001\",\"c006\",\"c024\",\"c080\",\"c112\",\"c156\",\"c296\",\"c421\",\"c436\",\"c450\",\"c487\",\"c499\",\"c561\",\"c584\",\"c620\",\"c633\",\"c656\",\"c661\",\"c665\",\"x001\",\"x035\",\"x043\"],\"endingLead\":\"正文真正的收束是：苏雨晴与曲奇死亡，莫空和莫语默继续生活。死后外传让雨晴以叶洛夜的身份转生，代价是前世记忆消失；幸福 IF 则让主要朋友在另一套事件发展中相聚。这些结局应当并列辨认，不能相互取消。\",\"objectLead\":\"把物品沿时间追踪：发卡连着旧同桌，贝壳连着夕晨，白裙连着家庭的伤害与补偿，钥匙连着两次相反方向的旅途，占卜卡则跨进死后外传。宠物既有角色档案，也在这里作为日常陪伴与失去的线索登记。\",\"timelineNote\":\"主线从2004年春的出走，走到2008年复学与收养、2011年婚礼和2016年终局。原著个别年龄、日期与前后天数不完全一致；这里优先采用明确写出的年份及事件顺序，不把推算伪装成精确日期。死后外传的“2010年转生”属于倒退时间的超自然安排。\",\"mapNote\":\"故事的空间核心是“小城市”的住处、工作场所和公共空间；杭州既是出走原点，也是回家的终点；台湾花莲与苏家村承接重建的家庭生活。书中一些匿名城市、梦中地点及自相矛盾的地理描述只保留叙事功能。\",\"graphCore\":[\"苏雨晴\",\"莫空\",\"林夕晨\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"天语遥\",\"柳韵\",\"夏归月\",\"孙昊\",\"安念\",\"曲奇\",\"苏榕槐\",\"苏雨晴的母亲\",\"莫语默\",\"冉空城\"],\"extraGroups\":[{\"kind\":\"side\",\"title\":\"如果有来世，我想做个女孩子\",\"count\":1,\"description\":\"续接正文死亡后的超自然外传：太阴、占卜卡与失去记忆的转生。\"},{\"kind\":\"fang\",\"title\":\"抓不住的幸福 · 方莜莜篇\",\"count\":34,\"description\":\"32篇加终章上下：同居后的压力、橘子往事的反转，以及莜莜与安念的分离。\"},{\"kind\":\"if\",\"title\":\"假如一切都还在\",\"count\":8,\"description\":\"在关键节点改写选择的独立假设；主要伙伴团聚，不代表所有出场人物都存活。\"},{\"kind\":\"prequel\",\"title\":\"在故事开始之前的故事\",\"count\":27,\"description\":\"补足雨晴童年、莫空与曲奇、思凡创伤、父母暗中保护等来历。\"},{\"kind\":\"meta\",\"title\":\"在故事之外的故事\",\"count\":8,\"description\":\"作者以现实素材口吻讲述人物原型相关内容；视为作者附录，不作为已核实真人事实。\"},{\"kind\":\"afterword\",\"title\":\"后记\",\"count\":1,\"description\":\"创作意图、作品关系、更新与致谢。作者文字与正文情节的口径差异也保留。\"}],\"stages\":[{\"title\":\"离开杭州，在小城市活下来\",\"period\":\"2004年春\",\"range\":[1,24],\"text\":\"雨晴离家并没有得到真正的自由通行证。钱会丢、工作会拒收、住处也要靠陌生人的善意才能找到。张阿姨的面馆与第一间出租屋提供了极低但重要的生存起点。莫空的相助并未立刻变成爱情；曲奇的到来则先让她有了不必解释身份的陪伴。她开始以日记和小物件，为自己确认“我仍在生活”。\",\"people\":[\"苏雨晴\",\"张阿姨\",\"莫空\",\"曲奇\"],\"refs\":[\"c001\",\"c004\",\"c006\",\"c008\",\"c014\",\"c020\",\"c022\",\"c024\"]},{\"title\":\"友谊打开了门，风险也随之到来\",\"period\":\"2004年春\",\"range\":[25,80],\"text\":\"论坛上的清泉与月橙相认，雨晴和思凡从熟客变成朋友。百流山、生日、石剑与野餐构成明亮的记忆；街头和酒吧中的暴力则揭示单靠小心并不能避免伤害。李天明的羞辱让她一度绝望，张阿姨的道歉又说明身边的人并非立场一致。父母寻来时她仍以逃离回应，第二次选择出走，告别面馆和第一间出租屋，也放弃了刚建立的安稳。\",\"people\":[\"苏雨晴\",\"张思凡\",\"莫空\",\"李天明\"],\"refs\":[\"c033\",\"c035\",\"c039\",\"c043\",\"c060\",\"c061\",\"c064\",\"c070\",\"c076\",\"c079\",\"c080\"]},{\"title\":\"一间合租屋，暂时组成的家\",\"period\":\"2004年晚春至夏\",\"range\":[81,160],\"text\":\"雨晴住进思凡家，与早已相识的胡玉牛进一步交往，并迎来网友优子——方莜莜。四个人找工作、凑房租、整租白兔小区的六间房，经济分担并不平均，却体现出彼此照顾。雨晴在大润发学会理货与扫码，也遭遇被轻视的同事关系。夕晨搬入后，画纸替两个人表达尚未说出口的亲近。群像主角的各自愿望在同一屋檐下被看见，但药物、创伤、家庭与恋人的秘密还没有真正说开。\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\"],\"refs\":[\"c082\",\"c098\",\"c101\",\"c107\",\"c112\",\"c120\",\"c124\",\"c156\",\"c160\"]},{\"title\":\"海、画像与各自藏起来的愿望\",\"period\":\"2004年夏\",\"range\":[161,240],\"text\":\"雨晴与夕晨的关系在旅行、画作、照料和共同日常中升温；她同时对莫空怀有难以命名的依赖。莜莜在《传奇》中遇见安念；思凡与孙昊的关系表面甜蜜，轻视的征兆已在细节里出现。胡玉牛急于改变身体，但又背着家族武艺传承的责任。莫空的游历、家主往事与偶遇的别墅少女，为日常故事留出更广的悬疑空间。\",\"people\":[\"苏雨晴\",\"林夕晨\",\"莫空\",\"张思凡\",\"孙昊\",\"方莜莜\",\"安念\",\"胡玉牛\"],\"refs\":[\"c161\",\"c173\",\"c178\",\"c189\",\"c198\",\"c200\",\"c202\",\"c205\",\"c208\",\"c211\"]},{\"title\":\"爱情确立之前，另一条路已经被伤害改变\",\"period\":\"2004年夏末至秋\",\"range\":[241,320],\"text\":\"胡玉牛救下柳韵，二人确认爱意；他没有告诉她全部身份愿望。被他重伤的天冲云在家人的强制安排下成为天语遥，经历自伤获救与复杂的妥协，旧仇并未因此消失。雨晴遇到追求者周超，占卜礼物以玩笑和不祥图案提示不同走向。父母一边悄悄看她，一边决定等待她自愿归家，而她还以为自己必须独自承担一切。\",\"people\":[\"胡玉牛\",\"柳韵\",\"天语遥\",\"苏雨晴\",\"周超\",\"莫空\"],\"refs\":[\"c242\",\"c245\",\"c269\",\"c270\",\"c291\",\"c296\",\"c300\",\"c301\",\"c302\",\"c303\"]},{\"title\":\"温柔延续，报复在暗处成形\",\"period\":\"2004年秋冬\",\"range\":[321,400],\"text\":\"莜莜生日的彩虹蛋糕、夕晨的画册、五位合租者的共同生活让人以为日子还会延续。朱雀病死先让雨晴直面一次具体的失去。天语遥重新认出胡玉牛，在旧部、家庭和夏归月之间摇摆，先经历羞辱与自伤获救，再以假和解换取接近他的机会。她已搜集照片、针筒等证据，只是因想好好过年而推迟报复。莜莜则为自己的身体选择迈出重要一步。\",\"people\":[\"方莜莜\",\"安念\",\"苏雨晴\",\"林夕晨\",\"天语遥\",\"胡玉牛\",\"夏归月\"],\"refs\":[\"c328\",\"c329\",\"c332\",\"c354\",\"c359\",\"c363\",\"c365\",\"c376\",\"c380\",\"c398\",\"c399\",\"c400\"]},{\"title\":\"新年里相爱，也在新年里失去一个室友\",\"period\":\"2004年底至2005年初\",\"range\":[401,454],\"text\":\"夕晨与雨晴正式确认恋爱，莜莜的身份也被安念接纳。另一边，天语遥的证据交到柳韵手里；柳韵决定不再主动揭露，却意外把信落在胡家。信被发现后，胡玉牛误认爱人背叛，与父亲决裂、与柳韵分手，又在超市遭公开羞辱。多重压力汇合时，室友未能及时发现危险；他经送医仍未能获救。朋友们为他送行，合租屋开始真正散去。\",\"people\":[\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"安念\",\"胡玉牛\",\"柳韵\",\"天语遥\"],\"refs\":[\"c401\",\"c404\",\"c409\",\"c421\",\"c436\",\"c438\",\"c441\",\"c444\",\"c446\",\"c450\",\"c452\",\"c453\"]},{\"title\":\"报复回到报复者身上，幻觉也无法替代现实\",\"period\":\"2005年春\",\"range\":[455,499],\"text\":\"天语遥越来越依赖幻想中的亲密关系；书中看似与夏归月相聚的一段，随后被明确推翻为幻觉。后来她落入柳韵与蓝色设计的侵害中，莫空指路、黄枸救援，生命得以保住，却长期无法恢复独立生活。昏迷中的投影世界与客机、陶人和叶雯线相交，留下超自然暗示。对于这段，必须区分现实救援、意识世界和原著自身不一致的伤势描述。\",\"people\":[\"天语遥\",\"夏归月\",\"柳韵\",\"蓝色\",\"莫空\",\"黄枸\"],\"refs\":[\"c459\",\"c463\",\"c464\",\"c487\",\"c489\",\"c490\",\"c491\",\"c495\",\"c497\",\"c498\",\"c499\"]},{\"title\":\"离开共同的屋檐，每段爱情接受各自的考验\",\"period\":\"2005年夏秋\",\"range\":[500,560],\"text\":\"雨晴换到加油站谋生；冉空城的探访让旧日好感有机会与现实碰面。莜莜到杭州见安念，后来在宁波同居开店；思凡毕业后更相信自己能与孙昊共同生活。夕晨却为了家庭医疗负担不断向富商妥协，连雨晴以为的廉价新居也有隐情。孙昊终于被思凡撞破背叛，原先的甜言蜜语显露出浅薄与轻慢。\",\"people\":[\"苏雨晴\",\"林夕晨\",\"冉空城\",\"张思凡\",\"孙昊\",\"方莜莜\",\"安念\"],\"refs\":[\"c503\",\"c507\",\"c518\",\"c523\",\"c524\",\"c529\",\"c530\",\"c538\",\"c546\",\"c547\",\"c559\",\"c560\"]},{\"title\":\"夕晨的离去，和活下来的人要面对的生活\",\"period\":\"2005年底至2006年\",\"range\":[561,604],\"text\":\"思凡与孙昊决裂后停止女性化、剪发并埋藏旧物，转回男性身份生活后返乡。雨晴被迫目睹夕晨遭受侵害，为阻止伤害继续而提出替代，自己也遭重创。两人随后获救，但导致痛苦的家庭压力仍未消失。夕晨回乡后遭暴力与禁闭，最终杀害父母后自杀。雨晴在梦中与她告别，随后带着记忆继续生活。宠物店工作和身边人的关照帮助她慢慢恢复；2006年台风夜，咖啡又死去，遗体在送医途中被水冲走，不能误写成已妥善埋葬。\",\"people\":[\"张思凡\",\"苏雨晴\",\"林夕晨\",\"莫空\",\"曲奇\",\"咖啡\"],\"refs\":[\"c561\",\"c566\",\"c571\",\"c572\",\"c575\",\"c577\",\"c582\",\"c584\",\"c585\",\"c587\",\"c595\",\"c603\",\"c604\"]},{\"title\":\"回家不是抹去过去，而是终于能带着过去生活\",\"period\":\"2006年后至2008年\",\"range\":[605,648],\"text\":\"莫空逐渐成为稳定的照顾者和恋人。雨晴交换信物后决定回杭州，用生锈的旧钥匙重新打开家门。父母公开承认她是女儿，支持手术与身份变更；父亲带全家脱离苏家宗族，迁往台湾。她带走夕晨画作、朋友礼物和曲奇，在花莲复学，与杨灵建立新友谊。莫空的小木屋复刻了她曾经贫困的出租屋，将同样的布局变成可以安心停留的地方。\",\"people\":[\"苏雨晴\",\"莫空\",\"苏榕槐\",\"苏雨晴的母亲\",\"苏冬凌\",\"杨灵\"],\"refs\":[\"c608\",\"c617\",\"c618\",\"c620\",\"c622\",\"c625\",\"c628\",\"c633\",\"c634\",\"c638\",\"c642\",\"c645\",\"c648\"]},{\"title\":\"旧友、女儿、婚礼与最后的海边\",\"period\":\"2008—2016年\",\"range\":[649,665],\"text\":\"旧城重访告诉雨晴，许多人已无法照原样找回。张思凡已与董花火成家；两家分别领养兄妹，妹妹成为莫语默。雨晴在婚前梦里见到夕晨，清楚对方已经死去，却也终于愿意带着这段爱继续前行。2011年海边婚礼实现愿望；2016年病痛夺走她的生命，曲奇随之死去。结尾留给莫空与语默的是继续照顾彼此的责任，来生则由正式外传另作回应。\",\"people\":[\"苏雨晴\",\"莫空\",\"莫语默\",\"张思凡\",\"董花火\",\"曲奇\",\"林夕晨\"],\"refs\":[\"c649\",\"c650\",\"c652\",\"c655\",\"c656\",\"c658\",\"c660\",\"c661\",\"c662\",\"c665\",\"x001\"]}],\"fates\":[{\"name\":\"苏雨晴\",\"label\":\"正文死亡；外传转生\",\"tone\":\"red\",\"text\":\"婚后重病，家人与莫空救治未果。正文于2016年4月4日安葬她；死后外传转生为叶洛夜，并失去前世记忆。\",\"note\":\"4月4日在正文是安葬日，后记却称为死亡日；不能无保留写成确定死亡日期。\",\"refs\":[\"c665\",\"x001\",\"x079\"]},{\"name\":\"莫空\",\"label\":\"存活，继续抚养女儿\",\"text\":\"与雨晴结婚并共同领养语默。雨晴死后安葬她与曲奇，承诺代她照顾女儿。\",\"note\":\"第三十九次轮回等线索没有完整解释；最后未能挽救雨晴。\",\"refs\":[\"c650\",\"c656\",\"c662\",\"c665\"]},{\"name\":\"林夕晨\",\"label\":\"正文死亡\",\"tone\":\"red\",\"text\":\"回乡后遭父亲暴力与禁闭、母亲未能保护，最终杀害父母后自杀。警方与新闻在后文确认死讯。\",\"note\":\"山村旅行与短暂醒来是雨晴的梦；c660再见仍是梦。不能写成现实复活。\",\"refs\":[\"c581\",\"c582\",\"c584\",\"c586\",\"c587\",\"c660\"]},{\"name\":\"胡玉牛\",\"label\":\"抢救无效死亡\",\"tone\":\"red\",\"text\":\"秘密暴露后承受家庭拒绝、误会分手和职场羞辱。自伤后被发现仍有呼吸，但送医抢救无效。\",\"note\":\"柳韵曾决定放下报复，信在胡家被发现源于遗落；这不等于她主动把信交给胡父母。\",\"refs\":[\"c438\",\"c441\",\"c444\",\"c446\",\"c448\",\"c450\"]},{\"name\":\"天语遥\",\"label\":\"存活，长期需照护\",\"text\":\"经历强迫、复仇、自伤与严重侵害，获救后长期无法独立生活。末次回访由父母与夏归月照顾，只有短暂回应和好转希望。\",\"note\":\"她最初的女性化并非自愿；后续的复杂选择与依恋也应保留。原著的精神医学说法只作文本记录。\",\"refs\":[\"c296\",\"c302\",\"c487\",\"c490\",\"c499\",\"c649\",\"c650\"]},{\"name\":\"夏归月\",\"label\":\"继续陪伴天语遥\",\"text\":\"多次寻找失联的天语遥，获知其病况后仍选择陪伴。雨晴后来回城时，她仍在照护对方。\",\"note\":\"早前有几段幻觉中的相聚，但c479重逢及c650照护属于真实正文。\",\"refs\":[\"c376\",\"c463\",\"c468\",\"c479\",\"c499\",\"c650\"]},{\"name\":\"张思凡\",\"label\":\"婚后收养，开始新生活\",\"tone\":\"green\",\"text\":\"与孙昊决裂后停止女性化，回家并恢复男性社会生活。后来与董花火结婚，在福利院收养林清雾。\",\"note\":\"按经历阶段记录身份与原文代词，不把个人选择上升为所有人的“正确答案”。\",\"refs\":[\"c560\",\"c561\",\"c580\",\"c652\",\"c656\"]},{\"name\":\"董花火\",\"label\":\"与张思凡成家\",\"tone\":\"green\",\"text\":\"相亲中主动靠近张思凡，后成为妻子，接纳其不育，并与他共同领养林清雾；张思凡仍没有告诉她过往的转变经历。\",\"note\":\"收养时与雨晴、莫空成为两家有关联的父母；不是孙昊的另一伴侣。\",\"refs\":[\"c580\",\"c652\",\"c656\"]},{\"name\":\"方莜莜\",\"label\":\"外传获救，离开安念\",\"text\":\"正文与安念同居开店；正式外传中难以承受隐秘恋人和被催婚的处境，自杀未遂后由橘子救援。二人均活下来，她拒见安念，关系结束。\",\"note\":\"未写她与橘子确立恋爱，也不能把雨晴早年的死亡噩梦当作莜莜终局。\",\"refs\":[\"c338\",\"c538\",\"c562\",\"x034\",\"x035\"]},{\"name\":\"安念\",\"label\":\"与莜莜分离\",\"text\":\"在家庭压力下参加与苏凝的相亲；莜莜获救后退出他的生活。苏凝继续陪伴，他逐渐接受分离，仍无法忘记莜莜。\",\"note\":\"正式外传没有写他已经与苏凝结婚；与莜莜的现实婚礼只在幸福IF中出现；正文另有《传奇》游戏婚礼。\",\"refs\":[\"c382\",\"x033\",\"x034\",\"x035\",\"x042\",\"x043\"]},{\"name\":\"橘子\",\"label\":\"救援后存活\",\"text\":\"本名田桔，跨性别男性。受创记忆在外传被澄清；后来救下莜莜，两人一同获救出院。他与安念绝交并继续保护莜莜。\",\"note\":\"张诚是学长，姜琳活着转学；此前的神怪故事含记忆改写。\",\"refs\":[\"x028\",\"x034\",\"x035\"]},{\"name\":\"苏凝\",\"label\":\"继续陪伴安念\",\"text\":\"在相亲中与安念相识，莜莜离开后给予陪伴，双方家人认可这段发展。\",\"note\":\"原著未写确定结婚日期或正式成婚，不补写婚后生活。\",\"refs\":[\"x035\"]},{\"name\":\"柳韵\",\"label\":\"复仇后个人去向未明\",\"text\":\"失去胡玉牛后策动对天语遥的报复，后来仍到胡玉牛衣冠冢前悼念。她本人是否被司法追责、此后去向均未交代。\",\"note\":\"第499章未具名的主谋、从犯判决不能直接对应到柳韵；第588章仍写她亲自前往墓园悼念。\",\"refs\":[\"c444\",\"c450\",\"c487\",\"c499\",\"c588\"]},{\"name\":\"莫语默\",\"label\":\"存活，由莫空继续照顾\",\"text\":\"原名林清云，林清雾的双胞胎妹妹，被雨晴和莫空收养后迁台生活。母亲死后由莫空继续抚养。\",\"note\":\"是领养女儿；IF中的亲生女儿叫苏慕夕，不能互换。\",\"refs\":[\"c653\",\"c656\",\"c657\",\"c665\",\"x043\"]},{\"name\":\"林清雾\",\"label\":\"由张思凡夫妇收养\",\"text\":\"与妹妹林清云相依为命，经过协商后由张思凡与董花火收养，妹妹随另一家庭生活。\",\"note\":\"原著写莫空拒绝同收兄妹，并留下说服过程的记忆空白；未完整解释所谓不良未来。\",\"refs\":[\"c652\",\"c653\",\"c655\",\"c656\"]},{\"name\":\"曲奇\",\"label\":\"守墓三天后死亡\",\"tone\":\"red\",\"text\":\"陪伴雨晴多年的黑猫。雨晴安葬后反复回墓前、拒绝食物，三天后死亡，被莫空葬在雨晴旁。\",\"note\":\"早期称母猫、后期及前传称公猫，原文前后不一致。台湾段与白猫糯米相伴，后文提及后代。\",\"refs\":[\"c024\",\"c643\",\"c662\",\"c665\"]},{\"name\":\"咖啡\",\"label\":\"台风夜死亡\",\"tone\":\"red\",\"text\":\"原本被曲奇带回的幼鼠，灰毛随换毛逐渐转紫，后来成为长期伙伴。2006年台风夜老去死亡；雨晴送医途中其遗体被排水冲走。\",\"note\":\"未找到遗体，不写成与雨晴或曲奇一同埋葬。\",\"refs\":[\"c046\",\"c603\",\"c604\"]},{\"name\":\"朱雀\",\"label\":\"病死并被埋葬\",\"tone\":\"red\",\"text\":\"雨晴购买并取名的染红雏鸡，后来病死，被她与曲奇、咖啡一起埋在小区绿化处。\",\"note\":\"它的死亡先于几条重大人物悲剧，让雨晴直接触到生命有限。\",\"refs\":[\"c310\",\"c328\"]},{\"name\":\"糯米\",\"label\":\"与曲奇相伴，未交代死亡\",\"text\":\"台湾阶段出现的异瞳白猫，与曲奇相伴；后文提到曲奇繁衍后代。\",\"note\":\"文本没有给出糯米的最终死亡，不随曲奇一并推定。\",\"refs\":[\"c643\",\"c662\"]},{\"name\":\"黑皇\",\"label\":\"由秋易收养，后续仍在\",\"text\":\"天语遥曾亲近的大黑犬，后来被秋易收养，由莫空命名黑皇。旧城回访时与秋易出现。\",\"note\":\"第348章叙述已提前称它黑皇，后文第590章才呈现莫空取名；另与小黑及投影线索有关，完整机制未说明。\",\"refs\":[\"c589\",\"c590\",\"c650\"]},{\"name\":\"苏榕槐\",\"label\":\"支持女儿，迁台经营\",\"text\":\"从开篇暴力拒绝到后期公开接纳，脱离宗族并带全家迁台，支持女儿复学、成家，也在她病重时尽力救治。\",\"note\":\"脱离苏家仍保有一千万及台湾公司，并非破产；后来的弥补不抹去开篇伤害。\",\"refs\":[\"c001\",\"c621\",\"c622\",\"c633\",\"c659\",\"c665\"]},{\"name\":\"苏雨晴的母亲\",\"label\":\"支持女儿，经历丧女\",\"text\":\"由最初不能接受到暗中关注、公开团圆，参与女儿的迁居、手术与婚礼。雨晴病重时奔走照顾，最终经历丧女。\",\"note\":\"“圆圆”为亲属称呼；按母亲身份统一，不凭空扩展实名。\",\"refs\":[\"c303\",\"c620\",\"c625\",\"c661\",\"c665\",\"x064\"]},{\"name\":\"苏雨晴的大舅\",\"label\":\"持续提供家庭支持\",\"text\":\"此前以“大伯”出现的苏书记，是母系长辈，并与苏父另有远房亲缘。暗中照看雨晴，在受害事件中动用资源救援并给予资助。\",\"note\":\"c573作者已把“大伯”更正为“大舅”，不是两个不同的人。\",\"refs\":[\"c524\",\"c548\",\"c573\",\"c574\",\"x064\"]},{\"name\":\"冉空城\",\"label\":\"退为普通朋友，另有女友\",\"text\":\"初中时保护雨晴，是发卡与电话号码的来源。后来探访并重逢，至雨晴归家后告知已有女友；雨晴也认清旧日好感。\",\"note\":\"不是雨晴最终伴侣；没有死亡或失踪结局。\",\"refs\":[\"c113\",\"c124\",\"c525\",\"c529\",\"c630\"]},{\"name\":\"孙昊\",\"label\":\"与张思凡决裂\",\"text\":\"背着思凡与他人交往，遭撞破后承认浅薄动机并羞辱对方。思凡离开，二人关系结束。\",\"note\":\"后续人生未给完整交代；没有凭原文写出悔悟、死亡或复合。\",\"refs\":[\"c469\",\"c546\",\"c559\",\"c560\",\"c561\"]},{\"name\":\"孔雀\",\"label\":\"被捕并判刑（书内情节）\",\"text\":\"星辰诊所相关人物，参与提供药物与手术。患者事件后被捕，后文叙述被判十年并承担赔偿。\",\"note\":\"只作原著案件结果，不把群聊对患者动机的猜测、书内法律解释当现实法理。\",\"refs\":[\"c205\",\"c398\",\"c576\",\"c583\"]},{\"name\":\"李任飞\",\"label\":\"被抓，具体后判未明\",\"text\":\"对夕晨及雨晴实施侵害的富商。大舅获报后组织救援，他被抓，相关人物要求严办。\",\"note\":\"与较早供养夕晨的秃顶富商是两个人；正文未在所引后续中给出明确刑期。\",\"refs\":[\"c566\",\"c572\",\"c573\"]},{\"name\":\"风羽蓝\",\"label\":\"与金家辉相恋\",\"text\":\"风音的妹妹、小蓝，宠物店后期出场，已完成自己的身份与身体相关选择，与金家辉保持恋爱关系。\",\"note\":\"与天语遥投影中祝福的“小蓝与少年”高度疑似对应，但身份同一性没有直接说出，完整机制亦未说明。\",\"refs\":[\"c497\",\"c595\",\"c596\",\"c599\",\"c600\",\"c613\"]},{\"name\":\"张诚\",\"label\":\"真实往事中遇难\",\"tone\":\"red\",\"text\":\"橘子的大学学长，追求橘子，在游乐园事故中为救他而死。\",\"note\":\"外传最初“道士”的形象是橘子改写记忆的一部分，x028给出真实身份。\",\"refs\":[\"x014\",\"x016\",\"x028\"]},{\"name\":\"姜琳\",\"label\":\"真实往事中存活离校\",\"text\":\"橘子的学妹，曾拒绝他的感情；因病转学返乡。\",\"note\":\"被黑雾附身、坠入深渊等讲述不是已确认的真实结局。\",\"refs\":[\"x009\",\"x015\",\"x028\"]},{\"name\":\"太阴\",\"label\":\"外传中的九尾神\",\"text\":\"在雨晴死后通过占卜卡显现，说明无法复活她或夕晨，但帮助她转生为女孩子。\",\"note\":\"属于明确超自然外传，不能由此推导现实医疗或生死机制。\",\"refs\":[\"x001\"]},{\"name\":\"叶洛夜\",\"label\":\"外传中的新生身份\",\"text\":\"雨晴转生为2010年出生的龙凤胎女儿，名字叶洛夜，兄弟叫秋叶；前世记忆随后完全消失。\",\"note\":\"父母在此篇没有实名；不要擅自把跨作品人物信息补入。\",\"refs\":[\"x001\"]}],\"alternatives\":[{\"name\":\"苏雨晴 × 林夕晨\",\"canon\":\"夕晨在返乡悲剧中死亡。雨晴后来与莫空成家，最后也病逝；夕晨在她后来的梦中仍被记念。\",\"alternate\":\"IF改写返乡及家庭冲突的后果，夕晨存活，并与雨晴结婚。结尾有亲生女儿苏慕夕。\",\"refs\":[\"c582\",\"c665\",\"x039\",\"x040\",\"x041\",\"x043\"]},{\"name\":\"方莜莜 × 安念\",\"canon\":\"正式外传以莜莜获救、拒见安念和两人分离结束。苏凝陪在安念身边，未写已经成婚。\",\"alternate\":\"IF让两人选择继续同行，并与雨晴、夕晨举办双婚礼；其间仍有安念父母车祸死亡的情节。\",\"refs\":[\"x035\",\"x042\",\"x043\"]},{\"name\":\"胡玉牛 × 柳韵\",\"canon\":\"误会分手、家庭与工作压力共同推动阿牛陷入危机，最终抢救无效；柳韵继而复仇。\",\"alternate\":\"IF在关键时刻让阿牛获救，柳韵给予接纳，悲剧链被改写。\",\"refs\":[\"c444\",\"c450\",\"c487\",\"x036\",\"x043\"]},{\"name\":\"天语遥 × 夏归月\",\"canon\":\"复仇引出更大伤害，天语遥长期需人照护，夏归月坚持陪伴。\",\"alternate\":\"IF让她选择放下复仇，与夏归月到外地读大学，生活有了别的方向。\",\"refs\":[\"c380\",\"c487\",\"c499\",\"c650\",\"x037\",\"x043\"]},{\"name\":\"张思凡\",\"canon\":\"孙昊背叛后他回到男性社会生活，后来与董花火结婚并领养孩子。\",\"alternate\":\"IF让她在失恋后回到朋友们身边，继续女性生活，并参加朋友们的婚礼。\",\"refs\":[\"c561\",\"c652\",\"c656\",\"x038\",\"x043\"]},{\"name\":\"莫空与孩子\",\"canon\":\"莫空是雨晴的丈夫和养父；女儿为林清云改名的莫语默。\",\"alternate\":\"莫空在IF承担联系、送信与婚礼仪式角色；雨晴和夕晨的亲生女儿是苏慕夕。\",\"refs\":[\"c656\",\"c662\",\"c665\",\"x040\",\"x043\"]}],\"layerCases\":[{\"title\":\"雨晴梦中的未来，不是人物死亡名单\",\"layer\":\"main\",\"text\":\"c338把胡玉牛、方莜莜、林夕晨、张思凡等人的悲惨结局放进同一个噩梦。后文有的现实与它呼应，有的并未照此发生。每个人的最终命运必须另查正文与外传，不能按梦中画面逐一判死。\",\"refs\":[\"c338\",\"c450\",\"c561\",\"c582\",\"x035\"]},{\"title\":\"天语遥的团聚：幻觉版本与真实重逢\",\"layer\":\"main\",\"text\":\"c459—462看似遇见夏归月、向父亲公开关系并一起吃饭；c463明确揭为幻觉改写。c468又有一段梦。c479才发生真实重逢，c480予以延续。\",\"refs\":[\"c459\",\"c460\",\"c461\",\"c462\",\"c463\",\"c468\",\"c479\",\"c480\"]},{\"title\":\"夕晨的两次“再见”，都没有撤销死亡\",\"layer\":\"main\",\"text\":\"c585—586的乘飞机赴山村与短暂苏醒告别，在结尾揭为雨晴仍躺在长椅上的梦；c660婚前再见夕晨时，雨晴主动承认现实中的她已经死去。\",\"refs\":[\"c584\",\"c585\",\"c586\",\"c587\",\"c660\"]},{\"title\":\"投影世界、客机与第三十九次轮回\",\"layer\":\"main\",\"text\":\"天语遥昏迷中的意识世界与JL6910、陶人、叶雯和黑犬发生交叉；后文莫空与秋易谈轮回和改写历史，再以小说对话解释。这些是有文本支持的超自然悬疑，完整规则、代价与人物背景并未一一交代。\",\"refs\":[\"c491\",\"c493\",\"c495\",\"c497\",\"c498\",\"c588\",\"c590\",\"c650\"]},{\"title\":\"橘子的神怪回忆，被后文重新解释\",\"layer\":\"fang\",\"text\":\"方莜莜外传先让橘子讲述恋情、鬼屋与道士。x028说明他受创后改写了部分记忆：姜琳拒绝他的感情、因病转学；张诚是救他而死的学长。不能把早段惊悚叙事当成无条件可靠的往事。\",\"refs\":[\"x004\",\"x014\",\"x016\",\"x027\",\"x028\"]},{\"title\":\"叶洛夜是死后外传中的转生，不是原身复活\",\"layer\":\"side\",\"text\":\"x001明确续接死亡，通过太阴的力量令雨晴在另一个年份以新生儿身份开始生命。她没有带着完好的记忆返回莫空身边，夕晨也没有因此复活。\",\"refs\":[\"c665\",\"x001\"]}],\"timeline\":[{\"label\":\"童年—出走前\",\"certainty\":\"前传与回忆\",\"items\":[{\"title\":\"愿望、创伤与关系的来历\",\"text\":\"雨晴的童年、早期性别愿望与家庭生活；莫空的幼年和游历；曲奇的流浪；思凡、夕晨与胡玉牛各自的家庭前史。前传补足原因，不改变它在原书中属于后置补充的阅读位置。\",\"refs\":[\"x044\",\"x045\",\"x048\",\"x052\",\"x059\",\"x061\",\"x063\",\"x066\",\"x067\"]}]},{\"label\":\"2004年3月\",\"certainty\":\"明确日期与相对推算\",\"items\":[{\"title\":\"离家、面馆与第一间小屋\",\"text\":\"雨晴15岁从杭州出走，3月6日日记与3月7日、3月8日事件构成早期明确日期锚点。出走约在3月初，具体日不能只凭推算说成原文直述。\",\"refs\":[\"c001\",\"c014\",\"c017\",\"c019\"]},{\"title\":\"3月15日，张思凡20岁生日\",\"text\":\"清泉与月橙在现实认出彼此，百流山之行和生日祝福建立姐妹般的友谊。\",\"refs\":[\"c035\",\"c036\",\"c043\"]}]},{\"label\":\"2004年4—6月\",\"certainty\":\"明确日期及阶段\",\"items\":[{\"title\":\"第二次出走与合租生活\",\"text\":\"4月29日发薪前后，父母来到小城市。雨晴离开面馆，先住进思凡家；四人随后搬入白兔小区并开始各自工作。\",\"refs\":[\"c076\",\"c079\",\"c080\",\"c107\",\"c112\"]},{\"title\":\"林夕晨入住\",\"text\":\"进入六月后的同住与绘画交流，让夕晨成为雨晴生活中新的重心。\",\"refs\":[\"c135\",\"c156\",\"c160\"]}]},{\"label\":\"2004年夏末秋冬\",\"certainty\":\"日期与叙述顺序\",\"items\":[{\"title\":\"几段亲密关系与复仇的开端\",\"text\":\"胡玉牛与柳韵相爱；天冲云受伤后被强迫改变生活并改名天语遥。莜莜与安念在网络相识，9月生日蛋糕加深依赖。\",\"refs\":[\"c291\",\"c296\",\"c300\",\"c302\",\"c332\"]},{\"title\":\"证据搜集与手术选择\",\"text\":\"天语遥逐步搜集针对胡玉牛的材料；莜莜完成自己的手术选择，与安念的关系走向坦白。\",\"refs\":[\"c380\",\"c398\",\"c399\",\"c400\",\"c401\"]}]},{\"label\":\"2005年春节前后\",\"certainty\":\"正文顺序\",\"items\":[{\"title\":\"雨晴与夕晨确认恋爱\",\"text\":\"除夕心意与大年初一的明确回应，让两人从亲密室友成为恋人。\",\"refs\":[\"c420\",\"c421\"]},{\"title\":\"胡玉牛之死、合租屋散去\",\"text\":\"证据信件意外留在胡家，暴露、误解、决裂和职场羞辱相继发生。阿牛送医后死亡，朋友们为他处理后事并开始搬离。\",\"refs\":[\"c436\",\"c438\",\"c441\",\"c446\",\"c450\",\"c453\"]}]},{\"label\":\"2005年春\",\"certainty\":\"含4月明确锚点\",\"items\":[{\"title\":\"天语遥获救，但长期需要照护\",\"text\":\"柳韵报复造成严重侵害，莫空与黄枸帮助救出天语遥。其意识世界与4月2日失联、4月3日报道的JL6910航班线索交叉；现实中她出院后由亲友继续照顾。\",\"refs\":[\"c487\",\"c489\",\"c490\",\"c491\",\"c495\",\"c499\"]}]},{\"label\":\"2005年夏秋冬\",\"certainty\":\"正文明确阶段\",\"items\":[{\"title\":\"相见、同居与背叛\",\"text\":\"莜莜赴杭州为安念庆生，后在宁波同居开店；雨晴换工作，与夕晨独立居住。孙昊的双重交往最终被思凡撞破。\",\"refs\":[\"c507\",\"c518\",\"c538\",\"c546\",\"c559\",\"c560\",\"c562\"]},{\"title\":\"林夕晨陷入更严重的剥削\",\"text\":\"家庭治疗费用加重，夕晨试图独自承担；雨晴发现后卷入危险，大舅获报救援。\",\"refs\":[\"c566\",\"c571\",\"c572\",\"c573\",\"c574\"]}]},{\"label\":\"2006年春节前后\",\"certainty\":\"1月20日返乡明确\",\"items\":[{\"title\":\"林夕晨返乡后死亡\",\"text\":\"夕晨带治疗费用回家，却遭拒绝与暴力。她与父母死亡，警方和新闻先后确认；雨晴以梦中告别处理无法承受的失去。\",\"refs\":[\"c575\",\"c581\",\"c582\",\"c584\",\"c586\",\"c587\"]}]},{\"label\":\"2006年夏—迁台\",\"certainty\":\"年份存在衔接疏漏\",\"items\":[{\"title\":\"咖啡死亡、莫空成为伴侣、归家\",\"text\":\"c602写2006年台风，c616写7月15日生日；之后雨晴回杭州。原文同时反复称“三年”，但2004年到2006年并非完整三年，故不强行修正。\",\"refs\":[\"c602\",\"c604\",\"c613\",\"c616\",\"c617\",\"c619\",\"c620\"]},{\"title\":\"手术、脱离宗族与迁居台湾\",\"text\":\"家人支持雨晴赴美手术，随后脱离大陆苏家、迁到台湾。c641又明确写2007年；具体跨年衔接原文不够一致。\",\"refs\":[\"c625\",\"c628\",\"c633\",\"c634\",\"c636\",\"c641\"]}]},{\"label\":\"2008年\",\"certainty\":\"春节与汶川地震锚点\",\"items\":[{\"title\":\"复学、回访与收养\",\"text\":\"2月6日除夕与花莲高中入学之后，雨晴回访旧城。福利院收养线把她、莫空与张思凡夫妇再度连起来，林清云成为莫语默。\",\"refs\":[\"c643\",\"c645\",\"c649\",\"c651\",\"c652\",\"c656\",\"c657\"]}]},{\"label\":\"2011年7月23日\",\"certainty\":\"正文明确\",\"items\":[{\"title\":\"苏家村海边婚礼\",\"text\":\"领养约三年后，雨晴高中毕业，莫空在父亲公司承担重任，两人在亲友见证下成婚。\",\"refs\":[\"c658\",\"c659\",\"c661\",\"c662\"]}]},{\"label\":\"2016年春\",\"certainty\":\"4月4日安葬明确\",\"items\":[{\"title\":\"雨晴病逝，曲奇随后死亡\",\"text\":\"救治未果后，正文以4月4日安葬雨晴、三天后曲奇死亡收束。后记把4月4日称作死亡日，与正文口径有差别。莫空继续照顾语默。\",\"refs\":[\"c665\",\"x079\"]}]},{\"label\":\"2010年 · 外传\",\"certainty\":\"超自然倒退时间\",\"items\":[{\"title\":\"叶洛夜诞生\",\"text\":\"死后外传让雨晴转生到2010年的龙凤胎家庭，随后失去前世记忆。这不处在通常顺向推进的主线时间轴内。\",\"refs\":[\"x001\"]}]}],\"processes\":[{\"name\":\"苏雨晴：寻找能安心生活的地方\",\"description\":\"既是身份的过程，也是从被照顾到照顾别人的过程。\",\"steps\":[{\"title\":\"离家求生\",\"text\":\"靠工作与陌生人的帮助建立最初生活。\",\"refs\":[\"c001\",\"c006\",\"c008\"]},{\"title\":\"共同生活与相爱\",\"text\":\"在合租屋、画作与节日中找到朋友和夕晨。\",\"refs\":[\"c112\",\"c160\",\"c421\"]},{\"title\":\"失去与继续\",\"text\":\"朋友离散、夕晨死亡，她保存遗物并恢复日常。\",\"refs\":[\"c450\",\"c561\",\"c584\",\"c587\",\"c595\"]},{\"title\":\"归家与重建\",\"text\":\"父母接纳、迁台复学，与莫空建立稳定生活。\",\"refs\":[\"c620\",\"c633\",\"c645\"]},{\"title\":\"母亲、妻子与终局\",\"text\":\"收养语默并成婚，最终病逝，爱留给继续生活的人。\",\"refs\":[\"c656\",\"c662\",\"c665\"]}]},{\"name\":\"胡玉牛—柳韵—天语遥：报复怎样继续制造伤害\",\"description\":\"图中串起因果，不等于为任何一方的暴力开脱。\",\"steps\":[{\"title\":\"侵害与反击\",\"text\":\"柳韵受威胁，阿牛反击使天冲云重伤。\",\"refs\":[\"c245\",\"c295\"]},{\"title\":\"强迫与仇恨\",\"text\":\"家人强迫女性化、后续羞辱与失控，仇恨转向阿牛。\",\"refs\":[\"c296\",\"c363\",\"c380\"]},{\"title\":\"揭露与误会\",\"text\":\"证据流转、信件意外被发现，关系接连断裂。\",\"refs\":[\"c436\",\"c438\",\"c441\",\"c444\"]},{\"title\":\"阿牛死亡\",\"text\":\"职场公开羞辱后陷入危机，送医抢救无效。\",\"refs\":[\"c446\",\"c448\",\"c450\"]},{\"title\":\"新的复仇与照护\",\"text\":\"柳韵报复天语遥，获救者长期需要父母和归月照顾。\",\"refs\":[\"c487\",\"c490\",\"c499\",\"c650\"]}]},{\"name\":\"林夕晨：沉默的照料与无法独自承担的家庭\",\"description\":\"她的温柔与隐瞒源于同一个被压迫的生活处境。\",\"steps\":[{\"title\":\"逃离家庭\",\"text\":\"离开暴力家庭，成为雨晴的室友与画友。\",\"refs\":[\"c156\",\"c178\"]},{\"title\":\"承担与隐瞒\",\"text\":\"持续汇款，为治疗费用接受剥削，并瞒住爱人。\",\"refs\":[\"c409\",\"c523\",\"c547\"]},{\"title\":\"相爱却仍受困\",\"text\":\"恋爱成立后仍要独自承担更大的费用与伤害。\",\"refs\":[\"c421\",\"c566\",\"c571\"]},{\"title\":\"返乡悲剧\",\"text\":\"带钱回家仍不被接纳，最终与父母共同死亡。\",\"refs\":[\"c575\",\"c581\",\"c582\",\"c584\"]},{\"title\":\"留在画与记忆里\",\"text\":\"现实未复活，雨晴在后续梦中与她告别、谈生活。\",\"refs\":[\"c586\",\"c587\",\"c660\"]}]},{\"name\":\"方莜莜与安念：网络里的亲密怎样走到现实\",\"description\":\"正式外传给出后续，幸福IF提供另一种假设。\",\"steps\":[{\"title\":\"游戏相识\",\"text\":\"优子与有条色狼在《传奇》中认识，关系逐渐亲近。\",\"refs\":[\"c151\",\"c152\",\"c173\"]},{\"title\":\"坦白与接纳\",\"text\":\"安念知晓身份后仍接纳，双方约定现实见面。\",\"refs\":[\"c332\",\"c401\"]},{\"title\":\"相见、同居、开店\",\"text\":\"一起谋生，把网络恋爱变成共同生活。\",\"refs\":[\"c507\",\"c538\",\"c562\"]},{\"title\":\"家庭压力与退出\",\"text\":\"外传里相亲及婚育压力无法化解；莜莜获救后离开。\",\"refs\":[\"x032\",\"x033\",\"x034\",\"x035\"]},{\"title\":\"假设分支\",\"text\":\"IF选择继续共同争取生活，并走向婚礼。\",\"refs\":[\"x042\",\"x043\"]}]}],\"mapRegions\":[{\"label\":\"ORIGIN & RETURN\",\"title\":\"杭州与苏家\",\"text\":\"离家的出发地、重新被接纳的家，以及需要脱离的宗族。\",\"places\":[\"杭州\",\"火车城站\",\"苏雨晴的家\",\"西湖\",\"南屏山\",\"苏家镇\"]},{\"label\":\"THE CITY OF ENCOUNTERS\",\"title\":\"“小城市”生活圈\",\"text\":\"主要群像相遇、谋生、同住、分离的核心叙事空间。\",\"places\":[\"面馆\",\"第一间出租屋\",\"笃头村\",\"白兔小区\",\"大润发\",\"百流山\",\"集装箱房\",\"加油站\",\"风音宠物店\"]},{\"label\":\"NEW HOME & OTHER PATHS\",\"title\":\"台湾与外地道路\",\"text\":\"重建生活的海边，以及其他人物为爱情、工作和治疗走过的城市。\",\"places\":[\"花莲\",\"苏家村\",\"花莲高中\",\"莫空的小木屋\",\"富阳金盈儿童福利院\",\"武汉\",\"宁波\",\"芝加哥\"]}],\"journeys\":[{\"name\":\"苏雨晴的主线迁移\",\"description\":\"出走、共同生活、独居、归家与迁台\",\"primary\":true,\"steps\":[{\"place\":\"杭州 → 小城市\",\"text\":\"2004年离家，面馆与出租屋构成第一处落脚点。\",\"refs\":[\"c001\",\"c002\",\"c006\",\"c008\"]},{\"place\":\"笃头村 → 白兔小区\",\"text\":\"避开父母寻访，随后与伙伴合租并工作。\",\"refs\":[\"c080\",\"c082\",\"c112\"]},{\"place\":\"集装箱房 / 海景住处\",\"text\":\"共同的家散去后与夕晨生活，逐渐面对独居与失去。\",\"refs\":[\"c453\",\"c454\",\"c539\",\"c547\",\"c584\"]},{\"place\":\"杭州 → 芝加哥 → 杭州\",\"text\":\"归家获接纳，家人陪同手术，莫空在国内等候。\",\"refs\":[\"c620\",\"c625\",\"c628\"]},{\"place\":\"苏家镇 → 台湾花莲\",\"text\":\"脱离宗族，办理新身份，复学并重建家庭。\",\"refs\":[\"c633\",\"c634\",\"c645\"]},{\"place\":\"小城市 / 富阳 → 海边\",\"text\":\"回访、收养、婚礼与终局；海边是愿望与悼念共同归处。\",\"refs\":[\"c649\",\"c652\",\"c656\",\"c661\",\"c665\"]}]},{\"name\":\"方莜莜与安念的现实路线\",\"description\":\"两地相识之后，把生活搬到一起\",\"steps\":[{\"place\":\"小城市合租屋与诊所\",\"text\":\"莜莜以优子的名字进入游戏并结识安念；后在小城孔雀诊所作出身体相关选择。\",\"refs\":[\"c112\",\"c151\",\"c173\",\"c398\"]},{\"place\":\"武汉附近家乡 → 武汉工作\",\"text\":\"离开合租生活后住在武汉附近未具名地级市的城中村，后来到武汉新单位工作、乘公交往返。\",\"refs\":[\"c457\",\"c469\"]},{\"place\":\"杭州\",\"text\":\"莜莜赴安念所在城市，生日相见并确认现实感情。\",\"refs\":[\"c507\",\"c518\"]},{\"place\":\"宁波；外传又称海宁\",\"text\":\"正文在宁波同居开奶茶店；正式外传主体场景又称海宁，并面临家庭压力。原文未明确交代两地间搬迁，保留地点口径差异。\",\"refs\":[\"c538\",\"c562\",\"x002\",\"x032\",\"x033\",\"x035\"]}]},{\"name\":\"林夕晨的现实路线与梦中路线\",\"description\":\"特别区分真实返乡与雨晴幻想中的山村告别\",\"steps\":[{\"place\":\"农村家庭 → 小城市\",\"text\":\"她离开压迫性的家庭，以插画和工作维系生活。\",\"refs\":[\"c156\",\"c178\",\"c313\"]},{\"place\":\"合租屋 → 与雨晴同住\",\"text\":\"关系成为恋爱，家庭汇款与供养关系仍被隐瞒。\",\"refs\":[\"c421\",\"c539\",\"c547\"]},{\"place\":\"真实返乡\",\"text\":\"带着治疗费用回家，悲剧随后发生。\",\"refs\":[\"c575\",\"c581\",\"c582\"]},{\"place\":\"雨晴的长椅梦\",\"text\":\"飞往山村、墓地与短暂醒来均是梦中告别，不加入真实旅行地图。\",\"refs\":[\"c585\",\"c586\"]},{\"place\":\"婚前梦中公园与夜市\",\"text\":\"夕晨留在雨晴的记忆里；这是悼念空间。\",\"refs\":[\"c660\"]}]}],\"themes\":[{\"title\":\"被接纳，往往发生在很具体的小事里\",\"text\":\"面馆的一份饭、肯让人入住的房间、交换便当的同学、接住一封未说完的求助，都比抽象善意更有分量。小说把接纳写进生活的入口：能否工作、能否回家、能否以希望的身份被称呼。其反面同样具体，是关门、羞辱、退让与不相信。\",\"refs\":[\"c006\",\"c064\",\"c112\",\"c620\",\"c622\",\"c647\"]},{\"title\":\"共同生活可以像家，也承受不起所有问题\",\"text\":\"合租屋并非能永久遮挡世界的理想国。伙伴们能分担房租、教做饭和送礼，却不总能看见另一个人的秘密与危机。阿牛之死和此后的搬离，使这个临时家庭的美好与局限同时显露。\",\"refs\":[\"c112\",\"c156\",\"c188\",\"c449\",\"c450\",\"c453\"]},{\"title\":\"爱与控制的界线\",\"text\":\"以“为你好”为名的强迫、不允许对方选择的家庭安排、要求爱人隐瞒身份的关系，都可能把关心变成支配。夏归月的陪伴、父亲后来的公开支持和雨晴尊重孤儿意愿，提供了其他形式的爱；但它们也没有让过去伤害自动消失。\",\"refs\":[\"c001\",\"c296\",\"c499\",\"c622\",\"c633\",\"c655\"]},{\"title\":\"身份不是一条人人必须走到同处的线\",\"text\":\"苏雨晴主动追求的生活、天语遥最初被迫承受的安排、胡玉牛尚未完成的愿望和张思凡后来的选择，彼此不能替代。文学分析应保留人物差别，而不照搬原著某些片面、病理化或贬损性的群体判断。\",\"refs\":[\"c098\",\"c296\",\"c302\",\"c450\",\"c561\",\"c624\",\"c652\"]},{\"title\":\"旁观者看到的幸福，可能以隐瞒维持\",\"text\":\"雨晴看到夕晨温柔的日常，却很晚才知道费用、供养和受虐背后的压力；她以为自己无人保护，读者却逐步知道父母的暗中安排。叙事利用这种信息差，让看似稳定的生活随真相改变意义。\",\"refs\":[\"c303\",\"c409\",\"c523\",\"c547\",\"c548\",\"c571\",\"x064\"]},{\"title\":\"记住一个人，与继续活着可以同时成立\",\"text\":\"雨晴曾把幸福理解为绝不分离，后来才在梦中承认夕晨已死，同时继续把她带进自己的画与生活。结尾莫空对语默的承诺，延续的也是这种爱：死亡终止共同的日常，却没有取消活着的人对彼此的责任。\",\"refs\":[\"c587\",\"c617\",\"c635\",\"c660\",\"c665\"]},{\"title\":\"梦有安慰，也会让痛苦换一种形状持续\",\"text\":\"有的梦让雨晴表达无法直面的失去；天语遥的幻觉却把等待的人写成已经归来；橘子的创伤叙事又把真实遇难者与拒绝混成神怪故事。原著并没有让所有梦拥有同一种真实性，阅读时必须跟随后文的边界。\",\"refs\":[\"c338\",\"c463\",\"c468\",\"c586\",\"c660\",\"x028\"]},{\"title\":\"偶然、资源与“命运”的不均等\",\"text\":\"雨晴背后有经济和家族资源，其他伙伴获得帮助的条件并不相同；莫空的反复出现又给日常加上近似命运的安排。结尾连莫空也不能留住她，使“能预见、能保护”与“仍会失去”之间形成无法轻易消除的矛盾。\",\"refs\":[\"c224\",\"c524\",\"c574\",\"c633\",\"c650\",\"c665\"]}],\"payoffs\":[{\"name\":\"想变成鹰的鱼\",\"setup\":\"莫空讲述鱼改变自身、仍被双方排斥的寓言。\",\"payoff\":\"夕晨后来的画册呼应鱼的形象，人物对身体与自由的追求也不断与它形成对照。\",\"reading\":\"可以读作被排斥者追求另一种存在方式的寓言；并非对所有人物结局的机械预告。\",\"refs\":[\"c020\",\"c329\",\"c665\"]},{\"name\":\"公园、空气墙与夜市\",\"setup\":\"雨晴反复在梦中看见荒园、少年与无法越过的边界。\",\"payoff\":\"婚前梦中她悟到束缚与自身执念有关，走出去，再见少年与夕晨，并明确承认夕晨现实死亡。\",\"reading\":\"梦境由无解的囚笼转为能够容纳哀悼和新生活的空间。\",\"refs\":[\"c025\",\"c338\",\"c585\",\"c586\",\"c660\"]},{\"name\":\"占卜牌：礼物、不祥图案与来生\",\"setup\":\"莫空为不同人展示不同卡面与礼物；神秘女孩给他狐狸图案木卡。\",\"payoff\":\"正文保留预示性，死后外传让卡牌成为雨晴与太阴相见的媒介。\",\"reading\":\"它把日常玩笑、死亡预感和超自然外传连接起来；每张卡的作用应逐物查看，不全部视为精确预言。\",\"refs\":[\"c269\",\"c270\",\"c272\",\"x001\"]},{\"name\":\"半枚贝壳、画作与夕晨的痕迹\",\"setup\":\"夕晨与雨晴互赠画作，后来把贝壳分成两半各自保存。\",\"payoff\":\"夕晨死亡后，雨晴发现画作中的另一面，又把遗物带到新的生活里；婚前仍在梦中向她讲述后来。\",\"reading\":\"关系没有被后一段爱情抹去，物品让记忆可以随人迁移。\",\"refs\":[\"c160\",\"c286\",\"c404\",\"c583\",\"c617\",\"c635\",\"c660\"]},{\"name\":\"烧掉的白裙与重新准备的白裙\",\"setup\":\"开篇父亲毁掉雨晴的女装并强制剃发。\",\"payoff\":\"归家后她发现母亲准备了与昔日第一套女装相近的白裙，父母提出支持手术与新生活。\",\"reading\":\"以具体物件表达补偿和接纳，但不能据此宣布旧伤从未发生。\",\"refs\":[\"c001\",\"c620\",\"c622\"]},{\"name\":\"旧钥匙与复制的小屋\",\"setup\":\"离家时钥匙被留在家中纸条上；返家段却写她一直保存着它，前后去向不一致。初到小城市时，她在外拥有极简的小窝。\",\"payoff\":\"生锈的钥匙重新打开杭州家门；莫空在台湾造的小木屋仿照初到小城市的出租房。\",\"reading\":\"相同物件与布局在不同阶段具有不同情感：贫困的防线后来成为安全的记忆。\",\"refs\":[\"c001\",\"c008\",\"c618\",\"c620\",\"c642\"]},{\"name\":\"语默之名与收养兄妹\",\"setup\":\"返乡火车上的梦出现孩子名字语默，莫空称自己听见梦话；小木屋中再提领养女儿。\",\"payoff\":\"林清云被收养后改名莫语默。莫空拒绝同收兄妹并涉及记忆空白的段落，未给完整解释。\",\"reading\":\"愿望得到实现，同时继续保存莫空预知与干预的悬念。\",\"refs\":[\"c618\",\"c642\",\"c655\",\"c656\",\"c657\"]},{\"name\":\"莫空、秋易与第三十九次轮回\",\"setup\":\"莫空游历、石剑、世界线提问、投影世界和秋易的出现不断累积异常。\",\"payoff\":\"两人直接谈到第三十九次轮回、觉醒和改变历史，随后以小说试读遮掩；雨晴死亡又令莫空惊惧于偏离预期。\",\"reading\":\"足以确认这不是毫无伏笔的偶然相助，却不足以自行补全轮回规则或套入未经原书说明的外部作品设定。\",\"refs\":[\"c039\",\"c224\",\"c277\",\"c495\",\"c588\",\"c650\",\"c665\"]},{\"name\":\"信件不是自动说出真相的人\",\"setup\":\"柳韵得到揭露胡玉牛的材料，却在改变主意后把信遗落胡家。\",\"payoff\":\"胡母意外看到内容，家庭冲突引爆；阿牛把误会当作背叛，错失柳韵后来的解释。\",\"reading\":\"信息本身真实，并不代表流转方式和人物对动机的猜测也真实。\",\"refs\":[\"c436\",\"c438\",\"c440\",\"c441\",\"c444\"]},{\"name\":\"宠物的生命，串起陪伴与告别\",\"setup\":\"曲奇由流浪猫变成伙伴，咖啡由猎物变成室友，朱雀加入短暂日常。\",\"payoff\":\"朱雀、咖啡、雨晴、曲奇在不同节点死去；每次的经过与遗体去向不同。\",\"reading\":\"这些死亡逐步把“永不分开”的愿望放在有限生命面前。\",\"refs\":[\"c024\",\"c046\",\"c310\",\"c328\",\"c603\",\"c604\",\"c665\"]}],\"ambiguities\":[{\"title\":\"雨晴的死亡日与安葬日口径不同\",\"text\":\"c665把2016年4月4日放在死亡后的“半个月”之后，明确说当天是安葬日；后记却把同一日期称为死亡日期。图鉴采用“2016年春病逝；4月4日安葬（正文）”，并保留差异。\",\"refs\":[\"c665\",\"x079\"]},{\"title\":\"“在外三年”、2006年归家与2007年台湾段\",\"text\":\"开篇是2004年；c616、c619仍明确2006年，却多次称已在外三年。台湾段c641又写2007年，下一春节明确2008年。不能在不说明的情况下把归家日期统一改成2007年，也不宜把所有天数精算成毫无缺口。\",\"refs\":[\"c001\",\"c616\",\"c618\",\"c619\",\"c641\",\"c643\"]},{\"title\":\"天语遥老家的地理表述摇摆\",\"text\":\"一处写小城市附近临海市郊区，另一处又写北方家乡与跨省联系。地图只保留“天语遥老家”这一叙事节点，不据此画真实经纬度或杜撰一条精确交通路线。\",\"refs\":[\"c415\",\"c422\"]},{\"title\":\"同一伤势，前后章严重程度不一致\",\"text\":\"救援段描述天语遥遭受非常严重的肢体伤害，紧接着的住院与后续章又用较轻的外伤口径叙述。图鉴确认侵害、救援及长期照护的结果，保留伤势描写差异，不编造一次未写出的治愈。\",\"refs\":[\"c490\",\"c491\",\"c499\"]},{\"title\":\"“大伯”已被作者更正为“大舅”\",\"text\":\"这不是必须维持两个身份的悬疑。c573作者更正称谓，后续和前传进一步解释母系长辈及双方远房亲缘。图鉴合并为苏雨晴的大舅，保留“大伯 / 苏书记”作为检索旧称。\",\"refs\":[\"c524\",\"c548\",\"c573\",\"c574\",\"x064\"]},{\"title\":\"苏家祖辈与辈分说明仍有疏漏\",\"text\":\"临行时说见爷爷，进入苏家段却说祖父母五年前已逝；关于名字辈分的解释也有字位不一致。保留原文可确认的家族权力与脱离结果，不为这些疏漏补写新人物或新仪式。\",\"refs\":[\"c630\",\"c631\",\"c633\"]},{\"title\":\"身份与身体设定需要按原著层次记录\",\"text\":\"夕晨的身体差异是正文就医情节所揭示的设定，不能写成服药改变染色体。全书的医疗、诊断、手术和法律叙述有虚构与不可靠之处；图鉴不据此提供现实医学或法律结论。\",\"refs\":[\"c338\",\"c473\",\"c474\",\"c499\",\"c665\"]},{\"title\":\"小说没有逐个交代所有人的余生\",\"text\":\"孙昊、柳韵、某些同事、富商与少年配角在主要事件后缺少明确终局；案件判决也未逐一具名对应。人物档案的“截至该段”是末次明确状态，不能自动当成完整人生结局。\",\"refs\":[\"c499\",\"c560\",\"c573\",\"c649\"]},{\"title\":\"旧家钥匙去向前后不一致\",\"text\":\"第1章写苏雨晴把家门钥匙留在告别纸条上；第618章却写她一直将旧钥匙保存在行李箱，想家时还会拿出来看，第620章再用它开门。图鉴保留后文归家的事件，同时标记这一连续性矛盾；不补写第二把钥匙或原文未记载的归还过程。\",\"refs\":[\"c001\",\"c618\",\"c620\"]},{\"title\":\"方莜莜与安念的店址口径变化\",\"text\":\"正文写两人在宁波同居、开店；方莜莜外传的主体生活地又称海宁，外传第30章附近再次出现宁波。原文没有明确交代一次将两处串起的搬迁，因此地图分别列出，并保留这一地点口径差异。\",\"refs\":[\"c538\",\"c562\",\"x033\"]},{\"title\":\"曲奇的性别设定前后不一致\",\"text\":\"第45章称曲奇为母猫；第595章以及前传多处又明确称其为公猫。图鉴将它统一登记为黑猫，并保留分段描述的差异，不用后来的伴侣、幼猫情节反推并改写早期文本。\",\"refs\":[\"c045\",\"c595\",\"x054\",\"x058\",\"x062\"]},{\"title\":\"张思凡早年前史中的报酬和期限差异\",\"text\":\"正文早期回忆写接受富人安排并计划坚持一年，最后未拿到约定的大笔报酬；前传展开时又写约定一个月，并写他逃离时带走前几天已收到的一万元。因此图鉴将两处作为同一前史的展开参照，同时保留期限和报酬措辞差异，不概括成各处都说分文未得。\",\"refs\":[\"c072\",\"x059\",\"x060\",\"x061\"]},{\"title\":\"狐狸木卡赠送时间的年数差异\",\"text\":\"正文第272章写莫空从失语的年轻女子处得到狐狸山水木卡；死后外传太阴以同一卡片回收赠礼身份，却称六年前，和正文约2004年、主角2016年去世的年代并不相合。可以确认道具回收，不能据此宣称全书时间精密一致；其他只有狐耳、九尾或脚铃相似的身影仍保留疑似。\",\"refs\":[\"c247\",\"c271\",\"c272\",\"x001\"]}],\"characterOverrides\":{\"苏雨晴\":{\"group\":\"核心群像\",\"identity\":\"全书主视角人物。2004年15岁从杭州出走的跨性别女孩，网名清泉；在小城市谋生，与伙伴建立临时家庭，后归家迁台、复学、结婚并成为养母。\",\"portrait\":\"她敏感、怕被拒绝，也有愿意冒险保护他人的勇气；同样会自卑、依赖、嫉妒，并以未经理解的道德判断伤到身边人。成长主要体现为逐渐能看见别人的处境，以及在收养选择中尊重孩子意愿。\"},\"莫空\":{\"group\":\"核心群像\",\"identity\":\"旅人、小说作者，笔名或自取名莫成，曾任莫家家主。早在雨晴离家的火车上出现，后来长期相助并成为她的丈夫、语默的养父；带有家族与轮回悬疑。\",\"portrait\":\"从容、善于观察，愿意付出实际帮助，却也习惯保留信息、替他人安排路径。后期的亲密关系并没有消除他与常人经验之间的距离；雨晴之死第一次彻底打破他对未来的笃定。\"},\"林夕晨\":{\"group\":\"核心群像\",\"identity\":\"网名夕子，插画师，雨晴的室友与后来的恋人。来自重男轻女、存在暴力的农村家庭；正文就医情节另揭示先天性发育差异，按小说设定记录。\",\"portrait\":\"外表安静温柔、擅长照料与绘画，内心却压着愤怒、负疚和沉重家庭责任。她习惯独自承担并隐藏痛苦；对雨晴的保护与对原生家庭的无法脱身共同构成悲剧。\"},\"张思凡\":{\"group\":\"核心群像\",\"identity\":\"网名月橙，常被称思思。初登场以女性身份生活，是雨晴姐姐般的朋友；计算机专业大学生。后与孙昊决裂、回到男性社会生活，再与董花火成家。\",\"portrait\":\"在熟人面前爱开玩笑，在网上耐心帮助新人，现实生活却长期独居、交友有限。她慷慨照顾雨晴，也曾以玩笑之名越过对方的身体边界；热闹外表下有孤独、自卑与受控制的旧创伤。后来选择改变生活路径，应按个人经历理解。\"},\"方莜莜\":{\"group\":\"核心群像\",\"identity\":\"本名方宇悠，网名优子，亦称悠悠。擅厨、从事网络维修工作的伙伴，长期失眠，与安念从《传奇》相识到现实同居。正式外传继续讲述她的感情终局。\",\"portrait\":\"温柔细心、能照料一屋人的日常，却常把自己的需求往后放。越是害怕被抛弃，越容易以退让换取关系；正式外传把这种忍耐推到极限，最终以获救与离开收束。\"},\"胡玉牛\":{\"group\":\"核心群像\",\"identity\":\"武艺传承家庭中的年轻人，常称阿牛、小玉，外形强健而有女性愿望。在超市工作，是合租伙伴，与柳韵相恋；身份秘密与复仇链交汇在他身上。\",\"portrait\":\"朴实、重情，有保护他人的勇气，也因家庭责任和外貌焦虑不断自我否定。他隐瞒关键事实，又在受伤时难以相信解释，使本可沟通的关系在压力中断裂。\"},\"天语遥\":{\"group\":\"核心群像\",\"identity\":\"原名天冲云，曾是混混头目。重伤后被父母强迫走向女性化生活并改名；父亲后来愿意退让时，她又亲口选择称小遥、做女儿。此后的认同仍伴随持续痛苦、复仇、幻觉与严重创伤，恋人为夏归月。\",\"portrait\":\"既曾主动伤害别人，也是后续强迫与暴力的受害者。她的倔强、控制欲、羞耻与被爱渴望交织；理解她的痛苦并不等于替其最初侵害和后来的报复开脱。\"},\"夏归月\":{\"group\":\"亲密关系\",\"identity\":\"天冲云、后来的天语遥的恋人，多次寻找对方，并在其长期失去生活能力后继续陪伴照顾。\",\"portrait\":\"乐观、坚韧，重视具体的人而愿意重新理解身份变化。她的坚持并非作者已经保证“必然治好”的承诺，而是在没有确定回报时仍然选择当下的陪伴。\"},\"柳韵\":{\"group\":\"亲密关系\",\"identity\":\"常用名音音，与胡玉牛相恋，既受过他的保护，也在他死后将仇恨转向天语遥。\",\"portrait\":\"她有真实的爱，也有偏见和冲动。得知秘密后曾主动放下报复，并愿意解释意外遗信；失去爱人后却转向严重的报复性伤害，不能用其中一面抹掉另一面。\"},\"安念\":{\"group\":\"亲密关系\",\"identity\":\"《传奇》中名有条色狼，另用女号有只银娘，与方莜莜相恋并同居开店。家庭婚育期待在正式外传中成为关系的重要压力。\"},\"橘子\":{\"group\":\"外传人物\",\"identity\":\"本名田桔，跨性别男性，方莜莜正式外传的重要人物。过去经历创伤与记忆改写，后来帮助并救下莜莜。\"},\"苏榕槐\":{\"group\":\"家庭与亲属\",\"identity\":\"苏雨晴父亲，苏家产业经营者。开篇拒绝并伤害女儿，后来参与暗中保护、公开接纳，带全家脱离宗族、迁台经营。\"},\"苏雨晴的母亲\":{\"group\":\"家庭与亲属\",\"identity\":\"亲属称圆圆，苏雨晴与苏冬凌的母亲，来自台湾苏家村一支。与丈夫经历从拒绝到理解的转变，归家时公开称雨晴为女儿。\"},\"苏雨晴的大舅\":{\"group\":\"家庭与亲属\",\"identity\":\"苏书记，母亲的兄长、大表哥的父亲，亦与苏父有远房亲缘。正文前期误称“大伯”，c573作者更正为“大舅”。暗中运用资源保护雨晴。\"},\"莫语默\":{\"group\":\"家庭与亲属\",\"identity\":\"原名林清云，林清雾的双胞胎妹妹。由莫空和苏雨晴领养后改名，随家庭到台湾生活。\"},\"曲奇\":{\"group\":\"动物伙伴\",\"identity\":\"陪伴苏雨晴的蓝眼黑猫，由流浪伙伴成为家人，与鼠咖啡关系亲近，后随雨晴迁台。早期称母猫，后期与前传又称公猫，原书性别设定前后不一致。\"},\"咖啡\":{\"group\":\"动物伙伴\",\"identity\":\"曲奇带回的幼鼠，初为灰毛，随换毛逐渐转为紫毛，晚年失去光泽并出现白毛。它与猫和雨晴长期相伴，有独立生命线，不能当作饮料“咖啡”混入物品。\"},\"朱雀\":{\"group\":\"动物伙伴\",\"identity\":\"苏雨晴购买并命名的红色雏鸡，短暂加入她、曲奇与咖啡的日常。\"},\"黑皇\":{\"group\":\"动物伙伴\",\"identity\":\"也与“小黑”称呼相关的大黑犬，曾亲近天语遥，后被秋易收养，由莫空取名黑皇。\"},\"糯米\":{\"group\":\"动物伙伴\",\"identity\":\"台湾段出现的异瞳白色母猫，由雨晴命名，与曲奇相伴。\"},\"太阴\":{\"group\":\"超自然与悬疑\",\"identity\":\"死后外传明确出现的九尾神，通过占卜卡接触雨晴，并给予转生机会。\"},\"叶洛夜\":{\"group\":\"外传人物\",\"identity\":\"死后外传中苏雨晴转生后的女婴身份，出生年份为2010年，龙凤胎兄弟名秋叶。\"}}},\"units\":[{\"key\":\"c001\",\"id\":1,\"title\":\"出走\",\"kind\":\"main\",\"volume\":1,\"start\":22,\"end\":25,\"summary\":\"2004年，15岁的苏雨晴因父母发现她的女装和药物，遭父亲殴打、强制剃发，衣物与部分药物被烧毁。她拿走父母的一千元，带上隐藏的药、行李和猫玩偶，留下不被接纳便离开的纸条及家门钥匙，独自去火车站。\",\"turn\":\"家庭冲突引发出走；她既恐惧又坚持女性身份。\",\"time\":\"2004年春；苏雨晴15岁\",\"people\":[\"苏雨晴\",\"苏雨晴父母\"],\"objects\":[\"行李箱\",\"鸭舌帽\",\"补佳乐\",\"螺内酯\",\"色谱龙\",\"离家纸条\",\"家门钥匙\",\"起司猫玩偶\"],\"places\":[\"杭州的家\",\"理发店\",\"出租车\"]},{\"key\":\"c002\",\"id\":2,\"title\":\"小城市\",\"kind\":\"main\",\"volume\":1,\"start\":26,\"end\":29,\"summary\":\"苏雨晴在杭州城站选购开往浙江虚构小城“小城市”的车票，希望在低物价环境工作生活。她因胆怯找不到检票口，获清洁工指路；旅途中想念又怨恨父母。一名不修边幅的年轻男子注意到她，列车抵达后将熟睡的她叫醒。\",\"turn\":\"第一次独行同时遇见陌生善意与对未来的恐惧。\",\"time\":\"出走当日\",\"people\":[\"苏雨晴\",\"火车站清洁工\",\"莫空\"],\"objects\":[\"T136车票\",\"鸭舌帽\"],\"places\":[\"杭州城站\",\"小城市火车站\"]},{\"key\":\"c003\",\"id\":3,\"title\":\"独自一人，不知方向\",\"kind\":\"main\",\"volume\":1,\"start\":30,\"end\":33,\"summary\":\"抵达小城市后，苏雨晴举目无亲，在车站外迟迟不知往哪里走。列车上的男子坐摩托车前往白石路；她独自步行，因学校受欺负的经验习惯低头隐藏自己。一天未进食的她买了一份嵌糕，吃饱后开始整理找工作和住处的计划。\",\"turn\":\"陌生城市的自由转化为实际生存问题，她开始盘算工作与住处。\",\"time\":\"出走当日下午\",\"people\":[\"苏雨晴\",\"莫空\",\"嵌糕店老板娘\"],\"objects\":[\"嵌糕\",\"行李箱\"],\"places\":[\"小城市火车站\",\"街头\"]},{\"key\":\"c004\",\"id\":4,\"title\":\"消失的钱包\",\"kind\":\"main\",\"volume\":1,\"start\":34,\"end\":37,\"summary\":\"苏雨晴在拥挤的中介店选中饭店服务员工作，付费时却发现装有积蓄和身份证的钱包消失。她多次翻找仍无结果，求助时反被中介老板指责闹事并赶走。她沿来路寻觅至天黑，因失去资金与身份凭证而陷入绝望。\",\"turn\":\"钱包去向不明，资金与身份证一并丢失，求职和租屋同时受阻。\",\"time\":\"出走当日傍晚\",\"people\":[\"苏雨晴\",\"中介老板\"],\"objects\":[\"钱包\",\"身份证\",\"招聘纸条\"],\"places\":[\"工作中介店\",\"街道\"]},{\"key\":\"c005\",\"id\":5,\"title\":\"流落街头\",\"kind\":\"main\",\"volume\":1,\"start\":38,\"end\":41,\"summary\":\"身无分文的苏雨晴沿公路流浪，在紧锁木屋旁以行李箱过夜，靠剩余半块嵌糕充饥。她梦见回家被拒、受辱与被拐等恐怖情景，醒后重新坚持自己的身份选择。夜空与日出给予她安慰，她决定天亮后继续找出路。\",\"turn\":\"受害情景全在噩梦中，现实的她迎来日出并决定继续寻找出路。\",\"time\":\"出走第一夜至次日清晨\",\"people\":[\"苏雨晴\"],\"objects\":[\"半块嵌糕\",\"行李箱\",\"天空意象\"],\"places\":[\"公路旁废弃小木屋\",\"加油站附近\"]},{\"key\":\"c006\",\"id\":6,\"title\":\"人生的第一份工作\",\"kind\":\"main\",\"volume\":1,\"start\":42,\"end\":45,\"summary\":\"苏雨晴在行李夹层意外找到三百元，稍解生存危机。她整日寻找工作，因未成年、没有身份证屡遭拒绝，也避开不怀好意的招工者。傍晚走到白石路时，一家面馆的老板娘愿以月薪三百元、包三餐录用她，成为她第一份工作。\",\"turn\":\"面馆提供基本生存条件与初步信任，她终于有了可停留的地方。\",\"time\":\"出走第二日\",\"people\":[\"苏雨晴\",\"张阿姨\",\"杂货店老板\"],\"objects\":[\"三百元备用钱\",\"招工纸条\"],\"places\":[\"小城市街道\",\"白石路\",\"无名面馆\"]},{\"key\":\"c007\",\"id\":7,\"title\":\"老虎房东\",\"kind\":\"main\",\"volume\":1,\"start\":46,\"end\":49,\"summary\":\"老板娘领苏雨晴去找房东“老虎”。途中苏雨晴说明自己的出生性别并摘帽露出短发，老板娘虽沿用男性称呼却没有羞辱她。叙述补充其名字由祖爷爷定入族谱，幼时曾穿裙子。豪爽而精明的女房东带她看一间带独立卫生间的小屋。\",\"turn\":\"自我披露获得有限接纳；找到可能安家的空间。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"老虎\",\"苏雨晴祖爷爷\"],\"objects\":[\"鸭舌帽\",\"族谱\"],\"places\":[\"白石路农民房\",\"出租小屋\"]},{\"key\":\"c008\",\"id\":8,\"title\":\"属于自己的小窝\",\"kind\":\"main\",\"volume\":1,\"start\":50,\"end\":53,\"summary\":\"张阿姨帮苏雨晴把房租谈到每月一百五十元，并预支一个月工资补齐三个月租金。苏雨晴布置小屋，将起司猫玩偶、木笔筒、日记和读物放好，谨慎分配剩余钱款。第一次拥有私人空间使她兴奋，也让她开始学习独立生活的预算。\",\"turn\":\"获得稳定住所，但首月工资已预支支付房租，日常预算仍然很紧。\",\"time\":\"出走第二日晚\",\"people\":[\"苏雨晴\",\"张阿姨\",\"老虎\"],\"objects\":[\"租房合同\",\"房间钥匙\",\"起司猫玩偶\",\"日记本\",\"木制笔筒\",\"食谱\",\"小说\",\"鲁迅散文集\"],\"places\":[\"出租小屋\",\"床品店\"]},{\"key\":\"c009\",\"id\":9,\"title\":\"第一次上班（上）\",\"kind\":\"main\",\"volume\":1,\"start\":54,\"end\":57,\"summary\":\"苏雨晴初次还价失败，买下棕白格棉被，又添置洗漱用品和泡沫地垫，布置出小小的卧室。她为次日工作设好闹钟，因缺钱只能用冷水洗漱。第二天清晨，她戴帽遮住短发出门，正式读到工作地点的名字“无名面馆”。\",\"turn\":\"她带着长发愿望进入劳动生活，独立小屋也需要自己悉心打理。\",\"time\":\"出走第三日清晨\",\"people\":[\"苏雨晴\",\"床品店老板\"],\"objects\":[\"棕白格棉被\",\"泡沫地垫\",\"闹钟\",\"小木梳\"],\"places\":[\"床品店\",\"出租小屋\",\"无名面馆\"]},{\"key\":\"c010\",\"id\":10,\"title\":\"第一次上班（下）\",\"kind\":\"main\",\"volume\":1,\"start\":58,\"end\":61,\"summary\":\"面馆老板娘让苏雨晴称她张阿姨，老板为李叔叔，两人给她早餐并温和照顾。张阿姨劝她感激父母，使她想起无法诉说的身份冲突。第一次上班，她羞于大声报单、遭熟客玩笑，仍认真完成工作；列车上的年轻男子再次来店吃饭并鼓励她。\",\"turn\":\"夫妻的照顾与不完全理解并存；与莫空再次相遇。\",\"time\":\"第一次上班\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"莫空\",\"老王\"],\"objects\":[\"拌面与荷包蛋\"],\"places\":[\"无名面馆\"]},{\"key\":\"c011\",\"id\":11,\"title\":\"真正迈出那一步\",\"kind\":\"main\",\"volume\":1,\"start\":62,\"end\":65,\"summary\":\"劳累回家后，苏雨晴看到青春期变化，害怕身体朝不愿的方向发育，依网络朋友提供的信息决定持续自行用药。她回忆查阅性别转换资料的经历，盼望未来手术。当夜她处理磨伤的双脚后入睡，却很快因噩梦、心悸和胸闷醒来。\",\"turn\":\"身份追求进入持续用药阶段，同时出现身体不适。\",\"time\":\"第一次上班当夜\",\"people\":[\"苏雨晴\",\"网络药娘朋友\"],\"objects\":[\"补佳乐\",\"螺内酯\",\"哆啦A梦胸章\",\"镜子\"],\"places\":[\"出租小屋\"]},{\"key\":\"c012\",\"id\":12,\"title\":\"失眠\",\"kind\":\"main\",\"volume\":1,\"start\":66,\"end\":69,\"summary\":\"彻夜失眠又脚伤未愈的苏雨晴冒雨艰难上班，怀疑不适与自行用药有关。张阿姨和李叔叔让她休息、准备鸡腿炒面，她困得无法吃完便睡下。梦中她来到荒芜公园，遇见与自己相似却没有影子的小男孩，对方请求她下次带自己离开。\",\"turn\":\"第一次出现反复荒园梦，身体虚弱中也获得雇主的体谅与照顾。\",\"time\":\"第二次上班清晨\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"梦中小男孩\"],\"objects\":[\"鸡腿炒面\",\"秋千\"],\"places\":[\"无名面馆\",\"梦中荒芜公园\"]},{\"key\":\"c013\",\"id\":13,\"title\":\"那朦胧的雨\",\"kind\":\"main\",\"volume\":1,\"start\":70,\"end\":73,\"summary\":\"苏雨晴睡醒后身体稍有恢复，老板夫妻主动把上班时间改为九点，并给她每周一休假。年轻写作者来店谈旅行、工作和饮食，坦言自己只是打零工与写故事的人。他的平和让她好奇；雨景又勾起她对父母是否寻找自己的复杂挂念。\",\"turn\":\"获得休息制度；莫空的生活态度引起她注意。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"莫空\"],\"objects\":[\"白色雨伞\",\"熔岩辣椒调味酱\"],\"places\":[\"无名面馆\"]},{\"key\":\"c014\",\"id\":14,\"title\":\"苏雨晴的日记\",\"kind\":\"main\",\"volume\":1,\"start\":74,\"end\":77,\"summary\":\"苏雨晴借面馆的伞回家，另开一本路灯封面的日记，记下三月六日用药不适、安家和对年轻男人的印象，向未来自己发问。当晚她再梦见荒园男孩，男孩为接近梦想不断吃石头，明知痛苦仍坚持，反问她要找的东西是否找到。\",\"turn\":\"日记确立明确日期；吃石头梦境呼应她的用药选择。\",\"time\":\"2004年3月6日夜\",\"people\":[\"苏雨晴\",\"张阿姨\",\"梦中小男孩\"],\"objects\":[\"借来的雨伞\",\"桃花备忘本\",\"路灯封面日记\",\"石头\"],\"places\":[\"出租小屋\",\"梦中公园\"]},{\"key\":\"c015\",\"id\":15,\"title\":\"螺内酯的副作用\",\"kind\":\"main\",\"volume\":1,\"start\":78,\"end\":81,\"summary\":\"苏雨晴因夜间频繁起身而再次睡不好，查看药品说明书，仍因害怕身体发育而没有改变自行用药。她忘记已推迟上班，清晨读鲁迅散文，从关于人生前路的文字中获得勇气，也反复思量出走对错，最后匆忙赶到面馆。\",\"turn\":\"她仍在惶恐中坚持选择，阅读成为孤身生活里整理思绪的方法。\",\"time\":\"2004年3月7日晨\",\"people\":[\"苏雨晴\",\"张阿姨\"],\"objects\":[\"螺内酯说明书\",\"鲁迅散文集\",\"闹钟\"],\"places\":[\"出租小屋\",\"无名面馆\"]},{\"key\":\"c016\",\"id\":16,\"title\":\"看板娘\",\"kind\":\"main\",\"volume\":1,\"start\":82,\"end\":85,\"summary\":\"高汤佐料厂家到面馆宣传，看中苏雨晴的外貌，愿付她两百元做一天发单员，也补偿面馆。她为添置生活用品接受任务，努力克服与陌生人交流的羞怯。年轻写作者接传单时无意碰到她手指，又爽快购货，使她开始猜想对方是否关照自己。\",\"turn\":\"首次额外收入机会，也出现对莫空的朦胧在意。\",\"time\":\"2004年3月7日\",\"people\":[\"苏雨晴\",\"莫空\",\"汤料厂家男子\",\"李叔\",\"张阿姨\"],\"objects\":[\"高汤佐料\",\"宣传单\",\"两百元报酬\"],\"places\":[\"无名面馆门口\"]},{\"key\":\"c017\",\"id\":17,\"title\":\"日常用品采购\",\"kind\":\"main\",\"volume\":1,\"start\":86,\"end\":88,\"summary\":\"发单结束后，苏雨晴领到两百元，获准提前下班，并确认次日妇女节为休息日。她到大润发挑选促销生活用品，购入电热水壶、热水瓶、粉色碎花帘和洗晒用品。虽负担不起女装，她仍被折扣国产芭比套装吸引，另买零食犒劳自己。\",\"turn\":\"额外收入换来热水与隐私用品，她也为喜欢的娃娃打破节制。\",\"time\":\"2004年3月7日星期日\",\"people\":[\"苏雨晴\",\"张阿姨\",\"汤料厂家男子\"],\"objects\":[\"两百元工资\",\"电热水壶\",\"热水瓶\",\"粉色碎花帘\",\"芭比娃娃\"],\"places\":[\"大润发超市\"]},{\"key\":\"c018\",\"id\":18,\"title\":\"身体的轻微变化\",\"kind\":\"main\",\"volume\":1,\"start\":89,\"end\":92,\"summary\":\"苏雨晴独自费力安装帘子，终于能用新水壶烧热水洗澡。照镜时，她留意身体出现细微变化，又意识到生活中的重活和家务全须自己完成。洗衣使她想起母亲照顾，虽动摇、怀念，仍决定继续独立走下去。\",\"turn\":\"独立带来自主，也意味着无人代为承担家务与病痛。\",\"time\":\"2004年3月7日夜\",\"people\":[\"苏雨晴\"],\"objects\":[\"粉色碎花帘\",\"电热水壶\",\"镜子\",\"洗衣用品\"],\"places\":[\"出租小屋\"]},{\"key\":\"c019\",\"id\":19,\"title\":\"上班后的第一个假日\",\"kind\":\"main\",\"volume\":1,\"start\":93,\"end\":96,\"summary\":\"第一个休息日天气晴好，苏雨晴沿尚未贯通的新路散步，在水库河堤发现宁静草地。她短暂幻想只有自己一人的城市，却也感到寂寞。常来面馆的年轻写作者恰好出现，躺在旁边欣赏风景，并向紧张的她搭话。\",\"turn\":\"无人的自由并没有消除孤单，莫空的出现提供新的交流机会。\",\"time\":\"2004年3月8日星期一\",\"people\":[\"苏雨晴\",\"莫空\"],\"objects\":[\"闹钟\"],\"places\":[\"未贯通的新路\",\"水库河堤\"]},{\"key\":\"c020\",\"id\":20,\"title\":\"想要变成鹰的鱼\",\"kind\":\"main\",\"volume\":1,\"start\":97,\"end\":100,\"summary\":\"河堤上，年轻男子讲述四处旅居与写作理想，苏雨晴因相似的非传统选择而放下戒备。他讲了一条鱼借魔法宝石变鹰的故事：鱼遭原有与未来同类排斥，终于飞翔却带伤死亡。苏雨晴被愿望、代价和不被接纳的主题触动落泪。\",\"turn\":\"寓言建立全书核心象征，也加深二人情感共鸣。\",\"time\":\"2004年3月8日\",\"people\":[\"苏雨晴\",\"莫空\"],\"objects\":[\"鱼变鹰寓言\",\"宝石\"],\"places\":[\"水库河堤\"]},{\"key\":\"c021\",\"id\":21,\"title\":\"黑猫\",\"kind\":\"main\",\"volume\":1,\"start\":101,\"end\":104,\"summary\":\"写作者悄然离开，苏雨晴懊悔尚未问名字。她遇到一只善游泳、会捕鱼的矫健黑猫，尊重它不愿被摸的距离。在河堤睡梦中，她把自己代入未能飞翔的鹰；傍晚黑猫拍醒她。返回途中，她走进热闹花店，尝试承受旁人的目光。\",\"turn\":\"猫的陪伴填补独处空隙，苏对还没来得及问姓名的写作者念念不忘。\",\"time\":\"2004年3月8日\",\"people\":[\"苏雨晴\",\"莫空\",\"曲奇\"],\"objects\":[\"豆腐干\",\"鱼变鹰梦\"],\"places\":[\"水库河堤\",\"花店\"]},{\"key\":\"c022\",\"id\":22,\"title\":\"勿忘我\",\"kind\":\"main\",\"volume\":1,\"start\":105,\"end\":107,\"summary\":\"苏雨晴买一枝颜色极浅的勿忘我给自己，取“不忘初心”之意，用捡来的易拉罐当花瓶。她玩芭比、用纸做衣服，又后悔冲动花钱。夜间黑猫来窗外未能进入；她梦见勿忘我花海中一朵与众不同、显得孱弱的白花。\",\"turn\":\"勿忘我成为自我认同象征，白花梦境继续铺设。\",\"time\":\"2004年3月8日夜\",\"people\":[\"苏雨晴\",\"曲奇\",\"花店老板\"],\"objects\":[\"勿忘我\",\"易拉罐花瓶\",\"芭比娃娃\",\"纸衣服\"],\"places\":[\"花店\",\"出租小屋\",\"梦中花海\"]},{\"key\":\"c023\",\"id\":23,\"title\":\"女色狼？\",\"kind\":\"main\",\"volume\":1,\"start\":108,\"end\":110,\"summary\":\"次日苏雨晴边劳动边期待写作者来店。一位高挑金发熟客出现，得知她的出生性别后要求看头发，并对被剃平头表示惋惜，似乎察觉这并非她所愿。但对方随后未经允许触碰她身体，使她惊惧躲开，视其为危险人物。\",\"turn\":\"张思凡以女装首次登场，关切与越界行为并存。\",\"time\":\"2004年3月9日\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"张思凡\"],\"objects\":[\"鸭舌帽\"],\"places\":[\"无名面馆\"]},{\"key\":\"c024\",\"id\":24,\"title\":\"曲奇\",\"kind\":\"main\",\"volume\":1,\"start\":111,\"end\":114,\"summary\":\"苏雨晴下班带回报纸，因预报暴雨而用铁丝在室内晾衣，继续写日记。河堤黑猫主动从窗台入内，她小心与它握爪、喂小鱼干，并因耳朵局部棕色为它取名“曲奇”，设想替它搭窝。猫吃完却离去，使她失落地以为只是自己一厢情愿。\",\"turn\":\"她主动命名并准备照顾曲奇，却尚不明白野猫会保留来去的自由。\",\"time\":\"2004年3月9日夜\",\"people\":[\"苏雨晴\",\"曲奇\"],\"objects\":[\"报纸\",\"铁丝晾衣绳\",\"日记\",\"小鱼干\"],\"places\":[\"出租小屋\"]},{\"key\":\"c025\",\"id\":25,\"title\":\"找不到答案的梦\",\"kind\":\"main\",\"volume\":1,\"start\":115,\"end\":118,\"summary\":\"苏雨晴再入荒园梦境，尝试翻墙逃出，却回到同一入口。秋千男孩身体更虚弱，开始吃五颜六色的糖果，解释这些东西让身体疼痛却能缓解心痛。她觉得对方无比熟悉，几乎想起自己遗失的东西，醒来却再次忘记。\",\"turn\":\"梦中身体与内心痛苦的交换更加明确，身份答案仍未揭示。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"梦中小男孩\"],\"objects\":[\"糖果\",\"秋千\",\"公园围墙\"],\"places\":[\"梦中公园\"]},{\"key\":\"c026\",\"id\":26,\"title\":\"黑网吧\",\"kind\":\"main\",\"volume\":1,\"start\":119,\"end\":122,\"summary\":\"雨天工作空闲，苏雨晴回忆初中唯一亲近的同桌：他护着受排斥的她，也常用玩笑和小礼物亲近她。下班后，她得知老板夫妻已购房，从打工生活中获得一点踏实感。随后她按食客提示来到杂货店暗门后的黑网吧，准备寻找网络同伴。\",\"turn\":\"旧同桌关系埋下伏笔；第一次在小城市接回网络关系。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"苏雨晴初中同桌\",\"张阿姨\",\"李叔\",\"黑网吧老板\"],\"objects\":[\"公共电脑\",\"杂货店暗门\"],\"places\":[\"无名面馆\",\"黑网吧\"]},{\"key\":\"c027\",\"id\":27,\"title\":\"论坛\",\"kind\":\"main\",\"volume\":1,\"start\":123,\"end\":126,\"summary\":\"苏雨晴登录设于台湾的封闭论坛“药娘”圈子，以清泉身份查阅资料，并回复好友月橙。月橙得知她出走后愿寄钱，她因已有工作婉拒；二人意外发现同在小城市，约定下周一中心广场见面。她随后看《乱马二分之一》，羡慕其中轻易转换的身体。\",\"turn\":\"最亲近的网友原来近在同城，第一次现实会面终于可以安排。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"封闭论坛\",\"清泉账号\",\"月橙私信\",\"《乱马二分之一》\"],\"places\":[\"黑网吧\"]},{\"key\":\"c028\",\"id\":28,\"title\":\"莫空\",\"kind\":\"main\",\"volume\":1,\"start\":127,\"end\":130,\"summary\":\"面馆生意繁忙，苏雨晴跑腿买雪菜后体力不支，端面险些洒出。年轻写作者及时扶住面碗，替她化解意外。她终于鼓起勇气问姓名，得知对方本名莫空、自取名或笔名莫成，二人正式交换名字。下班时，张阿姨送她牛奶补充营养。\",\"turn\":\"她终于知道写作者叫莫空，彼此从熟面孔成为能够互称姓名的人。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"张阿姨\",\"李叔\"],\"objects\":[\"雪菜\",\"面碗\",\"牛奶\"],\"places\":[\"小超市\",\"无名面馆\"]},{\"key\":\"c029\",\"id\":29,\"title\":\"做客的猫\",\"kind\":\"main\",\"volume\":1,\"start\":131,\"end\":133,\"summary\":\"苏雨晴洗澡后写下与月橙见面的期待，又画起曲奇。回忆揭示她童年被大量兴趣班占满，绘画是残留下来的自我表达方式。曲奇敲窗来访，带来一只尚活着的幼鼠；她虽嫌脏而惊退，仍逐渐明白猫可能是在送礼。\",\"turn\":\"曲奇以自身方式回报，人与猫之间的关系加深。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"曲奇\",\"苏雨晴父母\"],\"objects\":[\"绘画本\",\"幼鼠\",\"日记\"],\"places\":[\"出租小屋\"]},{\"key\":\"c030\",\"id\":30,\"title\":\"猫和老鼠\",\"kind\":\"main\",\"volume\":1,\"start\":134,\"end\":137,\"summary\":\"曲奇把幼鼠当礼物，苏雨晴拒绝又不忍看到它被吃，试图请猫放过老鼠，曲奇最终叼鼠离开。当夜她梦见公园树木半荣半枯，男孩不在，她坐上秋千后醒来。腹泻让她极度虚弱，挣扎回床却没盖好被子，为次日患病埋下原因。\",\"turn\":\"苏的怜悯给幼鼠留下生路，梦境与腹泻却继续侵扰她的夜晚。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"曲奇\",\"幼鼠\"],\"objects\":[\"秋千\",\"半荣半枯的树\"],\"places\":[\"出租小屋\",\"梦中公园\"]},{\"key\":\"c031\",\"id\":31,\"title\":\"着凉\",\"kind\":\"main\",\"volume\":1,\"start\":138,\"end\":141,\"summary\":\"苏雨晴着凉、头晕且食欲不振，仍因担心丢掉难得的工作而强撑上班。莫空看出她不舒服，帮她接过面碗并劝请假。他的关怀令她感到温暖，也使她意识到自己对这个温柔男性有了超出普通熟人的好感。\",\"turn\":\"疾病暴露经济压力，莫空逐渐成为情感依靠。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"张阿姨\"],\"objects\":[\"面碗\"],\"places\":[\"出租小屋\",\"无名面馆\"]},{\"key\":\"c032\",\"id\":32,\"title\":\"好想找个人来陪\",\"kind\":\"main\",\"volume\":1,\"start\":142,\"end\":145,\"summary\":\"病中熬完工作，苏雨晴获张阿姨赠感冒药，回到小屋却仍须独自洗澡处理家务。她强烈想家、渴望陪伴，一度产生轻生念头，又主动用未来可能有伴侣的希望压下。梦里公园外的城市出现末日暴乱，她逃回公园后被坠落物惊入黑暗。\",\"turn\":\"短暂自杀意念后自我制止；末日内容仅为梦境。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张阿姨\",\"莫空\"],\"objects\":[\"感冒药\",\"窗户\"],\"places\":[\"出租小屋\",\"梦中公园与街道\"]},{\"key\":\"c033\",\"id\":33,\"title\":\"和月橙的约定\",\"kind\":\"main\",\"volume\":1,\"start\":146,\"end\":149,\"summary\":\"次日苏雨晴退热恢复，工作也比初来时熟练。李叔叔说夫妻把她当孩子，专门做丰盛盖饭；张阿姨怀疑她原本就是女孩而以男装保护自己，她仍没有顺势隐瞒出生性别。下班后她用公用电话与月橙确定周一九点、广场首饰店松树下相见。\",\"turn\":\"雇主的照顾使生活暂时安稳，网友相见的具体时间地点也已确定。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"张思凡\",\"曲奇\"],\"objects\":[\"公共电话\",\"联系电话小本\"],\"places\":[\"无名面馆\",\"杂货店电话亭\"]},{\"key\":\"c034\",\"id\":34,\"title\":\"拥挤的早晨\",\"kind\":\"main\",\"volume\":1,\"start\":150,\"end\":153,\"summary\":\"三月十五日，苏雨晴兴奋早起准备首次见网友。为省钱她乘公交，在拥挤与异味中十分难受，险些错过下车。抵达中心广场外围后找不到入口，她终于鼓起勇气向环卫阿姨问路，获得帮助后前往约定地点。\",\"turn\":\"现实会面在即，她仍须克服问路与乘车带来的羞怯和紧张。\",\"time\":\"2004年3月15日星期一\",\"people\":[\"苏雨晴\",\"环卫阿姨\",\"公交司机\"],\"objects\":[\"白色鸭舌帽\",\"公交车票\"],\"places\":[\"公交车\",\"中心广场\"]},{\"key\":\"c035\",\"id\":35,\"title\":\"碰面\",\"kind\":\"main\",\"volume\":1,\"start\":154,\"end\":157,\"summary\":\"苏雨晴提前半小时来到松树下，月橙也早到却隔树焦急等待，两人起初彼此没有认出。确认身份后，月橙揭示自己正是此前金发女装熟客，本名张思凡。苏雨晴称她思思姐，逐渐消除紧张，二人从网络挚友转为现实朋友。\",\"turn\":\"清泉＝苏雨晴、月橙＝张思凡的身份链完整回收。\",\"time\":\"2004年3月15日\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"白色与淡黄色鸭舌帽\"],\"places\":[\"中心广场首饰店前松树\"]},{\"key\":\"c036\",\"id\":36,\"title\":\"百流山\",\"kind\":\"main\",\"volume\":1,\"start\":158,\"end\":161,\"summary\":\"张思凡解释自己在小城市读大学、靠父母汇款生活，瞒着家里用药两年，并担心出柜遭遇苏雨晴的处境。她答应送苏雨晴合身的巫女服。二人乘车去百流山，交流身份愿望、身体和家庭难题，随后开始攀登人烟稀少的山路。\",\"turn\":\"同类关系带来理解与互助，家庭接纳仍无解。\",\"time\":\"2004年3月15日\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"巫女服\"],\"places\":[\"公交车\",\"百流山\"]},{\"key\":\"c037\",\"id\":37,\"title\":\"纯黑色的蝴蝶\",\"kind\":\"main\",\"volume\":1,\"start\":162,\"end\":165,\"summary\":\"登山时，苏雨晴欣赏百流山特有的纯黑蝴蝶，谈起台湾外婆家和较包容的表亲。张思凡说明自己学计算机，希望日后能居家工作，也回忆曾是长跑体训队成员。二人对身体衰弱与手术经济门槛感到沮丧，最后把登顶当作坚持梦想的考验继续前行。\",\"turn\":\"互助登山映照身份追求；张思凡的体育与学业背景补齐。\",\"time\":\"2004年3月15日\",\"people\":[\"苏雨晴\",\"张思凡\",\"台湾外婆与表亲\"],\"objects\":[\"纯黑蝴蝶\",\"登山树枝\"],\"places\":[\"百流山\"]},{\"key\":\"c038\",\"id\":38,\"title\":\"山巅绝景\",\"kind\":\"main\",\"volume\":1,\"start\":166,\"end\":168,\"summary\":\"经过多次休息，苏雨晴和张思凡终于登顶，在山泉旁补水并欣赏云海。二人进入荒废小庙，对信仰与宗教商业化意见不同：无信仰的张思凡怀疑，受家族影响信佛的苏雨晴整理蒲团、虔诚祈求。她仍尊重朋友的不同看法，并教对方祈愿。\",\"turn\":\"登顶让共同坚持有了结果，苏也学习在信仰不同中尊重朋友。\",\"time\":\"2004年3月15日\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"山泉\",\"模糊佛像\",\"蒲团\"],\"places\":[\"百流山山顶\",\"山顶旧庙\"]},{\"key\":\"c039\",\"id\":39,\"title\":\"石铸的剑\",\"kind\":\"main\",\"volume\":1,\"start\":169,\"end\":172,\"summary\":\"小庙中两人继续讨论磨难与信仰，苏雨晴发现佛像后暗门，里面供奉刻有小篆“轮回”的石剑。外侧临崖走廊令她恐高，张思凡拥抱安慰后带她下山。她们乘车到郊区终点站，再骑电动车去张思凡住处，路途逐渐进入乡野。\",\"turn\":\"神秘石剑留下命运线索，山行结束后两人将进入更私人的生活空间。\",\"time\":\"2004年3月15日\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"轮回石剑\",\"寺庙暗门\",\"飞利浦电动车\"],\"places\":[\"百流山旧庙\",\"临崖走廊\",\"郊区终点站\"]},{\"key\":\"c040\",\"id\":40,\"title\":\"集装箱房\",\"kind\":\"main\",\"volume\":1,\"start\":173,\"end\":176,\"summary\":\"张思凡带苏雨晴到草地与树林旁的集装箱房，说明自己购箱装修、租地独居，生活清静但通勤很远。她邀请苏雨晴合住，后者因工作地点拒绝。洗漱过程中，张思凡数次玩笑与未经允许的身体接触使苏雨晴害羞不安，随后双方停止越界玩闹。\",\"turn\":\"看见另一种独立生活可能；朋友相处仍存在边界问题。\",\"time\":\"2004年3月15日\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"集装箱住宅\",\"玻璃门窗\",\"二手热水器\"],\"places\":[\"张思凡郊外集装箱房\"]},{\"key\":\"c041\",\"id\":41,\"title\":\"巫女服\",\"kind\":\"main\",\"volume\":1,\"start\":177,\"end\":180,\"summary\":\"张思凡拿出红白巫女服及配套衣物给苏雨晴试穿，尊重她想独自换装的要求。苏雨晴喜欢衣服，却被短发勾起难过；张思凡用纯黑长假发替她扎好马尾，鼓励她一起把真发留长。她解释自己的短发来自多次染发后主动重留。\",\"turn\":\"赠衣和假发缓解被剪发的伤心，真发留长仍需时间与安全空间。\",\"time\":\"2004年3月15日\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"红白巫女服\",\"黑色长假发\",\"牛皮筋\",\"哥特连衣裙\"],\"places\":[\"张思凡集装箱房\"]},{\"key\":\"c042\",\"id\":42,\"title\":\"野餐\",\"kind\":\"main\",\"volume\":1,\"start\":181,\"end\":184,\"summary\":\"二人穿女装到集装箱外草地野餐，合作搬火盆，吃烧烤火锅，讨论围院种花的生活。张思凡好奇苏雨晴家族，后者说家族有祖山与祠堂、众多规矩，成员关系复杂，因此不喜欢家族束缚。此处家族历史是人物讲述，不能当作已核实史实。\",\"turn\":\"田园野餐给她们片刻自在，苏也进一步说明自己与家族的疏离。\",\"time\":\"2004年3月15日\",\"people\":[\"苏雨晴\",\"张思凡\",\"苏氏家族\"],\"objects\":[\"野外火盆\",\"烧烤火锅\",\"家族族谱\"],\"places\":[\"集装箱外草地\",\"苏氏祖山与祠堂\"]},{\"key\":\"c043\",\"id\":43,\"title\":\"张思凡的生日\",\"kind\":\"main\",\"volume\":1,\"start\":185,\"end\":188,\"summary\":\"天黑后苏雨晴准备返家，张思凡低声请求她再陪一会儿，才说今天是自己二十岁生日。平日活泼的她流露独居孤单与惧怕父母得知身份的恐惧。苏雨晴替她插二十根蜡烛、唱生日歌，共享蛋糕，并答应留宿，由张思凡次日送她上班。\",\"turn\":\"张思凡的欢脱面具下显出脆弱，陪伴成为生日礼物。\",\"time\":\"2004年3月15日；张思凡20岁生日\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"老鼠造型生日蛋糕\",\"二十根蜡烛\",\"手提灯\"],\"places\":[\"张思凡集装箱房外草地\"]},{\"key\":\"c044\",\"id\":44,\"title\":\"同眠\",\"kind\":\"main\",\"volume\":1,\"start\":189,\"end\":192,\"summary\":\"张思凡谈自己喜欢黑夜，因为黑暗能遮掩不被理解的身份，并把她们比作不会发光的星。两人同睡，苏雨晴依偎朋友梦中唤母亲，梦见父母完全接纳自己。次晨因离工作地点远而急忙起床，张思凡送她衣物，并骑电动车赶往面馆。\",\"turn\":\"父母接纳仅为梦境；现实友情提供短暂家庭感。\",\"time\":\"2004年3月15日夜至16日晨\",\"people\":[\"苏雨晴\",\"张思凡\",\"苏雨晴父母（梦）\"],\"objects\":[\"巫女服礼物\",\"手机\",\"飞利浦电动车\",\"星空\"],\"places\":[\"集装箱房\",\"通往面馆的小路\"]},{\"key\":\"c045\",\"id\":45,\"title\":\"一个月\",\"kind\":\"main\",\"volume\":1,\"start\":193,\"end\":195,\"summary\":\"叙事跳过约一个月，苏雨晴逐渐适应工作与生活，头发变长，却反复嗜睡、醒时恍惚。她参考张思凡经验自行调整用药，医学描述仅属小说设定。暴雨休息日，曲奇浑身湿透前来避雨，竟带着此前那只幼鼠，显示猫已把它当伙伴。\",\"turn\":\"猫鼠天敌关系转为共处；生活稳定而身体负担持续。\",\"time\":\"约一个月后；与下一章4月19日日记相接\",\"people\":[\"苏雨晴\",\"张思凡\",\"曲奇\",\"咖啡\"],\"objects\":[\"闹钟\",\"药物\"],\"places\":[\"出租小屋\"]},{\"key\":\"c046\",\"id\":46,\"title\":\"咖啡\",\"kind\":\"main\",\"volume\":1,\"start\":196,\"end\":198,\"summary\":\"苏雨晴给曲奇和灰鼠清洗，逐渐放下对老鼠的嫌恶，给它取名咖啡。猫鼠互相照顾并接受喂食。她在四月十九日日记中写下张思凡忙学业、自己想买手机，也因父母一直没有消息而落泪；曲奇主动舔她脸颊，成为情绪上的安慰。\",\"turn\":\"咖啡得名；动物伙伴缓解被家人遗忘的感觉。\",\"time\":\"2004年4月19日星期一\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"张思凡\",\"苏雨晴父母\"],\"objects\":[\"猫用毛巾\",\"小鱼干\",\"日记\"],\"places\":[\"出租小屋\"]},{\"key\":\"c047\",\"id\":47,\"title\":\"普通的日子\",\"kind\":\"main\",\"volume\":1,\"start\":199,\"end\":201,\"summary\":\"暴雨中苏雨晴画下阴暗城市与上方一块留白的光，夹进日记。雨停后猫鼠离开，她打扫、晾衣，用劳动把小屋维持得温馨。洗澡后她再次换上张思凡赠的巫女服，正准备欣赏时，房东老虎突然敲门，令私人身份暴露风险骤然出现。\",\"turn\":\"绘画成为情绪表达；外界敲门打断私人自由。\",\"time\":\"2004年4月19日\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"老虎\"],\"objects\":[\"暴雨素描\",\"日记\",\"巫女服\"],\"places\":[\"出租小屋\"]},{\"key\":\"c048\",\"id\":48,\"title\":\"小混混\",\"kind\":\"main\",\"volume\":1,\"start\":202,\"end\":205,\"summary\":\"老虎来收二十三元水电费，苏雨晴慌忙藏好女装，房东又嫌她头发太长。午睡时她再梦见荒园男孩被打，答应以后帮忙。晚上她外出买嵌糕，抄近路穿小巷，遇见赌牌的绿毛、白狗等混混围堵，对方无视她要求离开的请求。\",\"turn\":\"梦中受欺凌与现实围堵相接，危险尚未解除。\",\"time\":\"2004年4月19日夜\",\"people\":[\"苏雨晴\",\"老虎\",\"梦中小男孩\",\"绿毛\",\"白狗\",\"黄毛混混\"],\"objects\":[\"水电费\",\"嵌糕\",\"扑克牌\"],\"places\":[\"出租小屋\",\"梦中公园\",\"夜市旁小巷\"]},{\"key\":\"c049\",\"id\":49,\"title\":\"勇敢还是胆小？\",\"kind\":\"main\",\"volume\":1,\"start\":206,\"end\":209,\"summary\":\"混混无视苏雨晴的拒绝，对她实施猥亵、强行脱衣并准备进一步性侵；她挥拳反抗却被压制。路过少年看似逃跑，实际去叫来保安，及时阻止侵害。苏雨晴脱险后向少年致谢，认识到害怕与勇敢可以并存，冷静求援同样能救人。\",\"turn\":\"已发生猥亵与羞辱；进一步侵害被保安制止，混混逃跑。\",\"time\":\"2004年4月19日夜\",\"people\":[\"苏雨晴\",\"绿毛\",\"白狗\",\"二黄\",\"救人少年\",\"保安们\"],\"objects\":[\"鸭舌帽\",\"保安警棍\"],\"places\":[\"夜市旁小巷\"]},{\"key\":\"c050\",\"id\":50,\"title\":\"曲奇，早安\",\"kind\":\"main\",\"volume\":1,\"start\":210,\"end\":213,\"summary\":\"受袭后苏雨晴做连环噩梦，梦见自己受辱，又见荒园男孩重伤并杀死多个与其长相相同的施暴者，对方向她追问是否明白。醒后曲奇与咖啡来访，跟她出门并一路到面馆，让她在创伤后的早晨感到被陪伴与守护。\",\"turn\":\"梦中杀人不是现实事件；动物陪伴开始进入工作场所。\",\"time\":\"受袭次日\",\"people\":[\"苏雨晴\",\"梦中小男孩\",\"曲奇\",\"咖啡\"],\"objects\":[\"梦中砖块\",\"冷开水\"],\"places\":[\"出租小屋\",\"梦中公园\",\"无名面馆\"]},{\"key\":\"c051\",\"id\":51,\"title\":\"曲奇相伴的工作\",\"kind\":\"main\",\"volume\":1,\"start\":214,\"end\":217,\"summary\":\"面馆夫妻接纳曲奇与咖啡，误以为咖啡是宠物鼠。苏雨晴熟练劳动并帮忙算账，莫空以整齐西装再来，教她简单心算技巧。他解释自己为维持生活暂做推销，喜欢尝试不同工作，又问她未来是否换工作、找男友，令她害羞。\",\"turn\":\"莫空呈现谋生压力与幽默，二人话题趋向私人生活。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"张阿姨\",\"李叔\",\"莫空\"],\"objects\":[\"账本\",\"草稿纸\",\"黑色西装\",\"薄荷糖\"],\"places\":[\"无名面馆\"]},{\"key\":\"c052\",\"id\":52,\"title\":\"被爱情抓住的张思凡\",\"kind\":\"main\",\"volume\":1,\"start\":218,\"end\":221,\"summary\":\"张思凡带孙昊来面馆，举止显出恋爱中的羞涩。孙昊是她在网上认识的变身小说作者，外表英俊、待人得体，却令苏雨晴感到不安。莫空借醋瓶即兴描述苏雨晴工作的样子，逗她开心；曲奇也认识莫空。孙昊对张思凡体贴中含不容拒绝的态度。\",\"turn\":\"孙昊进入关系网，与莫空形成相处方式的对照。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张思凡\",\"孙昊\",\"莫空\",\"曲奇\",\"咖啡\"],\"objects\":[\"醋瓶\",\"孙昊小说\"],\"places\":[\"无名面馆\"]},{\"key\":\"c053\",\"id\":53,\"title\":\"春祭\",\"kind\":\"main\",\"volume\":1,\"start\":222,\"end\":225,\"summary\":\"春祭使面馆连续繁忙，苏雨晴常走神、记单困难，下班累得进门即陷入半梦状态跌倒，幸被曲奇唤醒。猫鼠整夜陪伴，曲奇甚至替她关灯。周一休息日她洗晒衣被后想去附近孔庙，因缺少娱乐与钱，再次希望能拥有电脑。\",\"turn\":\"劳累影响状态，曲奇的照顾由陪伴转为具体帮助。\",\"time\":\"四月春祭；周日至次日周一\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"曲奇\",\"咖啡\"],\"objects\":[\"报单\",\"灯开关\",\"洗晒衣物\"],\"places\":[\"无名面馆\",\"出租小屋\"]},{\"key\":\"c054\",\"id\":54,\"title\":\"孔庙\",\"kind\":\"main\",\"volume\":1,\"start\":226,\"end\":229,\"summary\":\"苏雨晴带曲奇、咖啡沿田间小径到孔庙，遇到外表魁梧但说话温柔的陌生人。她对这种反差感到不适又觉亲切。曲奇爬上孔子像，她把猫抱下；返程遇见壮汉采映山红，对方热心分享花朵，减轻了她的陌生感。\",\"turn\":\"胡玉牛登场；苏雨晴也需面对自己的外貌成见。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"曲奇\",\"咖啡\"],\"objects\":[\"映山红\",\"孔子塑像\",\"银杏树\"],\"places\":[\"田野小径\",\"孔庙\",\"映山红花田\"]},{\"key\":\"c055\",\"id\":55,\"title\":\"两只思春的“少女”\",\"kind\":\"main\",\"volume\":1,\"start\":230,\"end\":233,\"summary\":\"壮汉自报胡玉牛，指明村中红色四层楼是住处，愿在她有困难时帮忙。苏雨晴来到河堤又遇张思凡，听她谈对孙昊既喜欢又不放心：孙昊明知其身份仍表白并专程探访，但有阴沉、占有欲强的一面。苏雨晴虽不喜欢他，仍试着鼓励朋友相信爱情。\",\"turn\":\"孙昊的不安信号已出现，二人尚以缺乏安全感解释。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张思凡\",\"孙昊\"],\"objects\":[\"孙昊赠包与假发\",\"电动车\"],\"places\":[\"孔庙附近村庄\",\"水库河堤\"]},{\"key\":\"c056\",\"id\":56,\"title\":\"张思凡和孙昊的情话\",\"kind\":\"main\",\"volume\":1,\"start\":234,\"end\":237,\"summary\":\"张思凡转述孙昊承诺娶她、赚钱一同移民，又担心承诺不真实。孙昊来电时，苏雨晴避开去河边，险些失足，被莫空及时拉回。她因莫空又不告而别而生气，与张思凡离开；结尾揭示莫空其实下水抓河蟹，浮出时才发现她们走了。\",\"turn\":\"离去误会来自信息差；张孙关系仍处甜蜜承诺期。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张思凡\",\"孙昊\",\"莫空\",\"曲奇\",\"咖啡\"],\"objects\":[\"电话\",\"青色河蟹\",\"电动车\"],\"places\":[\"水库河堤\"]},{\"key\":\"c057\",\"id\":57,\"title\":\"《我们所见到的就是真实吗？》\",\"kind\":\"main\",\"volume\":1,\"start\":238,\"end\":241,\"summary\":\"苏雨晴拒绝去张思凡家过夜，免得次日赶工，回程见曲奇与白猫亲近。她到新华书店读爱情小说，又被《我们所见到的就是真实吗？》吸引，思考感知、虚拟程序和身体身份。她既愿自己是真人，又幻想若是程序便能改变身体。\",\"turn\":\"虚拟世界哲学读物加入真实与梦境的主题线。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张思凡\",\"曲奇\",\"白猫\"],\"objects\":[\"《我们所见到的就是真实吗？》\",\"爱情小说\",\"梅干菜饼\"],\"places\":[\"新华书店\",\"出租小屋\"]},{\"key\":\"c058\",\"id\":58,\"title\":\"春梦\",\"kind\":\"main\",\"volume\":1,\"start\":242,\"end\":245,\"summary\":\"读物内容影响苏雨晴当夜梦境，引发生理反应与醒后的羞赧；该段是青春期体验，非现实亲密关系。洗漱后她精神较好，主动提早去面馆帮忙，迅速打包收款。新来的学生食客注意到她并议论外貌，她则只专注完成工作。\",\"turn\":\"苏雨晴更加主动熟练地劳动；旁人对她投射恋慕。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"学生食客\"],\"objects\":[\"闹钟\",\"小馄饨\"],\"places\":[\"出租小屋\",\"无名面馆\"]},{\"key\":\"c059\",\"id\":59,\"title\":\"路见不平一声吼\",\"kind\":\"main\",\"volume\":1,\"start\":246,\"end\":249,\"summary\":\"老板夫妻为儿子生日决定提前关门，给苏雨晴备好食物。她在《浙江日报》发现高度吻合自己的寻子启事，既因父母仍在找她而开心，又怕被带回限制身份选择，便带走报纸。去网吧途中，她听见混混报复当初叫保安的少年，准备求援。\",\"turn\":\"父母寻找出现证据；救人少年遭到混混报复。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"老板夫妇儿子\",\"救人少年\",\"绿毛等混混\"],\"objects\":[\"浙江日报寻人启事\",\"嵌糕\",\"生日蛋糕\"],\"places\":[\"无名面馆\",\"另一条小巷\"]},{\"key\":\"c060\",\"id\":60,\"title\":\"该出手时就出手\",\"kind\":\"main\",\"volume\":1,\"start\":250,\"end\":253,\"summary\":\"胡玉牛闯入小巷制服五名持械混混，莫空又及时挡开险些砸中苏雨晴的人。受伤少年拒绝去医院自行离开，仍未留名。胡玉牛面对莫空表现羞涩并想顺路同行，苏雨晴提醒自己不能因外形歧视别人。莫空告辞，胡玉牛让混混自叫救护车，众人分别。\",\"turn\":\"少年获救，混混受伤；胡玉牛对莫空的好感开始显露。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"莫空\",\"救人少年\",\"五名混混\",\"曲奇\",\"咖啡\"],\"objects\":[\"混混凶器\",\"莫空香烟\"],\"places\":[\"小巷\",\"出租小屋\"]},{\"key\":\"c061\",\"id\":61,\"title\":\"面馆老板的儿子\",\"kind\":\"main\",\"volume\":2,\"start\":255,\"end\":258,\"summary\":\"面馆夫妻为儿子过生日后晚开门，李叔叔趁清闲教苏雨晴煮面。两人的初三儿子李天明因学校活动提前放学到店，受到父母疼爱；他将苏雨晴认作漂亮女孩，主动搭讪并拉住她的手。苏雨晴担心误会，说明自己的出生性别，父母也予以证实，李天明随即变了态度。\",\"turn\":\"雇主家庭的新成员因性别信息产生排斥，破坏她在面馆的安全感。\",\"time\":\"李天明生日次日\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"李天明\",\"曲奇\",\"咖啡\"],\"objects\":[\"食谱\",\"嵌糕\"],\"places\":[\"无名面馆\"]},{\"key\":\"c062\",\"id\":62,\"title\":\"哭了\",\"kind\":\"main\",\"volume\":2,\"start\":259,\"end\":262,\"summary\":\"李天明得知苏雨晴的出生性别后出言羞辱，拒绝向她道歉，父母制止并教育他。苏雨晴受创跑出面馆，冲向河岸时产生轻生念头，却因绊倒而停在草地上痛哭。莫空见她流泪，留下陪伴并提供创可贴和纸巾；她没有说明真正的伤害来源，只借摔倒掩饰崩溃。\",\"turn\":\"莫空以陪伴暂时接住她的绝望；伤害未由施害者修复。\",\"time\":\"李天明来店当日\",\"people\":[\"苏雨晴\",\"李天明\",\"张阿姨\",\"李叔\",\"莫空\"],\"objects\":[\"创可贴\",\"纸巾\",\"擀面杖\"],\"places\":[\"无名面馆\",\"河堤\"]},{\"key\":\"c063\",\"id\":63,\"title\":\"烤螃蟹\",\"kind\":\"main\",\"volume\":2,\"start\":263,\"end\":266,\"summary\":\"莫空下水捉到两只螃蟹，在路边生火烤熟，与苏雨晴分食。食物和陪伴让她逐渐平静，也使她想起儿时被照顾的感觉。她羞怯询问他的住处，莫空只说以后有机会带她去，并提醒将下雨。她误以为遭到回避，决定当天不回面馆，以免再遇李天明。\",\"turn\":\"烤蟹成为关系中的温柔记忆；她仍害怕他人疏远。\",\"time\":\"河岸哭泣之后\",\"people\":[\"苏雨晴\",\"莫空\"],\"objects\":[\"螃蟹\",\"鞋带\",\"篝火\"],\"places\":[\"河堤\",\"公路边\"]},{\"key\":\"c064\",\"id\":64,\"title\":\"登门道歉\",\"kind\":\"main\",\"volume\":2,\"start\":267,\"end\":269,\"summary\":\"苏雨晴刚回租屋便遇到大雨，以临摹杯子练习绘画，幻想将来靠画画生活。张阿姨上门为儿子的侮辱道歉，带来牛奶、面包、巧克力等食物和《故事会》。苏雨晴从冷淡转为接受，愿意原谅张阿姨，却仍认为李天明本人应当认错。她整理食物，在雨夜独自阅读。\",\"turn\":\"雇主主动修复关系，但李天明的道歉仍然缺席。\",\"time\":\"河岸事件当日晚\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李天明\"],\"objects\":[\"素描纸\",\"杯子\",\"慰问食品\",\"《故事会》\"],\"places\":[\"出租小屋\"]},{\"key\":\"c065\",\"id\":65,\"title\":\"浑身的骨头都酸痛\",\"kind\":\"main\",\"volume\":2,\"start\":270,\"end\":273,\"summary\":\"苏雨晴梦见所有人排斥自己，又进入反复出现的公园。男孩以糖果压住内心痛苦，却承受身体疼痛；她把男孩理解为儿时的自己，把糖果联想到药物。男孩说自己杀害了各种欺凌他的人，使她害怕梦境映照被压抑的怨恨。醒来后她骨骼酸痛、乏力，现实中没有发生梦里的杀戮。\",\"turn\":\"她开始主动解释反复梦境，担忧伤害会侵蚀自己的温柔。\",\"time\":\"道歉后的夜晚\",\"people\":[\"苏雨晴\",\"梦中男孩\"],\"objects\":[\"梦中糖果\",\"梦中刀\"],\"places\":[\"梦中公园\",\"出租小屋\"]},{\"key\":\"c066\",\"id\":66,\"title\":\"就好像什么都没有发生\",\"kind\":\"main\",\"volume\":2,\"start\":274,\"end\":277,\"summary\":\"雨天早晨苏雨晴拖着不适的身体上班，面馆夫妻像往常一样招呼她吃早餐，让冲突后的关系恢复日常。空闲时她观看张阿姨绣“家”字，想起台湾外婆教过自己刺绣。张阿姨肯定男孩也能做这门手艺，教她绣十字并送了一套花猫图案的初学材料，给予实在的接纳。\",\"turn\":\"一门共同的手艺使她重新体验无需辩解的照顾。\",\"time\":\"道歉次日\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"苏雨晴外婆\"],\"objects\":[\"《故事会》\",\"家字十字绣\",\"花猫刺绣套件\"],\"places\":[\"无名面馆\",\"台湾外婆家（回忆）\"]},{\"key\":\"c067\",\"id\":67,\"title\":\"酒吧兼职（一）\",\"kind\":\"main\",\"volume\":2,\"start\":278,\"end\":281,\"summary\":\"周日收工时，李叔叔给苏雨晴和张阿姨煮云吞面；来访的张思凡吃炸酱面，并介绍一份从深夜到清晨的酒吧临时工作。薪资、奖金和分成吸引了想买手机的苏雨晴，她虽受父母说法影响而害怕酒吧，仍答应跟去。张思凡其实也未做过这份工作，两人骑车去面试。\",\"turn\":\"经济压力促使缺乏经验的两人进入陌生且有风险的工作环境。\",\"time\":\"一个周日夜；次日休假\",\"people\":[\"苏雨晴\",\"张思凡\",\"张阿姨\",\"李叔\"],\"objects\":[\"云吞面\",\"炸酱面\",\"电动车\"],\"places\":[\"无名面馆\",\"酒吧\"]},{\"key\":\"c068\",\"id\":68,\"title\":\"酒吧兼职（二）\",\"kind\":\"main\",\"volume\":2,\"start\":282,\"end\":285,\"summary\":\"酒吧的万董正在查顾总账目，顺便面试苏雨晴和张思凡。张思凡谎称两人都是大学生，万董看出年龄可疑仍让安排轻松工作。顾总带她们领制服，交由王主任管理。张思凡以男性装束被派去陪女客喝酒，苏雨晴穿女服务员制服送酒，两人分开进入不同房间。\",\"turn\":\"所谓轻松工作实际包含陪酒，管理层保护承诺未落实。\",\"time\":\"酒吧兼职当夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"万董\",\"顾总\",\"王主任\",\"酒吧保安\"],\"objects\":[\"酒吧制服\",\"储物柜钥匙\",\"酒单\"],\"places\":[\"酒吧办公室\",\"员工更衣室\",\"包厢\"]},{\"key\":\"c069\",\"id\":69,\"title\":\"酒吧兼职（三）\",\"kind\":\"main\",\"volume\":2,\"start\":286,\"end\":289,\"summary\":\"苏雨晴给二十七号包厢送酒，被三名男客要求陪饮；她不懂拒绝，又担心误工，被迫喝下啤酒。客人虽顾忌店内规矩，没有进一步强迫，她却在后续送酒中不断遭劝饮而晕眩。领班又让她给十四号贵宾送三杯鸡尾酒，使已经醉得不适的她接近更危险的处境。\",\"turn\":\"缺少拒绝与求助渠道，酒精令她逐步失去自我保护能力。\",\"time\":\"酒吧兼职当夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"二十七号包厢三名客人\",\"酒吧女领班\"],\"objects\":[\"啤酒\",\"龙舌兰日出鸡尾酒\"],\"places\":[\"酒吧二十七号包厢\",\"十四号贵宾区\"]},{\"key\":\"c070\",\"id\":70,\"title\":\"酒吧兼职（四）\",\"kind\":\"main\",\"volume\":2,\"start\":290,\"end\":293,\"summary\":\"十四号贵宾区的赵老板以小费为诱饵让苏雨晴喝完鸡尾酒，她失去意识后遭到性侵害。另一边张思凡受到三名女客的强迫触碰和性别羞辱，挣脱后决定离职，经过时发现苏雨晴受害。她准备冲上前阻止，莫空出现，表示由自己进入救人。\",\"turn\":\"两人遭遇侵害，张思凡与莫空开始紧急救援。\",\"time\":\"酒吧兼职当夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"赵老板\",\"赵老板同席客人\",\"十五号包厢三名女客\",\"莫空\"],\"objects\":[\"鸡尾酒\",\"小费\",\"支票\"],\"places\":[\"酒吧十四号贵宾区\",\"十五号包厢\"]},{\"key\":\"c071\",\"id\":71,\"title\":\"酒吧兼职（五）\",\"kind\":\"main\",\"volume\":2,\"start\":294,\"end\":297,\"summary\":\"莫空打退阻拦者和赵老板，抱走失去意识的苏雨晴，与张思凡从楼梯逃离。万董的儿子阿雷听说女服务员受欺负，命令保安停止追赶，万董也认可儿子的处理。莫空领两人穿过地下停车场和大润发仓库，又冒险取回电动车，准备送苏雨晴到张思凡住处休息。\",\"turn\":\"救援成功且追赶被叫停；阿雷父子的善意与酒吧失管并存。\",\"time\":\"酒吧逃离当夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"莫空\",\"赵老板\",\"万剑雷\",\"万董\",\"酒吧保安\",\"老管的儿子（提及）\"],\"objects\":[\"电动车\",\"红梅香烟\",\"打火机\"],\"places\":[\"酒吧楼梯\",\"地下停车场\",\"大润发仓库\"]},{\"key\":\"c072\",\"id\":72,\"title\":\"张思凡的心里话\",\"kind\":\"main\",\"volume\":2,\"start\":298,\"end\":301,\"summary\":\"莫空送两人回集装箱屋后独自步行等夜班公交，张思凡照顾醉酒的苏雨晴，因带她做危险兼职深感内疚，决定再不去酒吧。她向睡着的苏雨晴倾诉过去：曾想以富人的报酬换取手术费用，遭受严重虐待后逃离，却未拿到承诺的钱。今晚的羞辱重触旧创，两人相拥寻求安慰。\",\"turn\":\"张思凡的旧创与互助动机揭开；莫空默默承担救援善后。\",\"time\":\"酒吧逃离后的深夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"莫空\",\"曾虐待张思凡的富人\",\"夜班公交司机\"],\"objects\":[\"电动车\",\"夜班公交\"],\"places\":[\"张思凡的集装箱屋\",\"偏僻公交站\"]},{\"key\":\"c073\",\"id\":73,\"title\":\"宿醉\",\"kind\":\"main\",\"volume\":2,\"start\":302,\"end\":304,\"summary\":\"雨冷的周一早晨，张思凡为了照顾苏雨晴也放弃上课，同时为自己的拖延与前途发愁。苏雨晴宿醉醒来，一度以为上班迟到，听张思凡讲述莫空救人的经过后才理清零碎记忆。两人逃跑时把原来的衣服留在酒吧，张思凡找出一套黄白猫咪布偶装给她御寒，并准备煮食。\",\"turn\":\"苏雨晴确认获救经过；两人靠共同生活缓和受害后的不安。\",\"time\":\"酒吧兼职次日，星期一\",\"people\":[\"苏雨晴\",\"张思凡\",\"莫空\"],\"objects\":[\"猫咪布偶装\",\"遗落酒吧的衣物\",\"泡面\"],\"places\":[\"张思凡的集装箱屋\"]},{\"key\":\"c074\",\"id\":74,\"title\":\"钓鱼\",\"kind\":\"main\",\"volume\":2,\"start\":305,\"end\":308,\"summary\":\"两人吃水饺看新闻，谈论独居的孤单与城乡隐私差异。张思凡交还洗衣时发现的六百元小费，苏雨晴愿借给因买渔具超支的她，被婉拒；两人都决定不再去酒吧赚钱。张思凡带苏雨晴冒雨去河边试新鱼竿，合力支好大伞、组装渔具，笨拙但愉快地开始垂钓。\",\"turn\":\"金钱与陪伴互相支持；危险兼职告一段落，暂未遭追究。\",\"time\":\"酒吧兼职后的周一\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"六百元小费\",\"鱼竿\",\"遮阳伞\",\"猫咪布偶装\",\"小彩电\"],\"places\":[\"集装箱屋\",\"附近河湖岸\"]},{\"key\":\"c075\",\"id\":75,\"title\":\"悠扬的箫声\",\"kind\":\"main\",\"volume\":2,\"start\":309,\"end\":312,\"summary\":\"苏雨晴发现渔具箱里有张思凡买后弃学的洞箫，说明家族要求学习中国古乐器，吹奏《平沙落雁》，令对方安静下来。两人钓到一条草鱼，随后改玩双人GBA游戏。傍晚准备烤鱼时，信佛的苏雨晴不忍亲见杀生，张思凡也不会杀鱼，最终将鱼放回水中。\",\"turn\":\"苏的艺术才能与怜悯显现；张思凡的陪伴需求通过双份游戏物品呈现。\",\"time\":\"雨中钓鱼当日下午至傍晚\",\"people\":[\"苏雨晴\",\"张思凡\"],\"objects\":[\"洞箫\",\"平沙落雁\",\"草鱼\",\"GBA游戏机与双份卡带\",\"野外工具箱\"],\"places\":[\"集装箱屋附近河湖岸\"]},{\"key\":\"c076\",\"id\":76,\"title\":\"发工资\",\"kind\":\"main\",\"volume\":2,\"start\":313,\"end\":316,\"summary\":\"2004年4月29日，面馆午后清闲，苏雨晴认真擦净桌面后伏桌睡着。通宵写作的莫空来吃面，想起初见她的火车旅程，意识到自己珍惜她却没有占有欲，也想到将来离城的不舍。晚间夫妻提前发放三百元工资，李叔叔另给五十元让她改善饮食，肯定她的工作。\",\"turn\":\"劳动获得明确认可与资金；莫空的感情仍是珍惜和关照，未确立恋爱。\",\"time\":\"2004年4月29日，星期四\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"莫空\",\"曲奇\",\"咖啡\"],\"objects\":[\"三百元工资\",\"五十元补贴\",\"《故事会》\"],\"places\":[\"无名面馆\"]},{\"key\":\"c077\",\"id\":77,\"title\":\"逛夜市\",\"kind\":\"main\",\"volume\":2,\"start\":317,\"end\":320,\"summary\":\"发薪后苏雨晴逛夜市，测得身高一百五十厘米、体重四十四公斤。她用每天两元攒下的零花钱抽奖，得到黏性蜘蛛人、竹蜻蜓和夜光珠，又套中一盒国产EVA模型；蜘蛛人后来黏在雨棚上取不下来。她为毛绒玩具把剩余硬币投入娃娃机却一无所获，保留应急整钞回家。\",\"turn\":\"她在节制预算与儿童式愿望之间摇摆，经济独立没有抹去对玩具的喜爱。\",\"time\":\"4月29日晚\",\"people\":[\"苏雨晴\",\"夜市摊主\"],\"objects\":[\"身高体重小票\",\"黏性蜘蛛人\",\"竹蜻蜓\",\"夜光珠\",\"EVA拼装玩具\",\"娃娃机\"],\"places\":[\"小城市夜市\"]},{\"key\":\"c078\",\"id\":78,\"title\":\"预感\",\"kind\":\"main\",\"volume\":2,\"start\":321,\"end\":324,\"summary\":\"苏雨晴拼好EVA模型后失眠，感到既期待又害怕的不安；与此同时父母乘夜车赶往小城市寻找她。她早晨醒来有短暂的记忆混乱，稍后恢复；曲奇和咖啡从窗外回来，使她振奋并决定提早上班。叙述称猫鼠已有近半月未见，与前章面馆午睡画面存在连续性冲突。\",\"turn\":\"父母即将抵达；苏的预感是叙事照应，不构成超自然能力证据。\",\"time\":\"4月29日深夜至次日清晨\",\"people\":[\"苏雨晴\",\"苏榕槐\",\"苏雨晴的母亲\",\"曲奇\",\"咖啡\"],\"objects\":[\"EVA拼装玩具\",\"闹钟\"],\"places\":[\"出租小屋\",\"开往小城市的火车\"]},{\"key\":\"c079\",\"id\":79,\"title\":\"找寻\",\"kind\":\"main\",\"volume\":2,\"start\":325,\"end\":328,\"summary\":\"苏雨晴早到面馆，远远认出父母正向张阿姨打听自己。即使出示户口本，张阿姨仍拒绝泄露住处，要求等孩子本人确认。苏雨晴为父母憔悴而心疼，却害怕回家失去身份选择与自由，最终忍痛回屋收拾行李，留下让父母不要再找、当她不存在的纸条，准备再次逃离。\",\"turn\":\"她放弃已建立的生活以避免被带回家；家人关心与身份压迫继续纠缠。\",\"time\":\"推定2004年4月30日清晨\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"张阿姨\",\"曲奇\",\"咖啡\"],\"objects\":[\"户口本\",\"照片\",\"第二张离别纸条\",\"行李箱\"],\"places\":[\"无名面馆门外\",\"出租小屋\"]},{\"key\":\"c080\",\"id\":80,\"title\":\"逃离\",\"kind\":\"main\",\"volume\":2,\"start\":329,\"end\":331,\"summary\":\"苏雨晴带八百五十三元、全部可携行李和猫鼠从后门离开，乘公交去笃头村。车经过面馆时她忍住呼喊父母的冲动，在睡梦里得到家人接纳和手术成功的幸福，醒后确认只是愿望。她没有手机也不敢借电话，只能拖着重物沿乡间岔路寻找张思凡，花了一上午才到达。\",\"turn\":\"第二次出走失去工作和租屋，但保留朋友、积蓄与动物陪伴。\",\"time\":\"父母抵达当日清晨至午后\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"曲奇\",\"咖啡\"],\"objects\":[\"八百五十三元积蓄\",\"行李箱\",\"咪咪虾条\",\"矿泉水\"],\"places\":[\"出租屋后门\",\"公交车\",\"笃头村终点站\",\"乡间道路\"]},{\"key\":\"c081\",\"id\":81,\"title\":\"听风吹\",\"kind\":\"main\",\"volume\":2,\"start\":332,\"end\":335,\"summary\":\"张思凡正在给集装箱房围院子，看见苏雨晴带全部行李来投奔，欣然表示可以一直住下。苏雨晴洗澡后与她吃烤肉，终于说明父母已找来、自己选择躲避；张思凡理解却没有强迫她相认。叙述补充苏从小被禁止高声说话和表达愤怒，长期压抑也塑成如今胆怯温顺的习惯。\",\"turn\":\"朋友为第二次出走提供住处；被压抑的情绪背景得到补充。\",\"time\":\"搬来张思凡家当日午后\",\"people\":[\"苏雨晴\",\"张思凡\",\"苏雨晴父母\"],\"objects\":[\"行李箱\",\"围栏木桩\",\"木墩桌凳\",\"烤牛肉\",\"果汁\"],\"places\":[\"张思凡的集装箱屋\"]},{\"key\":\"c082\",\"id\":82,\"title\":\"院子\",\"kind\":\"main\",\"volume\":2,\"start\":336,\"end\":339,\"summary\":\"两人搭完木栅栏，讨论以后加建厨房、前院种花和后院种菜。张思凡欢迎曲奇与咖啡加入，洗澡后一起用纸箱做连通的小窝。苏雨晴接受照看花菜换三餐的约定，以劳动消除寄住的亏欠感。夜里她们谈父母不知情或不接纳的困境，各自羡慕对方又都害怕坦白后的结果。\",\"turn\":\"共同生活正式开始；互助建立在彼此认可而非单方面施舍上。\",\"time\":\"搬家当日傍晚至夜间\",\"people\":[\"苏雨晴\",\"张思凡\",\"曲奇\",\"咖啡\"],\"objects\":[\"木栅栏\",\"扩建铁皮材料\",\"连通纸箱宠物窝\"],\"places\":[\"集装箱屋前后院\"]},{\"key\":\"c083\",\"id\":83,\"title\":\"煮粥\",\"kind\":\"main\",\"volume\":2,\"start\":340,\"end\":343,\"summary\":\"搬来后的第一夜苏雨晴睡得安稳，翌日早起收拾张思凡忘盖药瓶而洒出的药片，又仔细打扫整个房间。曲奇与咖啡在院子追逐，并未真的反目。无班可上的她不愿白住，照着食谱尝试煮粥，随后在院里读书等张思凡起床，希望以家务回应收留之情。\",\"turn\":\"独立劳动习惯转化为共同生活中的照顾；煮粥结果尚待揭晓。\",\"time\":\"搬家次日早晨\",\"people\":[\"苏雨晴\",\"张思凡\",\"曲奇\",\"咖啡\"],\"objects\":[\"药瓶\",\"铁药盒\",\"食谱\",\"电饭煲\",\"榨菜\",\"咸鸭蛋\"],\"places\":[\"集装箱屋及院子\"]},{\"key\":\"c084\",\"id\":84,\"title\":\"黑暗料理\",\"kind\":\"main\",\"volume\":2,\"start\":344,\"end\":347,\"summary\":\"苏雨晴因看反电饭煲刻度把白粥煮糊，张思凡安慰后改在院里做早餐，却也把油条做成炸面团、煎蛋弄焦。两人索性试炸各种果蔬，闹出不少笑话；曲奇误尝油炸柠檬后避开，苏以吐司安抚并认真收拾卫生。她希望这样平静的生活能延续，远处有人忽然招呼她。\",\"turn\":\"生活技能不足没有破坏互助，家常失败反而带来放松与温暖。\",\"time\":\"搬家次日早晨至中午\",\"people\":[\"苏雨晴\",\"张思凡\",\"曲奇\",\"咖啡\",\"胡玉牛\"],\"objects\":[\"糊粥\",\"电饭煲\",\"油炸面团\",\"油炸果蔬\",\"吐司\"],\"places\":[\"集装箱屋院子\"]},{\"key\":\"c085\",\"id\":85,\"title\":\"又见胡玉牛\",\"kind\":\"main\",\"volume\":2,\"start\":348,\"end\":351,\"summary\":\"胡玉牛因来森林采药再次遇见苏雨晴，礼貌获准进入院子后与张思凡相识，共享午餐。张思凡刻意谈论体格，发现胡并不喜欢自己的强壮，反而羡慕她们的身材；胡想让人叫“小玉”又改口“老牛”。两人换上长裤，由胡带路进入屋后的树林，苏开始学习植物药材不止是草。\",\"turn\":\"胡玉牛加入朋友圈，其外貌与内心愿望的冲突逐渐浮现。\",\"time\":\"搬家次日午后\",\"people\":[\"苏雨晴\",\"张思凡\",\"胡玉牛\"],\"objects\":[\"牛仔裤\",\"登山杖\",\"采药背包\"],\"places\":[\"集装箱院子\",\"屋后森林\"]},{\"key\":\"c086\",\"id\":86,\"title\":\"隐藏在表相之下的灵魂\",\"kind\":\"main\",\"volume\":2,\"start\":352,\"end\":355,\"summary\":\"采药途中苏雨晴被兔子吓到，胡玉牛以荧光标记领路，耐心介绍结香与家传药方。他说明家族过去是卖武艺兼售跌打药的民间艺人，并非拥有神奇能力的武学世家，自己已不再学武。返家后张思凡判断胡内心向往女性，提醒苏不要凭外表衡量内心；此时胡尚未亲自确认。\",\"turn\":\"苏开始放下对胡举止的成见；身份判断仍须后续本人证实。\",\"time\":\"森林半日游至傍晚\",\"people\":[\"苏雨晴\",\"张思凡\",\"胡玉牛\",\"胡玉牛父亲（提及）\"],\"objects\":[\"荧光标记\",\"结香\",\"家传跌打药方\"],\"places\":[\"集装箱后森林\",\"小水潭\"]},{\"key\":\"c087\",\"id\":87,\"title\":\"步行街\",\"kind\":\"main\",\"volume\":2,\"start\":356,\"end\":358,\"summary\":\"张思凡陪苏雨晴去文澜学院旁的步行街买手机。苏因预算有限，在几款便宜机型中选中可接收电视的“NCKIA”山寨直板机；张思凡向熟识的年轻店主讲价，将五百元报价谈到三百六十元，又为她争取到八十元电话卡。苏获得第一部用自己钱买的手机，联系朋友终于方便了。\",\"turn\":\"手机解决失联与接送难题，同时消耗约一半积蓄。\",\"time\":\"搬家后一次购物日\",\"people\":[\"苏雨晴\",\"张思凡\",\"手机店老板\"],\"objects\":[\"NCKIA手机\",\"电话卡\",\"摩托罗拉翻盖手机\"],\"places\":[\"文澜学院旁步行街\",\"手机店\"]},{\"key\":\"c088\",\"id\":88,\"title\":\"张思凡的大学\",\"kind\":\"main\",\"volume\":2,\"start\":359,\"end\":362,\"summary\":\"买完手机后，张思凡又冲动花五百元买水冰月手办。两人在步行街看见一位穿文澜初中校服、极为美丽的少女，羡慕之余更显外貌焦虑。为省饭钱，张思凡带苏去自己就读的蓝阳大学文学社茶话会；学校环境破旧，社团却提供书籍与食物，苏拘谨地开始参与。\",\"turn\":\"苏接触同龄人与大学生活；美貌少女此时尚未揭名。\",\"time\":\"购买手机当日中午\",\"people\":[\"苏雨晴\",\"张思凡\",\"雯雯\",\"文学社社长\"],\"objects\":[\"水冰月手办\",\"奶茶\",\"文学社藏书\",\"茶点\"],\"places\":[\"步行街\",\"蓝阳大学\",\"文学社活动屋\"]},{\"key\":\"c089\",\"id\":89,\"title\":\"吟诗作对\",\"kind\":\"main\",\"volume\":2,\"start\":363,\"end\":366,\"summary\":\"文学社茶话会把古诗乱接成押韵笑话，连一向克制的苏雨晴也开怀大笑，重新向往中断的学业。张思凡指出一名清秀男生是校内唯一知晓其身份的好友，称对方有性别探索和偏爱跨性别者的倾向，又让苏别向孙昊告密。社员把苏当她妹妹，活动结束两人留下整理场地。\",\"turn\":\"苏体验群体欢乐但为辍学遗憾；张思凡亲密好友的名字尚未给出。\",\"time\":\"茶话会至下午四点\",\"people\":[\"苏雨晴\",\"张思凡\",\"文学社社长\",\"张思凡的文学社好友\",\"文学社社员\"],\"objects\":[\"古诗接句\",\"茶点\",\"历史书籍\"],\"places\":[\"蓝阳大学文学社\"]},{\"key\":\"c090\",\"id\":90,\"title\":\"园丁\",\"kind\":\"main\",\"volume\":2,\"start\":367,\"end\":370,\"summary\":\"苏雨晴照资料辛苦除草翻土，种下番薯和月季；张思凡铺鹅卵石小道，共同完善院子。劳累睡去的苏再次梦见荒废公园，梦中男孩为拒绝令人厌恶的世界而伤害自己的眼睛，使她恐惧并怀疑自己。曲奇叫醒她后，她发现张思凡因身体功能变化而发呆，开始询问对方心事。\",\"turn\":\"平静劳动与恐惧梦境并存；张思凡对身体变化的复杂情绪显露。\",\"time\":\"购物后的一日\",\"people\":[\"苏雨晴\",\"张思凡\",\"曲奇\",\"咖啡\",\"梦中男孩\"],\"objects\":[\"番薯种苗\",\"月季种子\",\"泥铲\",\"种植书\",\"鹅卵石小道\",\"摇椅\"],\"places\":[\"集装箱前后院\",\"梦中公园\"]},{\"key\":\"c091\",\"id\":91,\"title\":\"孙昊再一次前来\",\"kind\":\"main\",\"volume\":2,\"start\":371,\"end\":374,\"summary\":\"张思凡因身体变化而担忧自己未来的性别处境，称并非简单后悔，却仍感迷茫；苏雨晴一度害怕失去“同类”，也承认难以完全理解她。孙昊打电话说要再来，张思凡欣喜约好翌日接站。苏以不打扰情侣为由留家研究刺绣，心里仍对孙昊缺乏信任。\",\"turn\":\"孙昊的到来将改变两人独居节奏；朋友间也存在无法完全共感的差异。\",\"time\":\"五一已过；孙昊再访前一夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"孙昊\",\"曲奇\",\"咖啡\"],\"objects\":[\"NCKIA手机\",\"海鲜饼干\",\"牛奶\",\"十字绣\"],\"places\":[\"集装箱屋\"]},{\"key\":\"c092\",\"id\":92,\"title\":\"十字绣\",\"kind\":\"main\",\"volume\":2,\"start\":375,\"end\":377,\"summary\":\"张思凡早起化妆接孙昊，准备关东煮并留早餐纸条。苏醒来再有短暂混乱，想起梦见张思凡术后后悔，但清楚那只是自己担忧的投射。她打扫浇水，不愿擅动朋友电脑，下午完成熊猫十字绣，这是第一件成品；张阿姨赠的花猫作品则因匆忙搬家留在旧屋、去向不明。\",\"turn\":\"她以家务与手艺适应独处；梦中后悔不得当作张思凡真实手术结局。\",\"time\":\"孙昊再访当日早晨至下午\",\"people\":[\"苏雨晴\",\"张思凡\",\"曲奇\",\"咖啡\"],\"objects\":[\"早餐纸条\",\"关东煮\",\"熊猫十字绣\",\"遗留花猫十字绣\",\"手机\"],\"places\":[\"集装箱屋及院子\"]},{\"key\":\"c093\",\"id\":93,\"title\":\"小河边的莫空\",\"kind\":\"main\",\"volume\":2,\"start\":378,\"end\":381,\"summary\":\"下午三点张思凡发短信说夜里不归，苏雨晴虽然担忧孙昊是否真心，仍只能祝愿朋友幸福。她带猫鼠去乡间河边，偶遇徒步远行至此的莫空；曲奇显得与他熟悉。莫空给她原想用来戒烟的巧克力棒棒糖，边垂钓边解释过去常靠鱼充饥，准备只留够吃的鱼，其余放生。\",\"turn\":\"搬家后苏与莫空重新相遇，他的清贫与生存技能更具体。\",\"time\":\"孙昊再访当日下午\",\"people\":[\"苏雨晴\",\"张思凡\",\"孙昊\",\"莫空\",\"曲奇\",\"咖啡\"],\"objects\":[\"短信\",\"巧克力棒棒糖\",\"自制鱼竿\",\"草编鱼篓\",\"蚯蚓\"],\"places\":[\"集装箱院子\",\"笃头村附近河边\"]},{\"key\":\"c094\",\"id\":94,\"title\":\"张思凡和孙昊的不可描述\",\"kind\":\"main\",\"volume\":2,\"start\":382,\"end\":385,\"summary\":\"张思凡与孙昊牵手逛市中心，买龙凤糖人、叫花鸡和绿豆汤，观看夜市卖艺。她珍惜被当作女友的体验，刻意显得淑女，又因对方的体贴而放松。两人经过共同意愿的试探，进入小旅馆准备亲密相处；孙昊说自己没有过类似经历，张思凡因此更相信这段恋情。\",\"turn\":\"恋情进入更亲密阶段；张思凡对恋人真心的信任增加。\",\"time\":\"孙昊再访当日下午至夜间\",\"people\":[\"张思凡\",\"孙昊\",\"糖人摊主\",\"叫花鸡老汉\",\"夜市卖艺者\"],\"objects\":[\"龙凤糖人\",\"叫花鸡\",\"绿豆汤\",\"跌打损伤药\"],\"places\":[\"小城市中心广场\",\"老街\",\"小公园\",\"小旅馆\"]},{\"key\":\"c095\",\"id\":95,\"title\":\"小说和历史的区别\",\"kind\":\"main\",\"volume\":2,\"start\":386,\"end\":388,\"summary\":\"苏雨晴拿来调味料，与莫空在河岸烤鲈鱼和草鱼，也分给曲奇与咖啡。她欣赏莫空冷静细致的气质，害羞地找话题。莫空借《三国演义》说明现实并不保证努力得到圆满：英雄也会败亡、梦想也会未竟。苏把这番话联想到自己的愿望，因害怕未来无法实现而悄悄流泪。\",\"turn\":\"共同晚餐加深苏的好感，现实与故事的讨论却触动其命运焦虑。\",\"time\":\"孙昊再访当日夜间\",\"people\":[\"苏雨晴\",\"莫空\",\"曲奇\",\"咖啡\"],\"objects\":[\"烤鲈鱼\",\"烤草鱼\",\"调味料\",\"《三国演义》\"],\"places\":[\"笃头村附近河边\"]},{\"key\":\"c096\",\"id\":96,\"title\":\"胡玉牛来访\",\"kind\":\"main\",\"volume\":2,\"start\":389,\"end\":392,\"summary\":\"莫空离去、张思凡未归，苏独自看电视，思索命运与自由。她梦见一名作家在电脑上写出自己当下的动作，呈现故事内外互照，醒后仅留不安。次晨她吃小葱拌豆腐，准备日常事务时胡玉牛来访；开门受惊掉落的补佳乐药盒被胡盯住，她担心身份曝光后遭排斥。\",\"turn\":\"药盒意外使苏与胡进入身份坦白的关键时刻；元叙事仍属梦境。\",\"time\":\"孙昊再访当夜至翌晨\",\"people\":[\"苏雨晴\",\"莫空\",\"张思凡\",\"胡玉牛\",\"曲奇\",\"咖啡\",\"梦中写作者\"],\"objects\":[\"电视\",\"小葱拌豆腐\",\"补佳乐药盒\",\"维生素泡腾片\",\"钙片\"],\"places\":[\"集装箱屋\",\"梦中书桌\"]},{\"key\":\"c097\",\"id\":97,\"title\":\"被发现的秘密\",\"kind\":\"main\",\"volume\":2,\"start\":393,\"end\":395,\"summary\":\"胡玉牛认出补佳乐并说出“药娘”，苏雨晴才发现他也接触过被称为“新世界之门”的台湾论坛。胡因终于遇到同类而激动，询问自身改变的可能；苏说明不能只凭药物得到理想外貌，也倾诉自己十五岁出走的代价。胡随即讲出家族只剩自己一个男丁、被父祖期待继承武艺的压力。\",\"turn\":\"秘密曝光促成同类相认；外貌与家族继承构成胡的双重困境。\",\"time\":\"胡玉牛来访当日早晨\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"曲奇\",\"咖啡\",\"张思凡（提及）\",\"胡玉牛父亲与祖父\"],\"objects\":[\"补佳乐药盒\",\"新世界之门论坛\",\"清茶\"],\"places\":[\"集装箱院子\"]},{\"key\":\"c098\",\"id\":98,\"title\":\"胡玉牛的诉说\",\"kind\":\"main\",\"volume\":2,\"start\":396,\"end\":399,\"summary\":\"胡玉牛坦白自己不愿做家主或男子汉，只想作为普通女人生活。苏因担心他受更多伤害而劝阻，胡激烈反问自己为何没有选择权，冷静道歉后仍坚持离去。另一线张思凡与孙昊亲密过夜后送其返程，归家发现苏为胡的未来痛哭，便以选择并无错误安慰她，也安慰自己。\",\"turn\":\"胡自主选择的意愿明确；苏意识到关心也可能变成替别人作决定。\",\"time\":\"孙昊再访翌日\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张思凡\",\"孙昊\",\"曲奇\"],\"objects\":[\"清茶\",\"孙昊的背包\",\"肯德基薯条\"],\"places\":[\"集装箱院子\",\"小城市火车站\"]},{\"key\":\"c099\",\"id\":99,\"title\":\"平淡的田园生活\",\"kind\":\"main\",\"volume\":2,\"start\":400,\"end\":403,\"summary\":\"胡玉牛离开后苏雨晴郁闷两日才缓过来，照料菜苗时想念旧租屋、父母和面馆夫妻，却不知道他们的现状。张思凡与孙昊联系更密，女装也更频繁。苏清楚积蓄终会耗尽，计划找工作；张家生活费也将缩减，两人考虑搬回城里。熟稔后的苏更敢开玩笑，并肯定张作为女性的身份。\",\"turn\":\"田园停留终需经济出路；前雇主与父母在本段的后续仍未交代。\",\"time\":\"胡玉牛坦白后两日左右\",\"people\":[\"苏雨晴\",\"张思凡\",\"孙昊\",\"胡玉牛\",\"曲奇\",\"咖啡\"],\"objects\":[\"菜苗\",\"浇水壶\",\"旧屋墙字与贴纸\",\"梳子\",\"手机\"],\"places\":[\"集装箱院子\",\"旧租屋（回想）\"]},{\"key\":\"c100\",\"id\":100,\"title\":\"安静的田园生活\",\"kind\":\"main\",\"volume\":2,\"start\":404,\"end\":407,\"summary\":\"五月的一场暴雨把两人和猫鼠赶回屋里。她们登录论坛，苏厌恶争吵，张思凡却耐心回复新人的求助；她因热心获得“药娘导师”头衔，却自嘲不知自己前路。好友“优子”留言已决定来小城市生活，电话中说向父母借口外出工作。张思凡欢迎她入住，并提议三人共同进城求职合租。\",\"turn\":\"论坛互助延伸为现实同住，新成员即将加入。\",\"time\":\"2004年五月；方莜莜抵达前一日\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"曲奇\",\"咖啡\",\"论坛新人\"],\"objects\":[\"新世界之门论坛\",\"私信\",\"猫用沐浴露\",\"毛线球\"],\"places\":[\"集装箱屋\"]},{\"key\":\"c101\",\"id\":101,\"title\":\"方莜莜（上）\",\"kind\":\"main\",\"volume\":2,\"start\":408,\"end\":411,\"summary\":\"雨后张思凡唱武侠歌曲，苏与她玩双人小游戏；翌晨两人骑带备用电瓶的电动车去火车站接“优子”。苏重返初到小城的地点，对父母是否已放弃寻找作出未经证实的猜想。来客自报方莜莜，身高约一米六、气质温婉，与月橙张思凡相熟，首次见到“清泉”苏雨晴也感惊讶。\",\"turn\":\"方莜莜正式登场；线上三人首次在现实相聚。\",\"time\":\"优子来访前夜至翌日十一点二十分左右\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\"],\"objects\":[\"备用电瓶\",\"合金弹头小游戏\",\"《读者》\",\"沧海一声笑\"],\"places\":[\"集装箱屋\",\"小城市火车站\"]},{\"key\":\"c102\",\"id\":102,\"title\":\"方莜莜（下）\",\"kind\":\"main\",\"volume\":2,\"start\":412,\"end\":415,\"summary\":\"三人挤坐电动车返程，方莜莜先征求同意才抱住苏雨晴维持平衡，不追问她的家庭伤口，令苏感到尊重。方说明熟人众多的原城市让她疲惫，才选择异地生活。车辆连备用电瓶也耗尽，她们从笃头村总站步行，在炎热和口渴中抵达集装箱房，终于喝上冷饮休息。\",\"turn\":\"方的温和与边界感让苏迅速获得好感；三人生活开始。\",\"time\":\"方莜莜抵达当日中午至下午两点多\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\"],\"objects\":[\"电动车\",\"两块电瓶\",\"行李箱\",\"冰可乐\"],\"places\":[\"火车站至笃头村道路\",\"集装箱屋\"]},{\"key\":\"c103\",\"id\":103,\"title\":\"两个人都喝醉了\",\"kind\":\"main\",\"volume\":2,\"start\":416,\"end\":418,\"summary\":\"张思凡以烧烤招待方莜莜，两人热聊，苏因频繁走神误以为自己受到冷落，同时害怕安稳生活突然消失。她观察方温婉的举止，又想起胡玉牛的困境。张、方喝黄酒后醉倒，未饮酒的苏独自清理桌面，再费力把两人扶回房间；方中途醒来尽力自己走，三人终于休息。\",\"turn\":\"新关系引发苏对被忽略的焦虑，但她仍主动承担照顾。\",\"time\":\"方莜莜抵达当日晚至深夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"曲奇\",\"咖啡\"],\"objects\":[\"黄酒\",\"烧烤食材\"],\"places\":[\"集装箱院子及卧室\"]},{\"key\":\"c104\",\"id\":104,\"title\":\"三人同眠\",\"kind\":\"main\",\"volume\":2,\"start\":419,\"end\":421,\"summary\":\"三人同床休息，方莜莜严重失眠，直到凌晨才睡着。平行叙事中，莫空登上小城最高写字楼，冒风雨俯瞰城市，思索观察者也终究是故事中人。苏梦见社会与家人完全接纳自己，手术、婚姻及领养孩子皆圆满实现，清醒后怅然；这些幸福明确是梦境，没有发生于现实线。\",\"turn\":\"作者旁观视角与苏的理想生活互照，现实前景依然未定。\",\"time\":\"方莜莜抵达当夜至翌晨\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"莫空\"],\"objects\":[\"红梅香烟\",\"啤酒\",\"漫画\"],\"places\":[\"集装箱卧室\",\"小城市最高写字楼楼顶\",\"梦中海边之家\"]},{\"key\":\"c105\",\"id\":105,\"title\":\"连绵的阴雨天\",\"kind\":\"main\",\"volume\":2,\"start\":422,\"end\":425,\"summary\":\"连绵阴雨里，张思凡与带着上网本的方莜莜玩《传奇》，苏雨晴感到像局外人，借GBA玩农场游戏却因电池耗尽丢失两小时进度。方察觉她的无聊，主动让出电脑并去做饭，表示既然同住就是一家人。集装箱二层厨房此时已请人装好，雨天烹饪不再受露天火盆限制。\",\"turn\":\"方主动纳入苏，缓解三人相处的不平衡，并开始承担厨房事务。\",\"time\":\"方莜莜抵达翌日雨天\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"曲奇\",\"咖啡\"],\"objects\":[\"迷你上网本\",\"GBA与充电电池\",\"农场游戏\",\"传奇\",\"二层厨房\"],\"places\":[\"集装箱屋及二层厨房\"]},{\"key\":\"c106\",\"id\":106,\"title\":\"方莜莜的厨艺\",\"kind\":\"main\",\"volume\":2,\"start\":426,\"end\":429,\"summary\":\"苏试玩《传奇》后仍不感兴趣，转去厨房请求方莜莜教做菜。方鼓励她练切黄瓜，容许笨拙并耐心示范，两人完成凉拌黄瓜、丝瓜汤等午餐。方的清淡口味让苏多吃了饭，却让偏好辛辣的张思凡不习惯。方愿以后负责烹饪，并透露自己比张大一岁、自行用药约三年。\",\"turn\":\"方的照料与苏的学习建立稳定协作；年龄可推为方21、张20。\",\"time\":\"方莜莜抵达翌日午间\",\"people\":[\"苏雨晴\",\"方莜莜\",\"张思凡\"],\"objects\":[\"凉拌黄瓜\",\"丝瓜汤\",\"炒鸡蛋\",\"红烧狮子头\",\"传奇女道士角色\"],\"places\":[\"集装箱二层厨房\",\"餐桌\"]},{\"key\":\"c107\",\"id\":107,\"title\":\"找工作\",\"kind\":\"main\",\"volume\":2,\"start\":430,\"end\":432,\"summary\":\"三人赴城里中介找工作，商务英语毕业的方莜莜及在读大学生张思凡选择较多；十五岁、未读完初中且身份证遗失的苏屡受限制。快餐岗位已满、酒店迎宾因身高和幼态被拒，她仍不愿由朋友供养，最终获大润发理货员职位，月薪一千五百，要求三天内报到。\",\"turn\":\"苏重新获得工作，收入高于面馆；所承诺社保随后因无身份证被改为补贴。\",\"time\":\"方莜莜抵达第三日\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"工作中介老板\",\"酒店经理\",\"大润发人事经理\"],\"objects\":[\"招聘纸条\",\"联系电话\",\"就业资料\"],\"places\":[\"职业中介\",\"酒店\",\"大润发\",\"白兔街周边\"]},{\"key\":\"c108\",\"id\":108,\"title\":\"租房子\",\"kind\":\"main\",\"volume\":2,\"start\":433,\"end\":435,\"summary\":\"张思凡获月薪两千的账本录入校对兼职，方莜莜凭资格证入小商品市场做网络维修部门组长；苏填女性资料入职，但因无身份证未办理五险一金。三人找房时遇到刚做大润发装卸工的胡玉牛，决定一起整租六间房。总租金一千五，张与方各付五百，苏与胡各付二百五十，组成四人互助家庭。\",\"turn\":\"四人合租定案；胡已找到月薪1600装卸工作，与苏成同事。\",\"time\":\"求职当日下午\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"合租房房东\"],\"objects\":[\"资格证书\",\"租房广告\",\"合租钥匙\"],\"places\":[\"白兔街附近小区\",\"六室合租房\",\"大润发\",\"小商品市场\"]},{\"key\":\"c109\",\"id\":109,\"title\":\"安眠药\",\"kind\":\"main\",\"volume\":2,\"start\":436,\"end\":439,\"summary\":\"四人正式互相介绍、分配六把钥匙，约好翌日搬家。胡玉牛确认坚持性别转变，张思凡给予支持，也承认任何人的未来都无法保证圆满。回程三人因各自道路而低落，苏重想莫空的鱼鹰故事。夜里苏先睡着，受失眠折磨的张和方自行服用安眠药后才入睡，反映共同生活背后的身体压力。\",\"turn\":\"胡的选择被接纳，但三人都无法消除各自对前途的恐惧。\",\"time\":\"找到工作和租屋当日夜间\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"合租房钥匙\",\"安眠药\",\"手机俄罗斯方块\",\"鱼鹰故事\"],\"places\":[\"合租房\",\"回郊区公交车\",\"集装箱卧室\"]},{\"key\":\"c110\",\"id\":110,\"title\":\"搬家\",\"kind\":\"main\",\"volume\":2,\"start\":440,\"end\":443,\"summary\":\"三人收拾行李，带曲奇和咖啡告别田园小屋，步行、公交再转出租前往白兔街白兔小区。她们租住七层无电梯楼房的顶层，张思凡因物品太多而力竭，先到的胡玉牛帮忙搬上楼。六间房四人自选，方、张、苏依次住同侧相邻房间，苏选中最里面有两扇窗的一间。\",\"turn\":\"四人城市合住正式开始；郊区小屋仍在租期内，可日后回访。\",\"time\":\"求职次日搬家日\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"曲奇\",\"咖啡\",\"出租车司机\"],\"objects\":[\"行李箱\",\"手办\",\"旧球鞋\",\"菜苗与月季\"],\"places\":[\"集装箱屋\",\"笃头村总站\",\"白兔街白兔小区七楼合租房\"]},{\"key\":\"c111\",\"id\":111,\"title\":\"布置自己的新家\",\"kind\":\"main\",\"volume\":2,\"start\":444,\"end\":447,\"summary\":\"四人合力擦去房屋灰尘，苏布置独立卧室，把日记和钱分处收好、药盒放进抽屉，并摆上张思凡送的水冰月手办。屋内仅客厅有空调，众人商量买凉席或被褥等用品。午后方撑伞护住三人，胡独走在阳光下；她们到大润发采购，发现还需添置许多生活工具，预算有些吃紧。\",\"turn\":\"苏重新拥有私人房间，也融入可互助的共同客厅与厨房。\",\"time\":\"搬家日午后\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"水冰月手办\",\"日记\",\"药盒\",\"遮阳伞\",\"床垫被褥\",\"清洁工具\",\"烧水用具\"],\"places\":[\"白兔小区合租房\",\"大润发\"]},{\"key\":\"c112\",\"id\":112,\"title\":\"梦见一场大雨\",\"kind\":\"main\",\"volume\":2,\"start\":448,\"end\":451,\"summary\":\"苏领取两件红色大润发夏季工作服，采购后在方莜莜指导下做晚餐，却不慎划伤手指。张思凡以女装出席晚饭，胡玉牛羡慕其声音与装扮；大家愿教他练声化妆，并正式采用他接受的昵称“小玉”。夜里众人为首日上班早睡，苏梦见独困暴雨、无力前行，现实并未发生梦中死亡。\",\"turn\":\"小玉得到名字上的认可；新工作的期待与无助梦境并行。\",\"time\":\"搬家日傍晚至入职前夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"大润发红色工作服\",\"菜刀\",\"创可贴\",\"黑色褶裙\"],\"places\":[\"大润发\",\"白兔小区合租房\",\"梦中空城\"]},{\"key\":\"c113\",\"id\":113,\"title\":\"大清早\",\"kind\":\"main\",\"volume\":2,\"start\":452,\"end\":454,\"summary\":\"苏雨晴五点起床，为大润发第一天工作准备。她穿方莜莜买的朴素女式衬衫，首次使用旧同桌赠的七格星期发卡，回忆那份生日礼物曾使她感到同龄人的关心。胡玉牛耐心等她一起出门，两人买包子边走边吃；谈及身材时苏又意识到自己的话可能触动胡，及时道歉。\",\"turn\":\"苏更主动以女性形象工作；旧同桌礼物连接被珍惜的过往。\",\"time\":\"大润发入职第一日，清晨五点起\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"苏雨晴原同桌\",\"曲奇\",\"咖啡\"],\"objects\":[\"鸟鸣闹钟\",\"女式衬衫\",\"星期发卡\",\"栗色发卡\",\"包子豆奶\"],\"places\":[\"合租房\",\"白兔街至大润发道路\"]},{\"key\":\"c114\",\"id\":114,\"title\":\"初次在超市上班\",\"kind\":\"main\",\"volume\":2,\"start\":455,\"end\":458,\"summary\":\"苏与胡从大润发员工通道进入，苏避开拥挤女更衣室，在卫生间换制服，再与胡打卡。胡去二楼后仓，苏找到主管张燕，被转交给员工指导姚玲，再由“百事”长期促销员带学分货与补货。她接触庞大的六层商场布局，面对流程与新同事既好奇又紧张。\",\"turn\":\"新的劳动关系建立；她被视作女孩，但仍害怕被注目。\",\"time\":\"大润发入职第一日，五点四十五分起\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张燕\",\"姚玲\",\"百事促销员\",\"大润发其他员工\"],\"objects\":[\"红制服\",\"员工卡\",\"商品货柜\",\"价格标签\"],\"places\":[\"大润发员工区\",\"更衣室\",\"二楼干货区与后仓\"]},{\"key\":\"c115\",\"id\":115,\"title\":\"第一天的工作\",\"kind\":\"main\",\"volume\":2,\"start\":459,\"end\":462,\"summary\":\"百事促销员耐心教苏核对条码、规格和货架位置，苏为隐藏未成年而称自己十八岁。忙至九点后，她受命寻找需要帮助的同事，却因羞怯漫无目的；一名矮个男员工的薯片箱砸到她，她只觉其道歉带着戏弄。最后她主动去帮白发老伯搬米，寻找能安心投入的工作。\",\"turn\":\"苏学习能力不差，体力与沟通却吃力；结识友善长辈的契机出现。\",\"time\":\"入职第一日早晨至上午\",\"people\":[\"苏雨晴\",\"百事促销员\",\"张燕\",\"胡玉牛\",\"王海峰\",\"夏仕尼\"],\"objects\":[\"饮料\",\"食用油\",\"薯片纸箱\",\"大米\",\"商品条码\"],\"places\":[\"大润发二楼干货区与后仓\"]},{\"key\":\"c116\",\"id\":116,\"title\":\"矮个子一米六\",\"kind\":\"main\",\"volume\":2,\"start\":463,\"end\":466,\"summary\":\"苏坚持帮老伯搬完十袋米，累得气喘，老伯温和劝她慢慢做并承担重活。他自我介绍夏仕尼，耐心回答顾客与苏的问题，午间教她用员工卡买优惠盒饭。付款时又遇到早先的矮个男员工，其调侃让苏恼火，却也提醒她带上通行所需小票。夏老伯随后邀她同桌吃饭。\",\"turn\":\"夏仕尼成为工作中的可靠引导者；矮个员工的戏谑关系尚未明朗。\",\"time\":\"入职第一日上午至中午\",\"people\":[\"苏雨晴\",\"夏仕尼\",\"王海峰\",\"超市顾客\"],\"objects\":[\"大米\",\"筒面\",\"笼车\",\"员工卡\",\"三元盒饭\",\"小票\"],\"places\":[\"大润发二楼\",\"熟食区\",\"酒柜收银台\",\"员工餐厅\"]},{\"key\":\"c117\",\"id\":117,\"title\":\"瓢盆大雨\",\"kind\":\"main\",\"volume\":2,\"start\":467,\"end\":470,\"summary\":\"胡玉牛为省钱吃泡面，苏告诉他员工餐优惠，并小心分享未碰过的鸡块。夏仕尼误会二人恋爱，苏澄清只是合租伙伴。老伯说自己曾为老板开车，因公司破产来超市工作，再两年退休。下午苏慢慢更换价签，胡为加班费继续搬货，她下班时发现外面已下大雨。\",\"turn\":\"同住者分享食物与信息；苏独自返家，将遇暴雨考验。\",\"time\":\"入职第一日午后至约下午三点\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"夏仕尼\",\"张燕\"],\"objects\":[\"泡面\",\"鸡块\",\"员工卡\",\"替换价签\"],\"places\":[\"大润发员工餐厅\",\"货架区\",\"后仓\",\"员工出口\"]},{\"key\":\"c118\",\"id\":118,\"title\":\"挡住风的他和遮住雨的伞\",\"kind\":\"main\",\"volume\":2,\"start\":471,\"end\":473,\"summary\":\"没带伞的苏雨晴下班后冒雨回家，在红灯路口被狂风暴雨逼得蹲下。莫空忽然站在她前方挡风，把黑色雨伞递给她，只嘱路上小心便离去。苏握着带余温的伞平安回家，期待下次相遇时归还，也更强烈地意识到自己的心动；伞到本段结束仍在她手中。\",\"turn\":\"莫空的照顾转化为苏明确的期待与好感，赠伞留下再次相见的理由。\",\"time\":\"入职第一日下午三点左右\",\"people\":[\"苏雨晴\",\"莫空\"],\"objects\":[\"黑色雨伞\",\"湿透的旧球鞋\"],\"places\":[\"大润发至白兔小区路口\",\"合租房浴室\"]},{\"key\":\"c119\",\"id\":119,\"title\":\"雨鞋\",\"kind\":\"main\",\"volume\":2,\"start\":474,\"end\":477,\"summary\":\"唯一的球鞋湿透后，苏担心次日没鞋穿，先给同样淋雨回家的胡递毛巾，再打电话请张思凡代买。她趁等待练习已学会的煮饭。张回来提醒她本可在超市买伞，并带来三十六码短雨鞋，十元不必偿还，只开玩笑要她帮打扫房间；苏将莫空的伞留身边等归还。\",\"turn\":\"互助落实在生活急需上；苏开始掌握能独立完成的厨房技能。\",\"time\":\"入职第一日下班后\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张思凡\",\"莫空（回想）\"],\"objects\":[\"旧球鞋\",\"干毛巾\",\"手机\",\"简单电饭煲\",\"三十六码短雨鞋\",\"黑伞\"],\"places\":[\"白兔小区合租房\"]},{\"key\":\"c120\",\"id\":120,\"title\":\"扫码的工作\",\"kind\":\"main\",\"volume\":2,\"start\":478,\"end\":481,\"summary\":\"临近六月，梅雨连绵。方莜莜下班后指导苏雨晴完成番茄蛋花汤，张思凡称赞，使苏获得做饭的成就感；胡仍为身体与脚码难改变而失落。翌日超市没有货柜，胡与后仓同事逐渐熟悉，张燕则教苏用便携终端扫描核价、打印新标签。细致且可独自完成的工作令苏暂觉自在。\",\"turn\":\"四人工作与生活初步稳定，苏的技能、自信缓慢增长。\",\"time\":\"2004年五月末、临近六月；首日工作晚至翌日\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"张燕\",\"后仓同事\"],\"objects\":[\"番茄蛋花汤\",\"便携扫码终端\",\"标签打印机\",\"价签\"],\"places\":[\"白兔小区厨房\",\"大润发二楼酱料区\"]},{\"key\":\"c121\",\"id\":121,\"title\":\"冉空城\",\"kind\":\"main\",\"volume\":2,\"start\":482,\"end\":485,\"summary\":\"苏雨晴在超市核价时回忆初中同桌冉空城：他曾主动交换手机号码，她因自卑与朦胧感情而推托。语文课替他提示答案后，两人遭同学羞辱，雨晴怕失去唯一的朋友。冉空城却当面斥责欺凌者，明确维护她，使这段校园记忆成为离家后仍珍惜的温暖。\",\"turn\":\"同桌主动维护她；当年没有交换号码留下遗憾。\",\"time\":\"星期五上午；回忆初中\",\"people\":[\"苏雨晴\",\"冉空城\",\"夏仕尼\",\"初中同学\",\"语文老师\"],\"objects\":[\"标签打印机\",\"发卡\",\"摩托罗拉翻盖手机\"],\"places\":[\"超市\",\"初中教室\"]},{\"key\":\"c122\",\"id\":122,\"title\":\"羡慕？嫉妒？\",\"kind\":\"main\",\"volume\":2,\"start\":486,\"end\":489,\"summary\":\"夏老伯体谅雨晴，让她慢慢完成核价。她为更换高处标签跳跃时撞倒一名普通少年，又为来寻人的漂亮女孩指路；女孩的外貌、声音与举止激起她强烈的羡慕和身体自卑。两名客人的关系并未证实，她关于两人会错过的直觉也只是自己的想象。\",\"turn\":\"陌生女孩强化了雨晴对自身女性形象的渴望。\",\"time\":\"同一星期五上午\",\"people\":[\"苏雨晴\",\"夏仕尼\",\"普通少年\",\"雯雯\"],\"objects\":[\"标签打印机\",\"价格标签\",\"电脑光碟\"],\"places\":[\"超市二楼\",\"超市三楼\"]},{\"key\":\"c123\",\"id\":123,\"title\":\"胡玉牛的面点手艺\",\"kind\":\"main\",\"volume\":2,\"start\":490,\"end\":493,\"summary\":\"下班路上，胡玉牛坦言羡慕能自然拥有女性身份和恋爱生活的女孩。回家后，他熟练制作饺子、烧麦与酸辣汤，细致厨艺得到雨晴及室友们赞赏；他仍羡慕雨晴柔嫩的手。雨晴随后出现身体不适，准备向朋友询问，温暖合住生活与身体焦虑并行。\",\"turn\":\"阿牛用厨艺融入家庭，雨晴的用药不适引出调整。\",\"time\":\"同一星期五下午至晚餐\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张思凡\",\"方莜莜\"],\"objects\":[\"饺子\",\"烧麦\",\"酸辣汤\",\"雨鞋\"],\"places\":[\"回家街道\",\"合租屋厨房\"]},{\"key\":\"c124\",\"id\":124,\"title\":\"拨通了的号码\",\"kind\":\"main\",\"volume\":2,\"start\":494,\"end\":497,\"summary\":\"晚餐后张思凡将未拆封的色谱龙赠给身体不适、经济拮据的雨晴，室友们又围绕洗碗打趣。独处时雨晴从冉空城所赠发卡袋里发现久藏的电话号码，拨通后听见他的声音却哭着挂断。冉空城疑似认出她而失神；回忆揭示他曾用数学小游戏探出生日并送她发卡。\",\"turn\":\"隐藏号码恢复联系的可能，但雨晴尚未敢表明身份。\",\"time\":\"星期五夜晚\",\"people\":[\"苏雨晴\",\"冉空城\",\"张思凡\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"色谱龙\",\"发卡袋\",\"电话号码纸条\",\"手机\"],\"places\":[\"合租屋\",\"游戏厅\"]},{\"key\":\"c125\",\"id\":125,\"title\":\"一夜未眠\",\"kind\":\"main\",\"volume\":2,\"start\":498,\"end\":501,\"summary\":\"雨晴因通话而整夜追忆初中，猫曲奇与咖啡陪在床边。她曾因沉浸身份探索而成绩下滑，被父母安排重读初二；冉空城也来到原班陪伴，她猜他为自己留级，双方没有说破。天将亮才睡着的雨晴险些误工，胡玉牛进房将她叫醒并扶住险些跌倒的她。\",\"turn\":\"冉空城的陪伴分量加深；缺觉开始影响现实工作。\",\"time\":\"星期五夜至星期六清晨；回忆初二留级\",\"people\":[\"苏雨晴\",\"冉空城\",\"苏雨晴父母\",\"胡玉牛\",\"曲奇\",\"咖啡\"],\"objects\":[\"手机\",\"新世界之门论坛\",\"课本\",\"闹钟\"],\"places\":[\"合租屋卧室\",\"初中教室\"]},{\"key\":\"c126\",\"id\":126,\"title\":\"浑浑噩噩的感觉\",\"kind\":\"main\",\"volume\":2,\"start\":502,\"end\":505,\"summary\":\"睡眠不足的雨晴由胡玉牛一路扶到超市，又在女更衣室旧沙发上睡着。她勉强上岗时抽动货箱，险遭上层重物砸伤，幸被夏老伯及时挡住。夏老伯替她承担重活、安排休息，还在主管张燕询问时维护她，使陌生职场出现近似长辈照护的支持。\",\"turn\":\"疲惫暴露工作危险，夏老伯成为可信赖的保护者。\",\"time\":\"星期六上午\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"夏仕尼\",\"张燕\"],\"objects\":[\"员工卡\",\"旧沙发\",\"油箱\",\"笼车\"],\"places\":[\"超市更衣室\",\"货柜区\"]},{\"key\":\"c127\",\"id\":127,\"title\":\"超薄弹力贴身\",\"kind\":\"main\",\"volume\":2,\"start\":506,\"end\":509,\"summary\":\"夏老伯继续帮缺觉的雨晴挡下险落的货物，并让她午间补眠、替她应付主管。雨晴醒来后饥饿，得知新排班已发布，便买促销泡面；为避开拥挤收银处寻找三楼化妆品柜台，却走进女性用品区。她对领导的害怕又引出昔日误以为受罚、实为作文获奖的回忆。\",\"turn\":\"有人替她承担工作压力；意外进入用品区触发身份体验。\",\"time\":\"星期六中午至下午\",\"people\":[\"苏雨晴\",\"夏仕尼\",\"张燕\",\"班主任\"],\"objects\":[\"酱油箱\",\"排班表\",\"促销泡面\",\"作文奖状\"],\"places\":[\"超市员工餐厅\",\"超市三楼\"]},{\"key\":\"c128\",\"id\":128,\"title\":\"七度空间少女系列\",\"kind\":\"main\",\"volume\":2,\"start\":510,\"end\":513,\"summary\":\"雨晴在忐忑中买下七度空间卫生用品，收银员将她当作羞怯少女，平常地完成结账；离开时按制度接受小票检查。她与阿牛下班回到室友身边，吃过简便晚餐，夜里独自尝试新购物品，从中获得被女性生活接纳的象征性安慰与安全感。\",\"turn\":\"一次普通而顺利的购买，让雨晴短暂体验到女性日常的归属与接纳。\",\"time\":\"星期六下午至夜\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张思凡\",\"方莜莜\",\"三楼收银员\",\"门岗女员工\",\"曲奇\"],\"objects\":[\"七度空间\",\"泡面\",\"购物小票\",\"速冻馄饨\"],\"places\":[\"超市收银台\",\"员工餐厅\",\"合租屋\"]},{\"key\":\"c129\",\"id\":129,\"title\":\"工作的日常（上）\",\"kind\":\"main\",\"volume\":2,\"start\":514,\"end\":517,\"summary\":\"雨晴醒来发现身体不适并非梦中转变，对镜观察自身变化后仍被外貌比较困扰。周日上班她得知周一休息、随后轮到晚班；夏老伯休假令她失去依靠。员工指导姚玲主动带她处理退货单据，肯定她娟秀字迹，也教她按照实际工作需要写大字。\",\"turn\":\"雨晴开始从长辈照顾转向学习独立承担文书工作。\",\"time\":\"星期日；次日星期一休息\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"夏仕尼\",\"姚玲\"],\"objects\":[\"七度空间\",\"排班表\",\"退货清单\"],\"places\":[\"合租屋卫生间\",\"超市后仓\"]},{\"key\":\"c130\",\"id\":130,\"title\":\"工作的日常（中）\",\"kind\":\"main\",\"volume\":2,\"start\":518,\"end\":521,\"summary\":\"周一张思凡在实习公司被要求制作新产品方案PPT，先无意贬低经理旧稿，后凭设计能力交出精美成果。她与王经理因《传奇》游戏找到共同话题，并帮他把稀有游戏道具和装备带回安全区。工作才能与活泼交际令上下级关系迅速亲近，也展现她在职场隐藏身份的另一面。\",\"turn\":\"思思的办公能力与游戏合作同时赢得上司认可，隐秘身份仍藏在工作表象下。\",\"time\":\"星期一上午\",\"people\":[\"张思凡\",\"王经理\",\"邻座女职员\"],\"objects\":[\"PPT\",\"U盘\",\"传奇狗书\",\"迷你仙人掌\"],\"places\":[\"实习公司办公室\"]},{\"key\":\"c131\",\"id\":131,\"title\":\"工作的日常（下）\",\"kind\":\"main\",\"volume\":2,\"start\":522,\"end\":524,\"summary\":\"方莜莜对外使用本名方宇悠，在新公司任网络工程部主管，承担修电脑、建设网站和培训新人。朱志杰入职后认真学习；莜莜因眩晕险跌时被他扶住，他因察觉身体特征误猜主管是女扮男装。莜莜担心身份暴露却仍温和指导、请他吃午饭，显出独立逞强与平易近人的两面。\",\"turn\":\"新下属关系建立，身体虚弱和身份保密留下隐患。\",\"time\":\"星期一上午至午饭\",\"people\":[\"方莜莜\",\"朱志杰\",\"总经理\"],\"objects\":[\"公司网站资料\",\"重装光盘\",\"维修TXT文档\",\"进水键盘\"],\"places\":[\"网络工程部办公室\"]},{\"key\":\"c132\",\"id\":132,\"title\":\"荡秋千的猫\",\"kind\":\"main\",\"volume\":2,\"start\":525,\"end\":528,\"summary\":\"休息日雨晴在小区公园思考离家追求自我的代价，曲奇带咖啡自在荡秋千。幼童小天跌倒，奶奶以男子汉不能哭安慰，引起她对童年性别规训的回想；小天随后带竹篓清理石头防止旁人跌倒，又逐渐沉迷收集美石，直至竹篓装满，给她新的生活隐喻。\",\"turn\":\"童年规训与取舍问题从观察普通家庭中重新浮现。\",\"time\":\"星期一午后\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"小天\",\"小天奶奶\"],\"objects\":[\"秋千\",\"石头\",\"竹篓\",\"创口贴\"],\"places\":[\"小区公园\"]},{\"key\":\"c133\",\"id\":133,\"title\":\"生活中的哲学\",\"kind\":\"main\",\"volume\":2,\"start\":529,\"end\":531,\"summary\":\"小天为装新石头、提动竹篓不断舍弃旧石，雨晴由此联想自己为梦想失去亲情、朋友与尊严的代价，仍决定向前。秋千又唤起台湾外婆家花园和三位表哥的温暖记忆；他们包容她哭泣与想成为女孩的童言，尤其大表哥曾温柔答应儿时婚约，但多年未见后的态度仍未知。\",\"turn\":\"外婆家的自由回忆与石头取舍相互映照，雨晴开始衡量追梦所放下的亲情。\",\"time\":\"同一星期一午后；童年回忆\",\"people\":[\"苏雨晴\",\"小天\",\"小天奶奶\",\"大表哥\",\"二表哥\",\"三表哥\",\"外婆\",\"曲奇\",\"咖啡\"],\"objects\":[\"竹篓\",\"石头\",\"木板秋千\"],\"places\":[\"小区公园\",\"台湾外婆家\",\"山脚花园\"]},{\"key\":\"c134\",\"id\":134,\"title\":\"胡玉牛的烦恼\",\"kind\":\"main\",\"volume\":2,\"start\":532,\"end\":535,\"summary\":\"雨晴从公园回家，看到阿牛为体毛与强壮外形苦恼，有限的解决办法也因费用和身体反应受阻。叙述转入阿牛成长史：父亲自幼训练他、寄望其振兴武学家族，而他被重担压迫，渐渐把成为女性与摆脱责任联系起来。自责、逃避和已深植的身份愿望交织，并未得到化解。\",\"turn\":\"阿牛把曾被父亲赞赏的体魄视为身份阻碍，身体改变与家族期待发生冲突。\",\"time\":\"星期一午后；阿牛童年回忆\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"胡玉牛父亲\",\"曲奇\",\"咖啡\"],\"objects\":[\"镊子\",\"电视\",\"脱毛用品\"],\"places\":[\"合租屋\",\"胡家旧居\"]},{\"key\":\"c135\",\"id\":135,\"title\":\"莫空的日常（一）\",\"kind\":\"main\",\"volume\":2,\"start\":536,\"end\":539,\"summary\":\"时间来到2004年六月，莫空独居廉价天台阁楼，靠写网络故事挣少量稿费，搬城时会拆装台式电脑。他闭门通宵写作，思索李慕翔这一名字，收入将尽又需考虑打工；午后买炒面回家睡觉，却因停电、旧空调停转而热醒，散漫自由与现实贫困同时显现。\",\"turn\":\"六月莫空的清贫写作生活展开，停电即将把他带向新的出行与相遇。\",\"time\":\"2004年六月\",\"people\":[\"莫空\"],\"objects\":[\"台式电脑\",\"Word文档\",\"网络小说\",\"二手窗式空调\",\"炒面\"],\"places\":[\"莫空天台出租屋\",\"沙县小吃\"]},{\"key\":\"c136\",\"id\":136,\"title\":\"莫空的日常（二）\",\"kind\":\"main\",\"volume\":2,\"start\":540,\"end\":543,\"summary\":\"莫空向年轻房东王果确认片区停电，决定去郊外海边散心。他乘公交、穿树林抵达未经开发的海滩，游水后烤贝类饮酒，享受宁静，也注意到远处别墅亮灯。自由景色令他反思家族社会束缚，并想到屡次偶遇的忧郁女孩雨晴，对她的处境生出关切。\",\"turn\":\"莫空接近海边别墅，雨晴在他心中的分量浮现。\",\"time\":\"六月某日午后至夜\",\"people\":[\"莫空\",\"王果\"],\"objects\":[\"二锅头\",\"烤螃蟹与贝壳\",\"打火机\"],\"places\":[\"天台出租屋\",\"郊外公交终点\",\"海边\",\"海边别墅\"]},{\"key\":\"c137\",\"id\":137,\"title\":\"莫空的日常（三）\",\"kind\":\"main\",\"volume\":2,\"start\":544,\"end\":547,\"summary\":\"深夜莫空走近别墅，遭保镖礼貌驱离，并看到天台上美丽少女似乎对他出现感到意外；双方没有交谈。问得水泥路后，他出林才发现公交已停，只能步行回城。途中遇上夜游的黑猫曲奇与紫色鼠咖啡，原来他比雨晴更早认识曲奇；人和动物相伴走到岔路再告别。\",\"turn\":\"别墅少女身份未明；曲奇把独立人物线悄然相连。\",\"time\":\"同日深夜至后半夜\",\"people\":[\"莫空\",\"雯雯\",\"别墅保镖\",\"曲奇\",\"咖啡\"],\"objects\":[\"别墅玻璃\",\"篝火\"],\"places\":[\"海边别墅\",\"水泥路\",\"郊区车站\",\"回城岔路\"]},{\"key\":\"c138\",\"id\":138,\"title\":\"莫空的日常（四）\",\"kind\":\"main\",\"volume\":2,\"start\":548,\"end\":551,\"summary\":\"莫空步行至天亮，偶见与阿牛上班的雨晴，误把阿牛当作其男友而选择不打扰。回家昏睡后梦见昔日继任莫家家主：父亲因癌症去世，族人在就任仪式上各怀心思，以琐碎事务刁难。摸到祖传紫檀椅里的蛀洞，他决意放弃家主之位，梦境揭示其远行缘起。\",\"turn\":\"阿牛被误认男友；莫空主动辞去家主是自由生活根源。\",\"time\":\"六月次日清晨；往事梦境\",\"people\":[\"莫空\",\"苏雨晴\",\"胡玉牛\",\"王果\",\"莫家父亲\",\"莫家族人\"],\"objects\":[\"紫檀族长椅\",\"祖先牌位\"],\"places\":[\"回城街道\",\"莫空出租屋\",\"莫家祠堂\"]},{\"key\":\"c139\",\"id\":139,\"title\":\"莫空的日常（五）\",\"kind\":\"main\",\"volume\":2,\"start\":552,\"end\":555,\"summary\":\"梦中莫空放弃权位后游历各地，以写故事和打零工维生；醒来发现已睡过一天一夜。他前往旧面馆期待再见雨晴，却从老板夫妇处得知她离家、父母曾来寻人及其出生时被认定的性别。面对老板娘责怪，莫空坚持每个人都有苦衷，理解多于评判。\",\"turn\":\"莫空得知雨晴身份与家庭处境，并未因此否定她。\",\"time\":\"六月又次日早晨\",\"people\":[\"莫空\",\"李叔\",\"张阿姨\",\"苏雨晴父母\",\"苏雨晴\"],\"objects\":[\"猪肝面\",\"雨晴留条\",\"香烟\"],\"places\":[\"莫空出租屋\",\"无名面馆\"]},{\"key\":\"c140\",\"id\":140,\"title\":\"同性恋的传言\",\"kind\":\"main\",\"volume\":2,\"start\":556,\"end\":559,\"summary\":\"孙昊频繁打电话询问思思动态，既显亲密也暴露占有欲，并计划暑假探访。办公室听见男性声音后流传同性恋猜测，影响思思融入同事。她临时虚构来电者是哥哥、自己因算命而从小按女孩养大的说法，暂时化解排斥，却仍承受议论和被劝找女友的压力。\",\"turn\":\"职场暂时接纳以隐瞒真实关系为代价；恋人控制感初显。\",\"time\":\"六月工作日；临近暑假\",\"people\":[\"张思凡\",\"孙昊\",\"邻座女职员\",\"扫地大妈\",\"王经理\"],\"objects\":[\"手机\",\"复印文件\"],\"places\":[\"实习公司办公室\"]},{\"key\":\"c141\",\"id\":141,\"title\":\"哆啦 A 梦的百宝袋\",\"kind\":\"main\",\"volume\":2,\"start\":560,\"end\":562,\"summary\":\"室友晚间分享变身题材小说《夜明珠》，又看《哆啦A梦》讨论想要的道具。思思喜时光旅行、童话入口，雨晴向往任意门与成真能力，莜莜从缩小电筒想到生活与资源问题。阿牛看似熟睡，三人费力将他搬回床上后，他梦话仍请求让谎言成真的道具，显露深藏愿望。\",\"turn\":\"共同幻想将群像愿望并列，阿牛的沉默并非无欲。\",\"time\":\"六月某晚至22时\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"夜明珠小说\",\"电视遥控器\",\"哆啦A梦道具\"],\"places\":[\"合租屋客厅\",\"阿牛卧室\"]},{\"key\":\"c142\",\"id\":142,\"title\":\"收银员的学习\",\"kind\":\"main\",\"volume\":2,\"start\":563,\"end\":565,\"summary\":\"连续搬货让雨晴渐渐熟悉超市，能主动找事做。午餐时她鼓励阿牛以日常举止靠近理想形象，两人计划端午同游乐园，也被同事误看作情侣。张燕安排雨晴学习收银，夏老伯解释跨岗补位的需要；她随后向前台主管学习辨钞，工作技能由理货扩展到收银。\",\"turn\":\"雨晴工作自主性增强，节日集体出游有了计划。\",\"time\":\"六月端午节前\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张燕\",\"夏仕尼\",\"前台主管\"],\"objects\":[\"儿童小勺\",\"百元钞票\",\"收银机\"],\"places\":[\"超市员工餐厅\",\"后仓\",\"前台\"]},{\"key\":\"c143\",\"id\":143,\"title\":\"小城市的游乐园\",\"kind\":\"main\",\"volume\":2,\"start\":566,\"end\":568,\"summary\":\"端午四位室友都获连休，赶早乘车去邻镇游乐园。雨晴、思思、莜莜穿女装出行，阿牛因外形只穿休闲装，感到失落；莜莜制止思思越界玩笑，并给雨晴安全衣物。排队至十点后入园，雨晴想起童年被学习占满、只能在少年宫喂鸽子的生活，期待补回游玩的快乐。\",\"turn\":\"四人共同度假，衣着自由与外貌落差仍并存。\",\"time\":\"端午假期第一天7:30—10:00\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"苏雨晴的母亲\"],\"objects\":[\"水手服\",\"淑女裙\",\"安全裤\",\"门票\",\"遮阳伞\"],\"places\":[\"合租屋\",\"郊区公交\",\"邻镇游乐园\",\"少年宫\"]},{\"key\":\"c144\",\"id\":144,\"title\":\"真·旋转木马\",\"kind\":\"main\",\"volume\":2,\"start\":569,\"end\":572,\"summary\":\"四人体验旋转木马：雨晴选独角兽、思思抢白马、莜莜坐枣红马，阿牛因体型被安排水牛座位。思思未细看说明，恰好选中会高速自转的特殊白马，结束后眩晕呕吐，伙伴扶她休息、买水照顾。嬉闹与分享阿牛寿司等自带食物，使短暂惊险回到亲密轻松的节日氛围。\",\"turn\":\"思思莽撞造成不适，朋友互相照顾支撑欢乐。\",\"time\":\"端午游园上午\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"游乐园工作人员\"],\"objects\":[\"白马\",\"独角兽\",\"水牛座位\",\"矿泉水\",\"寿司\",\"三明治\"],\"places\":[\"游乐园旋转木马\",\"长椅\"]},{\"key\":\"c145\",\"id\":145,\"title\":\"萝莉体型\",\"kind\":\"main\",\"volume\":2,\"start\":573,\"end\":575,\"summary\":\"摩天轮令雨晴恐高，之后她因身高未达要求，无法参加雷神之锤及其他刺激项目，只能在外等待，既遗憾又盼长高。思思逞强追逐刺激，莜莜体力不支，练武的阿牛最镇定。过山车乘客呕吐令思思抱怨，雨晴以玩笑回应，身体差异在同一游园经历中形成各自限制。\",\"turn\":\"雨晴被身高排除于项目外，群体玩乐呈现不同能力。\",\"time\":\"端午游园当日\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"游乐园工作人员\"],\"objects\":[\"摩天轮\",\"雷神之锤\",\"风神之手\",\"跳楼机\",\"过山车\"],\"places\":[\"游乐园\"]},{\"key\":\"c146\",\"id\":146,\"title\":\"“萝莉”的优势（上）\",\"kind\":\"main\",\"volume\":2,\"start\":576,\"end\":579,\"summary\":\"午后四人在游乐园大厅避暑，雨晴被限量水冰月玩偶吸引，把门票外剩余的钱全换成游戏币，仍抓取失败。她由此想到人生努力与舍弃可能都无回报，情绪崩溃落泪。旁观的洛胖、雷哥与管鹏注意到她；娃娃由园主侄子洛胖放入机器，三人商量上前帮忙。\",\"turn\":\"抓娃娃失败触发更深无望感，三个少年主动接近。\",\"time\":\"端午游园13—14时\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"洛胖\",\"万剑雷\",\"管鹏\"],\"objects\":[\"水冰月玩偶\",\"娃娃机\",\"游戏币\"],\"places\":[\"游乐园中央大厅\"]},{\"key\":\"c147\",\"id\":147,\"title\":\"“萝莉”的优势（下）\",\"kind\":\"main\",\"volume\":2,\"start\":580,\"end\":583,\"summary\":\"三位少年提出帮雨晴抓到水冰月，再由她登台唱歌作为交换。洛胖连续抓错但取得多个玩偶，雷哥换手后终于一次抓出三只、包括目标水冰月。雨晴感激又担心真实身份被知晓，仍接受约定走上小舞台，决定不放伴奏；少年们欣赏她却尚未留下联系方式。\",\"turn\":\"陌生人的帮助取得目标，唱歌约定让雨晴面对公众。\",\"time\":\"同日午后\",\"people\":[\"苏雨晴\",\"洛胖\",\"万剑雷\",\"管鹏\",\"游乐园工作人员\"],\"objects\":[\"水冰月玩偶\",\"哆啦A梦玩偶\",\"话筒\"],\"places\":[\"游乐园娃娃机\",\"小舞台\"]},{\"key\":\"c148\",\"id\":148,\"title\":\"动人的歌声\",\"kind\":\"main\",\"volume\":2,\"start\":584,\"end\":587,\"summary\":\"雨晴克服紧张，把平时自创旋律即兴填词，清唱迷茫前行、守住梦想的心情，感动大厅听众。三个少年交付水冰月及所有抓出的玩偶后离开，没有索取号码。她自留水冰月，将起司猫送莜莜、其余送思思，重新露出笑容；休息过后四人又决定去人工湖划船。\",\"turn\":\"歌声把个人困境转成被听见的表达，玩偶成为珍贵纪念。\",\"time\":\"同日下午至傍晚\",\"people\":[\"苏雨晴\",\"洛胖\",\"万剑雷\",\"管鹏\",\"张思凡\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"原创无名歌曲\",\"水冰月玩偶\",\"起司猫玩偶\",\"其他玩偶\"],\"places\":[\"游乐园大厅\",\"小舞台\",\"人工湖\"]},{\"key\":\"c149\",\"id\":149,\"title\":\"打地铺\",\"kind\":\"main\",\"volume\":2,\"start\":588,\"end\":591,\"summary\":\"划船时雨晴想起西湖与父母出游，向莜莜谈起希望被家人接纳；莜莜也承认父母古板但更喜欢独立生活。回家雨晴洗净玩偶，阿牛做面点，众人为避暑在客厅打地铺，读书、聊天、催思思给孙昊回电。雨晴受小说理想身份刺激而自行改变用药，温暖日常里藏着急切与风险。\",\"turn\":\"共眠客厅延长亲密感，思亲和求变压力未消。\",\"time\":\"端午当天傍晚至夜\",\"people\":[\"苏雨晴\",\"方莜莜\",\"张思凡\",\"胡玉牛\",\"孙昊\",\"苏雨晴父母\"],\"objects\":[\"皮划艇\",\"脚踏船\",\"水冰月玩偶\",\"色谱龙\",\"凉席\",\"花露水\",\"夜明珠\",\"MP4\",\"银民公敌\"],\"places\":[\"游乐园人工湖\",\"合租屋客厅\",\"西湖\"]},{\"key\":\"c150\",\"id\":150,\"title\":\"夜话\",\"kind\":\"main\",\"volume\":2,\"start\":592,\"end\":595,\"summary\":\"客厅夜话从宿舍闲聊转向身份与未来。思思坦言吸引对象不限于男性，阿牛询问药物代价；众人被未经证实的短寿传言压低情绪，又讨论不可逆身体改变、家人态度和谋生压力。思思承认愿望与顾虑并存，阿牛沉默最久。话题转开后，四人仍未找到解决困境的答案。\",\"turn\":\"改变身体的愿望与风险、家庭及工作之间的冲突被明说。\",\"time\":\"端午游园之后深夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"MP4\",\"电视\",\"水冰月玩偶\",\"咖啡饮品\"],\"places\":[\"合租屋客厅\"]},{\"key\":\"c151\",\"id\":151,\"title\":\"相识\",\"kind\":\"main\",\"volume\":2,\"start\":596,\"end\":599,\"summary\":\"莜莜从噩梦惊醒，独自出门为四人买早餐，随后玩《传奇》。角色优子被怪群包围时，道士玩家有条色狼为她治疗解围，二人互加好友，相约挖矿练级，对方还送铁镐。原本习惯独自游戏的莜莜首次体会有伙伴一起走路、聊天的快乐，新关系在虚拟世界萌芽。\",\"turn\":\"安念在游戏里帮助新角色优子，使莜莜获得合租与公司之外的新朋友。\",\"time\":\"端午假期次日早晨\",\"people\":[\"方莜莜\",\"安念\",\"苏雨晴\",\"张思凡\",\"胡玉牛\"],\"objects\":[\"早餐\",\"笔记本电脑\",\"传奇\",\"铁镐\",\"蜡烛\",\"魔法戒指\"],\"places\":[\"合租屋阳台\",\"传奇矿洞与小村庄\"]},{\"key\":\"c152\",\"id\":152,\"title\":\"相知\",\"kind\":\"main\",\"volume\":2,\"start\":600,\"end\":603,\"summary\":\"莜莜与有条色狼从游戏聊到生活和观念，得知对方住杭州，但因羞怯拒绝语音。室友们午前陆续起床，新闻预报夜间流星雨，思思提议上山观赏。雨晴清点药物后短暂胸痛，又回忆梦中成为女性、结婚育儿的圆满生活；醒后现实落差仍令她沉郁。\",\"turn\":\"网游关系加深；观星计划提出但本章未执行。\",\"time\":\"端午假期白天；预告当晚22时流星雨\",\"people\":[\"方莜莜\",\"安念\",\"苏雨晴\",\"张思凡\",\"胡玉牛\"],\"objects\":[\"传奇\",\"YY\",\"药盒\",\"电视流星雨新闻\"],\"places\":[\"合租屋\",\"游戏矿洞\"]},{\"key\":\"c153\",\"id\":153,\"title\":\"前台收银\",\"kind\":\"main\",\"volume\":2,\"start\":604,\"end\":607,\"summary\":\"雨晴刚学收银便被抽调前台，未及时整理零钱又因紧张频频出错，遇到改价和权限问题只能求助主管。随着人流减少，她逐渐找到节奏，连报金额都不再结巴。过了下班时间仍无法离开，姚玲替她封住排队入口才结束加班；刚松口气，另一收银台传来顾客怒骂。\",\"turn\":\"首次实操形成能力与信心，却立即撞上服务冲突。\",\"time\":\"假期之后某日下午至16时许\",\"people\":[\"苏雨晴\",\"前台主管\",\"姚玲\",\"顾客\"],\"objects\":[\"收银机\",\"钱箱\",\"零钱\",\"拦队链条\"],\"places\":[\"大润发前台\"]},{\"key\":\"c154\",\"id\":154,\"title\":\"前台纠纷\",\"kind\":\"main\",\"volume\":2,\"start\":608,\"end\":611,\"summary\":\"收银员与顾客因找回的旧钞发生争执，顾客先持物伤人，年轻员工暴怒反击酿成严重伤害，被警方带走，顾客送医。雨晴首次目睹如此暴力，震惊呕吐，回家路上仍不断重现现场；阿牛陪她并谈及自己的练武经历。事件将日常服务中的羞辱与瞬间失控的后果推到眼前。\",\"turn\":\"暴力结果尚待救治确认；目击给雨晴留下强烈冲击。\",\"time\":\"c153同日下午\",\"people\":[\"苏雨晴\",\"年轻收银员\",\"中年顾客\",\"胡玉牛\",\"超市管理人员\",\"警方\"],\"objects\":[\"旧五十元钞票\",\"酱油瓶\",\"剪刀\"],\"places\":[\"大润发前台\",\"回家街道\"]},{\"key\":\"c155\",\"id\":155,\"title\":\"平静的日常\",\"kind\":\"main\",\"volume\":2,\"start\":612,\"end\":615,\"summary\":\"室友晚间照常谈外貌、逗猫、打恋爱电话；莜莜宣布插画师朋友次日将来合住。曲奇按遥控器切到新闻，报道确认超市顾客抢救无效死亡、员工已被控制，室友才知道雨晴目击了事件。超市通知停业整顿、复工待定，雨晴与阿牛因此有空接待新室友。\",\"turn\":\"顾客死亡获新闻确认；停工连起新室友到来。\",\"time\":\"前台冲突当天夜\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张思凡\",\"方莜莜\",\"孙昊\",\"曲奇\",\"咖啡\",\"年轻收银员\",\"中年顾客\"],\"objects\":[\"紫色指甲油\",\"剃须刀\",\"逗猫棒\",\"电视新闻\",\"停工短信\"],\"places\":[\"合租屋\",\"大润发\"]},{\"key\":\"c156\",\"id\":156,\"title\":\"林夕晨\",\"kind\":\"main\",\"volume\":2,\"start\":616,\"end\":619,\"summary\":\"林夕晨拖行李乘车至白兔街，在车上遭骚扰却没有外显回应。到合租屋后，雨晴与阿牛热情接待，她寡言而直接，自己挑空房入住，以药板表明与他们有相近经历。她自述一年前开始用药，父母尚不知情，容貌令两位室友羡慕；阿牛记下她喜欢鱼，准备晚餐。\",\"turn\":\"新室友入住，沉默性格与受骚扰时的反应尚待理解。\",\"time\":\"超市停业次日白天\",\"people\":[\"林夕晨\",\"苏雨晴\",\"胡玉牛\",\"公交骚扰者\"],\"objects\":[\"行李箱\",\"地址纸条\",\"拖鞋\",\"补佳乐\",\"可乐\"],\"places\":[\"公交车\",\"白兔街\",\"合租屋\"]},{\"key\":\"c157\",\"id\":157,\"title\":\"三无少女\",\"kind\":\"main\",\"volume\":2,\"start\":620,\"end\":623,\"summary\":\"思思归家得知林夕晨十八岁，越界触碰对方却没有得到预期反应，反而被递上一罐旺仔牛奶。莜莜解释她是论坛ID夕子的插画师朋友、高中毕业后独立生活。众人晚间逛夜市，雨晴关心阿牛低沉状态，措辞却触痛其自卑；阿牛坦言不相信还能变得好看，关系首次明显紧绷。\",\"turn\":\"夕晨融入日常，阿牛却因体貌比较和不够体贴的安慰产生更深失落。\",\"time\":\"林夕晨入住当日晚\",\"people\":[\"林夕晨\",\"张思凡\",\"方莜莜\",\"苏雨晴\",\"胡玉牛\"],\"objects\":[\"旺仔牛奶\",\"套圈香烟\",\"冰棍\"],\"places\":[\"合租屋\",\"夜市\"]},{\"key\":\"c158\",\"id\":158,\"title\":\"胸部按摩\",\"kind\":\"main\",\"volume\":2,\"start\":624,\"end\":627,\"summary\":\"夕晨注意到雨晴低落，主动递牛奶，显示沉默中的关心。回家后雨晴因外貌比较而焦虑，独处时被夕晨误入房间撞见私密活动，尴尬地躲回客厅。思思与莜莜照常打闹，阿牛却因无人主动理会自己而受伤，只有夕晨观察到。超市停业三天明确，收银员父母仍请律师争取辩护。\",\"turn\":\"夕晨开始以行动表达关怀，阿牛孤立感加深。\",\"time\":\"夕晨入住当晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"收银员父母\",\"辩护律师\"],\"objects\":[\"牛奶箱\",\"故事会\",\"棉被\",\"棒棒糖\"],\"places\":[\"夜市\",\"合租屋\"]},{\"key\":\"c159\",\"id\":159,\"title\":\"优雅的淑女\",\"kind\":\"main\",\"volume\":2,\"start\":628,\"end\":631,\"summary\":\"雨夜过后天气转凉，室友从客厅各回卧室；雨晴收拾曲奇偷开的猫粮，因超市尚停业而留家。思思和莜莜出门工作，雨晴为自己与夕晨准备粥、蛋和面包。夕晨极慢而优雅地用餐，主动分给她半杯牛奶，又因急着陪她喝完而显窘迫；阿牛反常地睡到很晚。\",\"turn\":\"雨晴渐懂夕晨的非言语亲近，阿牛作息异常继续。\",\"time\":\"停业最后一天早晨\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"曲奇\",\"咖啡\"],\"objects\":[\"猫粮罐\",\"白粥\",\"荷包蛋\",\"肉松面包\",\"牛奶\"],\"places\":[\"合租屋\"]},{\"key\":\"c160\",\"id\":160,\"title\":\"彩色铅笔画\",\"kind\":\"main\",\"volume\":2,\"start\":632,\"end\":635,\"summary\":\"夕晨在阴雨阳台以彩铅画出雨后夕阳、鸽群与浅虹，落款夕，再加雨晴二字郑重赠给她。雨晴感受被珍视，借夕晨工具回画许多带喜怒哀乐表情的Q版夕晨，祝她更自由表达心情。夕晨从身后握住雨晴执笔的手补画，亲密而温暖的接触使雨晴生出陌生悸动。\",\"turn\":\"夕晨用命名画作表达注视，雨晴第一次以回赠图画主动靠近她。\",\"time\":\"停业最后一天白天\",\"people\":[\"苏雨晴\",\"林夕晨\"],\"objects\":[\"彩色铅笔\",\"画板\",\"绘画工具箱\",\"雨晴画作\",\"简易画框\"],\"places\":[\"合租屋阳台\"]},{\"key\":\"c161\",\"id\":161,\"title\":\"温润的小手\",\"kind\":\"main\",\"volume\":2,\"start\":636,\"end\":639,\"summary\":\"夕晨补上一位张开双臂的大Q版人物，像拥抱其他小人；雨晴题名《心情》，夕晨珍藏。阿牛起床打断二人空间，雨晴独自反复回味牵手与香气，并读爱情文章对照心动。她由此困惑吸引与主动性是否影响自我认同，仍未得答案；窗外雨后晚霞竟与夕晨赠画相映。\",\"turn\":\"心动被雨晴辨认，但关系尚未表白；画中晴景在现实出现。\",\"time\":\"同日白天至雨后傍晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"胡玉牛\"],\"objects\":[\"心情画作\",\"雨晴画作\",\"故事会爱情文章\",\"画卷背包\"],\"places\":[\"合租屋阳台\",\"雨晴卧室\"]},{\"key\":\"c162\",\"id\":162,\"title\":\"新郎的梦\",\"kind\":\"main\",\"volume\":2,\"start\":640,\"end\":643,\"summary\":\"雨晴梦见自己作为成年新郎与林小姐结婚，梦境中的角色和身体却互相矛盾，使婚礼破碎。她又进入变得明亮热闹的梦中公园，见小男孩拥有妻子般的伴侣，被其安稳人生说法动摇，思考自己能否拥有婚姻与未来。小男孩送她香雪兰，梦末她认出书中赋予它的悲伤、痛苦与后悔寓意。\",\"turn\":\"梦境集中呈现身份与婚姻焦虑，不能视为真实婚礼。\",\"time\":\"雨后夜间梦境\",\"people\":[\"苏雨晴\",\"梦中林小姐\",\"梦中小男孩\",\"梦中小女孩\",\"梦中神父\"],\"objects\":[\"婚戒\",\"礼服\",\"香雪兰\",\"秋千\"],\"places\":[\"梦中教堂\",\"梦中公园\"]},{\"key\":\"c163\",\"id\":163,\"title\":\"目送离开\",\"kind\":\"main\",\"volume\":2,\"start\":644,\"end\":647,\"summary\":\"复工清晨雨晴醒在夕晨床上，想起昨晚被思思灌醉却记不起如何睡来。两人出现亲吻与亲近，夕晨醒后仍平静，雨晴又惊又喜；闹钟显示已迟到。匆忙出门时，夕晨替她抹匀面霜，并始终在门口和窗边目送，雨晴将其想象成妻子送丈夫上班的温柔画面。\",\"turn\":\"真实亲近加深，但昨晚细节不明，雨晴误工。\",\"time\":\"超市复工日7:30以后\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\"],\"objects\":[\"闹钟\",\"啤酒\",\"面霜\",\"工作服袋\",\"蛋糕\"],\"places\":[\"夕晨卧室\",\"合租屋走廊\"]},{\"key\":\"c164\",\"id\":164,\"title\":\"部门调动\",\"kind\":\"main\",\"volume\":2,\"start\":648,\"end\":651,\"summary\":\"迟到的雨晴被姚玲带往散称零食与酒柜部门，正式交给主管王海峰。她认出他曾失手让箱子砸到自己，而他与陈淑艳的拌嘴和搬货时的沉默形成反差。面对积压三天的大量货物，雨晴倍感吃力；王海峰随口说部门里女人也要当男人用，一度令她误以为身份暴露。\",\"turn\":\"岗位转入新部门，建立另一套同事关系与工作压力。\",\"time\":\"超市复工日上午\",\"people\":[\"苏雨晴\",\"姚玲\",\"王海峰\",\"陈淑艳\"],\"objects\":[\"积压货物\",\"六阶梯车\",\"安全帽\",\"果冻箱\"],\"places\":[\"超市散称零食区\",\"酒柜\"]},{\"key\":\"c165\",\"id\":165,\"title\":\"跳脱的部门主管\",\"kind\":\"main\",\"volume\":2,\"start\":652,\"end\":655,\"summary\":\"忙到午后，王海峰与雨晴吃饭却记不住她的名字，还用烧焦的肉捉弄她，陈淑艳在旁维护并继续与他斗嘴。雨晴发现这位口无遮拦的主管会亲自做重活、处理事务井井有条。陈淑艳透露他出身贫困，由超市资助读大学，毕业后任主管五年，仍未升迁，令雨晴改观。\",\"turn\":\"雨晴开始能对领导顶嘴，也看到王海峰的能力与困境。\",\"time\":\"复工日午饭\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\"],\"objects\":[\"烧焦五花肉\",\"退货单\",\"炒面\"],\"places\":[\"员工餐厅\",\"新部门\"]},{\"key\":\"c166\",\"id\":166,\"title\":\"抄写退货单\",\"kind\":\"main\",\"volume\":2,\"start\":656,\"end\":659,\"summary\":\"果冻公司业务员请求促销堆位，王海峰先以空间不足拒绝，私谈后答应下周安排，最终承认换取销售额分成。陈淑艳边调侃他边教雨晴抄退货单，雨晴观察便掌握流程，主动展示能力。主管去整理仓库、陈淑艳找货，她独自完成文书，新部门虽有灰色交易也有互相照顾的协作。\",\"turn\":\"雨晴融入新部门，看到主管权力与利益交换。\",\"time\":\"复工日下午\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"果冻业务员\"],\"objects\":[\"促销地堆\",\"彩页\",\"终端机\",\"退货表\",\"中华香烟\"],\"places\":[\"散称区\",\"部门办公室\",\"散称仓库\"]},{\"key\":\"c167\",\"id\":167,\"title\":\"苏雨晴的自制蛋糕\",\"kind\":\"main\",\"volume\":2,\"start\":660,\"end\":663,\"summary\":\"周五轮休日，夕晨完成插画订单，阿牛整上午把自己关在闷热房里。雨晴问午餐想吃什么，因夕晨答蛋糕便翻料理书尝试制作，辛苦搅拌仍想满足她。夕晨一直在旁安静陪看。直到等待出锅时，雨晴才发现冰箱本已有蛋糕，却仍珍惜亲手为她做食物的意义。\",\"turn\":\"雨晴以照顾表达好感，阿牛闭门准备另有缘由。\",\"time\":\"六月某星期五上午至中午\",\"people\":[\"苏雨晴\",\"林夕晨\",\"胡玉牛\"],\"objects\":[\"西式糕点书\",\"自制蛋糕\",\"电饭煲\",\"哲学书\",\"插画订单\"],\"places\":[\"合租屋阳台\",\"厨房\"]},{\"key\":\"c168\",\"id\":168,\"title\":\"胡玉牛的女装\",\"kind\":\"main\",\"volume\":2,\"start\":664,\"end\":667,\"summary\":\"阿牛鼓足勇气穿水手服、化妆走出房间，雨晴一时不知如何回应，夕晨却直接肯定并给他看身体转变的对照图片。得到鼓励后他感动落泪，雨晴也认真教日常穿裙礼仪。蛋糕因耽搁略焦但仍做成，夕晨点头认可，阿牛看出雨晴喜欢夕晨，问得她害羞辩解。\",\"turn\":\"阿牛获得珍贵肯定；雨晴情愫开始被同伴察觉。\",\"time\":\"同一星期五中午\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"林夕晨\"],\"objects\":[\"水手服\",\"化妆用品\",\"转变对照图片\",\"自制蛋糕\"],\"places\":[\"合租屋客厅\",\"厨房\"]},{\"key\":\"c169\",\"id\":169,\"title\":\"胡玉牛和莫空的邂逅\",\"kind\":\"main\",\"volume\":2,\"start\":668,\"end\":671,\"summary\":\"阿牛独逛夜市，海鲜香气唤起与父亲海边烧烤的童年，令他怀念过去又不愿退回原路。他买贝类和啤酒到公园竹林，遇到曾替雨晴挡混混的莫空。莫空说圆月残月各有观赏价值，接纳他的倾诉，却不逼问具体心事；阿牛仍盼自己能以理想形象获得保护。\",\"turn\":\"阿牛独自承受失落时遇莫空，残月与倾听为尚无答案的困境打开思考。\",\"time\":\"夏日某晚\",\"people\":[\"胡玉牛\",\"莫空\",\"胡玉牛父亲\",\"海鲜摊主\"],\"objects\":[\"烤蛤蜊\",\"啤酒\",\"香烟\"],\"places\":[\"夜市\",\"公园竹林石桌\"]},{\"key\":\"c170\",\"id\":170,\"title\":\"天神和女神的故事\",\"kind\":\"main\",\"volume\":2,\"start\":672,\"end\":675,\"summary\":\"莫空给阿牛讲一个独立神话故事：恶魔之主杀害自愿献身保护众生的女神，夺回神位后陷入悔恨；女神所救妖狐寿终留下羽毛，与他保存的另一片相遇，使他回到过去成为妖狐。有限陪伴因轮回成为永恒，是莫空对结局的解释。阿牛还想追问为何不阻止悲剧，抬头莫空已离开。\",\"turn\":\"轮回寓言未回答能否改变悲剧，不能当现实主线历史。\",\"time\":\"承接竹林夜谈；故事中漫长轮回\",\"people\":[\"莫空\",\"胡玉牛\",\"故事中的天神/恶魔之主\",\"故事中的生命女神\",\"故事中的九尾妖狐\"],\"objects\":[\"故事中的两片羽毛\"],\"places\":[\"公园竹林\",\"故事中的神界与人间\"]},{\"key\":\"c171\",\"id\":171,\"title\":\"去集装箱房度假（上）\",\"kind\":\"main\",\"volume\":2,\"start\":676,\"end\":679,\"summary\":\"五位室友趁连休回郊区集装箱房，发现雨晴种的花与爬山虎已蓬勃生长。大家一起清扫灰尘、赶开踩脏床单的曲奇，忙碌也变得有趣。河边只一支钓竿，夕晨接手后熟练上鱼，思思与莜莜拿蚯蚓和网兜打闹，雨晴吹箫；曲奇玩水却被小螃蟹夹住爪子。\",\"turn\":\"共同劳动和田园生活巩固合住家庭感，夕晨钓鱼特长显露。\",\"time\":\"初夏连休出游首日\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\",\"曲奇\",\"咖啡\"],\"objects\":[\"种植花草\",\"爬山虎\",\"钓竿\",\"蚯蚓\",\"网兜\",\"箫\"],\"places\":[\"郊区集装箱房\",\"屋前院落\",\"河边\"]},{\"key\":\"c172\",\"id\":172,\"title\":\"去集装箱房度假（下）\",\"kind\":\"main\",\"volume\":2,\"start\":680,\"end\":683,\"summary\":\"曲奇反击螃蟹，夕晨钓满鱼篓后留大放小，五人傍晚烤鱼。雨晴因见血反胃，众人却又谈起药效停滞与私人诊所身体手术的可能；高昂费用和不确定安全让人犹豫，阿牛重新立志赚钱。许愿时多数人盼父母接纳，阿牛盼漂亮，夕晨却希望胸小些，揭示外人羡慕未必等于本人舒适。\",\"turn\":\"阿牛获得新的身体改变目标；各人愿望显示不同困境。\",\"time\":\"出游首日傍晚至夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\",\"曲奇\"],\"objects\":[\"鱼篓\",\"烤鱼\",\"私人诊所信息\",\"药物\"],\"places\":[\"集装箱房旁河岸\"]},{\"key\":\"c173\",\"id\":173,\"title\":\"安念\",\"kind\":\"main\",\"volume\":2,\"start\":684,\"end\":687,\"summary\":\"郊居清晨众人多仍贪睡，莜莜与游戏好友继续组队。对方送战士装备，两人交换名字：她报女性名方莜莜并谎称父母所取，他自报名安念，两人又加QQ。谈到大公会霸占练级区，安念提议自己建公会，莜莜愿作首位成员，友情由日常聊天迈向共同组织。\",\"turn\":\"有条色狼明确实名安念，双方建立更私人联系。\",\"time\":\"出游翌日，正文称星期六\",\"people\":[\"方莜莜\",\"安念\",\"苏雨晴\",\"张思凡\",\"胡玉牛\",\"林夕晨\",\"曲奇\",\"咖啡\"],\"objects\":[\"战士装备\",\"QQ\",\"笔记本电脑\",\"集装箱地面小窗\"],\"places\":[\"集装箱房\",\"传奇练级区\"]},{\"key\":\"c174\",\"id\":174,\"title\":\"春宫阁\",\"kind\":\"main\",\"volume\":2,\"start\":688,\"end\":691,\"summary\":\"安念拉好友凑十人创建《传奇》行会春宫阁及同名QQ群，莜莜加入并调侃会长。现实中众人发现冰箱没菜，思思提议捉蝉作为野趣午餐；雨晴怕热不愿去，被玩闹劝出门。思思自己又被高温吓退，伙伴合力阻止她临阵逃跑，五人带着笑闹向屋后树林出发。\",\"turn\":\"线上公会成立；线下郊游进入采集食物阶段。\",\"time\":\"出游翌日中午\",\"people\":[\"方莜莜\",\"安念\",\"春宫阁成员\",\"苏雨晴\",\"张思凡\",\"胡玉牛\",\"林夕晨\",\"曲奇\"],\"objects\":[\"春宫阁行会\",\"QQ群\",\"号角\",\"捉蝉网兜\"],\"places\":[\"集装箱房\",\"屋后树林\",\"传奇世界\"]},{\"key\":\"c175\",\"id\":175,\"title\":\"捉知了\",\"kind\":\"main\",\"volume\":2,\"start\":692,\"end\":695,\"summary\":\"树林捉蝉时思思徒手示范失败，阿牛踢树震落蝉，却感到体力不如从前。思思逞强爬高成功收获，下来时踩空，被莜莜抢先垫护，二人避免重伤。莜莜夸大疼痛吓她、提醒不可鲁莽，雨晴在旁配合；随后阿牛踢树、思思爬树、莜莜收集，分工继续。\",\"turn\":\"莜莜救下失足思思，以假装较重伤势促她谨慎。\",\"time\":\"郊游第二日下午\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\"],\"objects\":[\"蝉\",\"树枝\",\"塑料袋\"],\"places\":[\"郊区树林\"]},{\"key\":\"c176\",\"id\":176,\"title\":\"油炸知了\",\"kind\":\"main\",\"volume\":2,\"start\":696,\"end\":699,\"summary\":\"众人带近百只蝉回集装箱房，思思发现油不足，骑电瓶车去村店补买调料；莜莜负责清洗，怕虫的雨晴与夕晨搬餐具和沉重煤气罐。煤气又不足，只得改在院中生火烹制。香味引得大家品尝，雨晴仍不敢入口，莜莜耐心递给她尝试，度假由游玩变成集体劳动。\",\"turn\":\"众人分工解决油料与燃料不足，简单晚餐展示能力互补和相处的耐心。\",\"time\":\"第二日黄昏至晚\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\"],\"objects\":[\"蝉\",\"电瓶车\",\"菜油\",\"调味料\",\"煤气罐\",\"铁锅\",\"餐具\"],\"places\":[\"集装箱房\",\"附近村杂货店\",\"前院\"]},{\"key\":\"c177\",\"id\":177,\"title\":\"意外的美味\",\"kind\":\"main\",\"volume\":2,\"start\":700,\"end\":703,\"summary\":\"雨晴第一次吃蝉强忍不适，又主动重试，终于觉得美味，曲奇和咖啡也来分食。星空下众人谈未来：思思想与爱人经营僻静杂货店，莜莜想有伴侣并保留在家工作、领养孩子的生活，雨晴想做幼师、获父母认可和爱人相伴。阿牛说自己没有未来，模特愿望也像随口应付，温馨晚餐转为沉重自责。\",\"turn\":\"普通生活愿望显得遥远；阿牛绝望被明确说出。\",\"time\":\"第二日晚餐\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\",\"曲奇\",\"咖啡\"],\"objects\":[\"油炸知了\",\"野黄瓜\",\"二锅头\"],\"places\":[\"集装箱房前院\"]},{\"key\":\"c178\",\"id\":178,\"title\":\"一个无法入眠的夜\",\"kind\":\"main\",\"volume\":2,\"start\":704,\"end\":707,\"summary\":\"同夜五人都无法入眠，雨晴以佛教观念作精神依靠，阿牛则坚持索取药贩联系方式、急于身体改变，思思暂缓回应。谈未来时夕晨沉默，叙述揭示她有三个姐姐、曾被重男轻女的父亲因成绩反复公开殴打羞辱，随后逃家。她其实渴望交流，却难以表达，暗中说出杀父的愿望，旁人没有听见。\",\"turn\":\"夕晨的沉默获得创伤背景，杀父念头尚未行动。\",\"time\":\"第二日深夜；夕晨童年初中回忆\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\",\"林夕晨父亲\",\"林夕晨母亲\",\"林夕晨三位姐姐\",\"算命道士\"],\"objects\":[\"佛教典籍\",\"药贩联系方式\"],\"places\":[\"集装箱房\",\"夕晨老家与学校\"]},{\"key\":\"c179\",\"id\":179,\"title\":\"酒柜\",\"kind\":\"main\",\"volume\":2,\"start\":708,\"end\":711,\"summary\":\"雨晴被安排在酒柜收银，虽比前台清闲却要久站，身体不适。王海峰先拿小梯子自坐、与她斗嘴，又以算术题捉弄她，最终把座位让出并宣布中午请部门同事吃饭。两人围绕长期卖不出的名贵茅台和没墨水的笔互损，雨晴在他面前展现不同于平日的活泼与不服气。\",\"turn\":\"王海峰嘴上戏弄而行动关照，雨晴敢平等顶嘴。\",\"time\":\"郊游之后某工作日上午\",\"people\":[\"苏雨晴\",\"王海峰\"],\"objects\":[\"酒柜\",\"二阶梯\",\"1988年茅台\",\"圆珠笔\",\"排班表\",\"工作手套\"],\"places\":[\"超市酒柜\"]},{\"key\":\"c180\",\"id\":180,\"title\":\"排班表\",\"kind\":\"main\",\"volume\":2,\"start\":712,\"end\":716,\"summary\":\"王海峰告知每周可休两日，雨晴要求周末连休，却不愿独上晚班，缠得他与陈淑艳一同排晚班。主管因打麻将赢了钱，请早班五人去小餐馆；同事们在打卡、点菜和木瓜玩笑里互相调侃，陈淑艳甚至真咬他的手。雨晴感到轻松，也隐约看到工作规则中的变通。\",\"turn\":\"新的双休日与晚班确定，部门饭局拉近关系。\",\"time\":\"同日中午\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"翁锡芽\",\"徐嫂\"],\"objects\":[\"排班表\",\"麻将赢钱\",\"吃饭卡\",\"拔丝木瓜\"],\"places\":[\"超市酒柜\",\"员工通道\",\"小餐馆\"]},{\"key\":\"c181\",\"id\":181,\"title\":\"明争暗斗\",\"kind\":\"main\",\"volume\":2,\"start\":717,\"end\":720,\"summary\":\"饭局上雨晴发现笑闹背后陈淑艳被翁锡芽和徐嫂疏远。徐嫂谈即将高三的儿子，王海峰透露自己读浙江大学农科，本想回乡种田，后因家乡偏远留在城市，并建议徐嫂考虑儿子喜欢动物的兽医方向。他自然替夹不起豆腐的雨晴夹菜，却引来成人暧昧玩笑，使她拘谨害羞。\",\"turn\":\"王海峰教育背景明确；雨晴察觉同事之间排斥与拉拢。\",\"time\":\"同日午餐\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"翁锡芽\",\"徐嫂\",\"徐嫂儿子\"],\"objects\":[\"麻婆豆腐\",\"白酒\",\"木瓜\"],\"places\":[\"小餐馆\",\"王海峰老家\"]},{\"key\":\"c182\",\"id\":182,\"title\":\"勾心斗角\",\"kind\":\"main\",\"volume\":2,\"start\":721,\"end\":724,\"summary\":\"饭后打包剩菜又激起陈淑艳与两名女同事暗斗。回超市路上，徐嫂和翁锡芽逼雨晴表态认同对陈的贬低，并安排她与自己一起工作；她为免得罪只能含糊回应。回到王海峰面前，两人又笑脸融入聊天。麻将电话拆穿主管次日排晚班的理由，雨晴见识熟人嬉闹与职场站队并存。\",\"turn\":\"雨晴被动卷入同事阵营，日常交往不再全然轻松。\",\"time\":\"同日午后\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"翁锡芽\",\"徐嫂\",\"王海峰牌友\"],\"objects\":[\"打包木瓜\",\"糖醋里脊\",\"手机\",\"退货单\"],\"places\":[\"餐馆至超市路上\",\"超市酒柜\"]},{\"key\":\"c183\",\"id\":183,\"title\":\"胡玉牛的一天（上）\",\"kind\":\"main\",\"volume\":2,\"start\":725,\"end\":728,\"summary\":\"阿牛在后仓连续搬运重货，体力恢复变慢却仍超过同事。他主动替促销员取高处米箱，因任劳任怨被接纳；后仓主管察觉疲惫，暂给他分配较轻的传递工作。经理以请快餐鼓励继续，阿牛稍恢复又扛下收尾重活。群体认可主要建立在他的力量和勤劳上，与其内心愿望形成反差。\",\"turn\":\"阿牛获得劳动群体关心，也感到身体能力正衰减。\",\"time\":\"某个繁忙早班上午\",\"people\":[\"胡玉牛\",\"阿春\",\"后仓主管\",\"后仓经理\",\"大米促销员\",\"后仓同事\"],\"objects\":[\"大米箱\",\"食用油箱\",\"叉车\",\"水瓶\"],\"places\":[\"超市后仓\"]},{\"key\":\"c184\",\"id\":184,\"title\":\"胡玉牛的一天（下）\",\"kind\":\"main\",\"volume\":2,\"start\":729,\"end\":732,\"summary\":\"午后休息时阿牛抵挡不住同事递烟，又去买双喜，戒烟宣告中断。烟味让他回忆曾以父亲为榜样，后来怀疑所谓武学家族不过没落卖艺班，祖传伤药或比武术更有生计前景，却不被父亲接受。他由拒绝继承走向女性身份探索，如今仍无法辨清哪个自己才真实，急切想借药物改变身体。\",\"turn\":\"阿牛的家族神话被其自身质疑，情绪依靠转向吸烟。\",\"time\":\"c183同日下午；成长回忆\",\"people\":[\"胡玉牛\",\"胡玉牛父亲\",\"后仓同事\"],\"objects\":[\"雄师烟\",\"双喜烟\",\"棒棒糖\",\"祖传伤药配方\"],\"places\":[\"超市卸货码头\",\"对面烟店\",\"胡家旧居\"]},{\"key\":\"c185\",\"id\":185,\"title\":\"晚班\",\"kind\":\"main\",\"volume\":2,\"start\":733,\"end\":735,\"summary\":\"连上数日晚班后雨晴熟悉酒柜工作，偶尔替陈淑艳做文书与换标签。陈承担轻活招致同事嫉妒，雨晴选择不站队。一位和善的中年顾客突然要求最贵的酒，拒绝便宜替代品；王海峰开柜取出久未售出的龙年茅台，顾客仔细查看后决定买下，称临时有事未及准备礼物。\",\"turn\":\"长期陈列的茅台终遇买家，顾客身份引出疑问。\",\"time\":\"连续晚班某日20时许\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"中年购酒客\",\"酒柜促销员\"],\"objects\":[\"龙年限量茅台\",\"天之蓝\",\"放大镜\",\"价格标签\"],\"places\":[\"超市酒柜\"]},{\"key\":\"c186\",\"id\":186,\"title\":\"陈淑艳的总结报告\",\"kind\":\"main\",\"volume\":2,\"start\":736,\"end\":739,\"summary\":\"购酒客付款离开，雨晴觉得他似台湾大表哥却不敢确定；同事争论他是官员还是商人，均无证据。王海峰因售出贵重酒获奖金，又催陈淑艳写半年总结；她胡乱夸大功劳后改抄他的范文，并拉雨晴帮抄。主管以排班迁就她，使部门的偏爱、互损和现实形式主义并行。\",\"turn\":\"茅台售出完成；购酒客与亲属是否相关仍未证实。\",\"time\":\"同日晚班\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"翁锡芽\",\"徐嫂\",\"中年购酒客\",\"大表哥\",\"大表哥父亲\"],\"objects\":[\"龙年茅台\",\"半年总结报告\",\"奖金\"],\"places\":[\"超市酒柜\"]},{\"key\":\"c187\",\"id\":187,\"title\":\"深夜的街道\",\"kind\":\"main\",\"volume\":2,\"start\":740,\"end\":742,\"summary\":\"晚班十点后突降雨，雨晴独自步行回家，因不愿劳累早班的阿牛而拒绝接送。她在西瓜摊被当成晚归学生，顺着话题听摊主谈孩子作业，想起母亲逼自己套用作文范本的往事；虽原只想看看，仍因不好意思拒绝而买下大西瓜，继续在暗雨中艰难前行。\",\"turn\":\"怕麻烦别人和难以拒绝陌生人的性格，再次让她独自承受负担。\",\"time\":\"晚班十点后\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"西瓜摊主\",\"苏雨晴的母亲\"],\"objects\":[\"雨伞\",\"西瓜\",\"诺基亚手机\"],\"places\":[\"超市外街道\",\"西瓜摊\"]},{\"key\":\"c188\",\"id\":188,\"title\":\"雨中的街道\",\"kind\":\"main\",\"volume\":2,\"start\":743,\"end\":746,\"summary\":\"雨晴又在小摊挑选五个绳编小挂件，按朋友特点分配气球、梳子、兔子、红酒和猫脸，摊主另赠蝴蝶。黑暗路段的动静使她惊惧，靠近才知是曲奇出来迎接；猫陪她穿过小区回家。屋里只有思思仍撑着困意看电视，她把礼物放好，先替淋湿的猫洗澡，再去洗漱。\",\"turn\":\"曲奇的迎接和按人选礼物的细节，把独行的恐惧接回家庭般的日常。\",\"time\":\"同一雨夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"胡玉牛\",\"曲奇\",\"手工摊主\"],\"objects\":[\"编绳挂件\",\"蝴蝶挂件\",\"雨伞\",\"西瓜\"],\"places\":[\"夜街\",\"住处客厅\",\"浴室\"]},{\"key\":\"c189\",\"id\":189,\"title\":\"张思凡的心事（上）\",\"kind\":\"main\",\"volume\":2,\"start\":747,\"end\":750,\"summary\":\"雨晴带曲奇回房安睡，思思却为白天父母催找女友、安排相亲而失眠；她争辩时漏出对女孩无兴趣，担忧身份、家人和恋人无法兼容。她致电孙昊哭诉，对方在听到她本来的声音时烦躁喝止，待她恢复伪女声又温柔安慰，许诺永不抛弃；她未察觉这种态度变化。\",\"turn\":\"思思把父母的压力交给恋人安抚，而恋人的温柔已显出对声音与女性外表的条件。\",\"time\":\"同一雨夜至深夜\",\"people\":[\"苏雨晴\",\"曲奇\",\"张思凡\",\"孙昊\",\"思思父母\"],\"objects\":[\"电话\",\"电视\",\"女性衣物\"],\"places\":[\"住处客厅\",\"雨晴卧室\"]},{\"key\":\"c190\",\"id\":190,\"title\":\"张思凡的心事（下）\",\"kind\":\"main\",\"volume\":2,\"start\":751,\"end\":755,\"summary\":\"孙昊答应下周一来陪伴，思思依恋通话直到手机断电，穿着让自己安心的女性衣物入睡。梦中却浮出被富客囚禁和性侵虐待的记忆：她因急需大笔钱接受中间人安排，到了别墅后失去反抗能力，对方用高额包养承诺和控制阻止离开。她不断求救，安全感被旧创伤彻底冲破。\",\"turn\":\"恋人的承诺暂时安抚现实焦虑，却未能阻止被控制和受辱的创伤重现。\",\"time\":\"凌晨一时后；梦中往事\",\"people\":[\"张思凡\",\"孙昊\",\"中间人\",\"富客\"],\"objects\":[\"手机\",\"女性衣物\",\"约见信与定金\"],\"places\":[\"思思卧室\",\"梦中别墅\"]},{\"key\":\"c191\",\"id\":191,\"title\":\"森林冒险（一）\",\"kind\":\"main\",\"volume\":2,\"start\":756,\"end\":759,\"summary\":\"周末雨停放晴，思思反常地早起招呼大家去海边散心，并用玩笑掩饰噩梦留下的恐惧；莜莜察觉后没有追问。阿牛以有事和晚间大夜班为由留下，他同样做了噩梦，梦见父亲因其女性身份而杀害自己并自尽。这只是他对父亲偏执的恐惧，并未在现实发生。\",\"turn\":\"四人外出与阿牛独留分成两条线；两人的噩梦揭出玩笑和沉默背后的恐惧。\",\"time\":\"周末早晨\",\"people\":[\"张思凡\",\"苏雨晴\",\"方莜莜\",\"林夕晨\",\"胡玉牛\",\"胡玉牛父亲\",\"曲奇\",\"咖啡\"],\"objects\":[\"早餐\",\"电视\"],\"places\":[\"合租住处\"]},{\"key\":\"c192\",\"id\":192,\"title\":\"森林冒险（二）\",\"kind\":\"main\",\"volume\":2,\"start\":760,\"end\":763,\"summary\":\"四位室友换好女装结伴出发，阿牛在门关上后感到被美丽、女性身份和陪伴共同排除。公交车驶向郊外，雨晴有意同夕晨搭话，夕晨带了画具并因晕车靠在她肩头睡着；雨晴既满足于这种亲近，又误把照顾和心动看作男性角色的证明，对身份和爱情更加迷惑。\",\"turn\":\"阿牛的孤独与雨晴夕晨的亲密并置，关系内部的温差进一步扩大。\",\"time\":\"同一周末上午\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"画板与颜料\",\"公交车\",\"女装\"],\"places\":[\"合租住处\",\"郊区公交车\"]},{\"key\":\"c193\",\"id\":193,\"title\":\"森林冒险（三）\",\"kind\":\"main\",\"volume\":2,\"start\":764,\"end\":767,\"summary\":\"四人坐近两小时公交后仍须穿过农田走向森林。思思和莜莜兴奋地摘取他人田里的南瓜藤、黄瓜与丝瓜，再拉着同伴逃跑，雨晴体力最弱而腹痛疲惫。到林缘后众人休息，思思用过去来过的经验淡化野兽风险；夕晨把华夫饼分给雨晴，使她把普通照料感受为恋人的分享。\",\"turn\":\"轻率的野外准备和雨晴的虚弱为危险埋伏笔，夕晨的分享继续推动感情。\",\"time\":\"同日上午\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\"],\"objects\":[\"南瓜藤\",\"黄瓜\",\"丝瓜\",\"华夫饼\",\"矿泉水\"],\"places\":[\"郊区公交总站\",\"农田\",\"森林边缘\"]},{\"key\":\"c194\",\"id\":194,\"title\":\"森林冒险（四）\",\"kind\":\"main\",\"volume\":2,\"start\":768,\"end\":770,\"summary\":\"思思选择一条通往海边的林间小路，折树枝领队并不断安慰惧蛇的雨晴，享受保护妹妹般的成就感。越往深处杂草越密，莜莜被荆棘划伤，众人又闻到强烈腥臭，却未及时退出；树后突然出现棕熊逼近，思思率先拉起雨晴逃跑，原本轻松的郊游骤然变成险境。\",\"turn\":\"对安全的乐观判断被突发熊袭打破，四人的行动进入危机。\",\"time\":\"同日接近中午\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"棕熊\"],\"objects\":[\"树枝\",\"可乐味棒棒糖\",\"湿巾\"],\"places\":[\"海边森林小路\"]},{\"key\":\"c195\",\"id\":195,\"title\":\"森林冒险（五）\",\"kind\":\"main\",\"volume\":2,\"start\":771,\"end\":774,\"summary\":\"熊的追赶让四人慌乱跑散，思思先到海滩等候，莜莜与夕晨一起找到另一条小路。雨晴却奔跑过度昏倒，醒来已是夜晚，独自在陌生森林里无助地呼唤同伴；背包异响又使她惊惧，幸而钻出的是随行的曲奇，猫的出现让她从彻底孤立中获得一点安慰。\",\"turn\":\"同行者分成三组；雨晴在身体极限与失联中必须依靠曲奇。\",\"time\":\"同日中午至入夜\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"曲奇\",\"棕熊\"],\"objects\":[\"背包\",\"矿泉水瓶\",\"贝壳\"],\"places\":[\"森林\",\"海滩\"]},{\"key\":\"c196\",\"id\":196,\"title\":\"森林冒险（六）\",\"kind\":\"main\",\"volume\":2,\"start\":775,\"end\":778,\"summary\":\"雨晴发现已是晚七点半，手机没有信号，也辨不清方向。曲奇带她寻找树木栖身过夜，她勉强爬上树，仍被黑暗、冷意与声响折磨。莫空恰好路过，想吓一下树上迷路的孩子；雨晴误认树下黑影为熊，慌乱坠落昏厥，被他及时接住，这才认出是曾相识的少女。\",\"turn\":\"曲奇保全陪伴，莫空接住坠树的雨晴；救援前的惊吓也出自他的玩笑。\",\"time\":\"同日晚七点半以后\",\"people\":[\"苏雨晴\",\"曲奇\",\"莫空\"],\"objects\":[\"手机\",\"背包\",\"栖身树木\"],\"places\":[\"夜间森林\"]},{\"key\":\"c197\",\"id\":197,\"title\":\"森林冒险（七）\",\"kind\":\"main\",\"volume\":2,\"start\":779,\"end\":782,\"summary\":\"昏迷中的雨晴梦见祭坛和九尾狐耳少女，以为自己将转生而期盼成为天生女孩；醒来却在同伴身边，已到次日中午，得知莫空将她救出。大家在海边重聚，莜莜和思思仍以为莫空不知她们的出生性别，打趣他适合照顾雨晴；夕晨则以轻摸脑袋安慰她。\",\"turn\":\"雨晴脱险重聚；旁人未知莫空已在面馆得知她的身份，形成信息差。\",\"time\":\"次日中午；昏迷梦境\",\"people\":[\"苏雨晴\",\"九尾狐耳少女\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"莫空\",\"曲奇\"],\"objects\":[\"梦中祭坛与宝石\",\"雨伞\",\"鱼竿\"],\"places\":[\"梦中空间\",\"海滩\"]},{\"key\":\"c198\",\"id\":198,\"title\":\"森林冒险（八）\",\"kind\":\"main\",\"volume\":2,\"start\":783,\"end\":786,\"summary\":\"莫空钓鱼、思思烧烤，众人在海边补吃迟来的午餐。他说明那只熊是附近猎人朋友饲养，主人尚未来得及喊住她们便跑散，并指出别墅旁有安全大路。莫空离开时，雨晴被他的沉稳吸引，却怕自己不被接受；对夕晨的心动又让她无法确定爱情与人生选择，莜莜劝她留给时间。\",\"turn\":\"熊袭性质被重新解释；雨晴对莫空和夕晨的两种吸引开始正面冲突。\",\"time\":\"次日中午\",\"people\":[\"莫空\",\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"养熊猎人\",\"曲奇\"],\"objects\":[\"酒精灶\",\"迷你烧烤架\",\"烤鱼\",\"鱼竿\"],\"places\":[\"海滩\",\"海边别墅旁大路\"]},{\"key\":\"c199\",\"id\":199,\"title\":\"阳光、大海和沙滩（上）\",\"kind\":\"main\",\"volume\":2,\"start\":787,\"end\":790,\"summary\":\"夕晨把现实中明朗平静的海画成乌云怒浪，显出外表沉静之下的另一种情绪。等莫空离开，四人换泳装下海，难得享受不受旁人审视的身体自由。雨晴发现农村长大的夕晨竟完全不会游泳，便主动邀她入水、提出教学；追问往事触及她的忧伤后，又体贴地转开话题。\",\"turn\":\"雨晴从被照顾者转为照顾夕晨的人，海的自由与画中风暴形成反差。\",\"time\":\"周末第二日下午\",\"people\":[\"林夕晨\",\"苏雨晴\",\"张思凡\",\"方莜莜\"],\"objects\":[\"海景画\",\"画板\",\"白色学生泳装\",\"黑色学生泳装\",\"比基尼泳装\"],\"places\":[\"海滩\",\"浅海\"]},{\"key\":\"c200\",\"id\":200,\"title\":\"阳光、大海和沙滩（下）\",\"kind\":\"main\",\"volume\":2,\"start\":791,\"end\":794,\"summary\":\"夕晨初学游泳时失去平衡，惊慌抓住雨晴，把两人一起拖入水中，思思及时游来扶起。雨晴看见夕晨少见的脆弱反而感到特别的亲近，之后耐心示范，陪她逐渐克服恐惧、练习漂浮和换气。教学让两人长时间相伴，也使雨晴更加困惑于自己的爱意与性别角色想象。\",\"turn\":\"短暂险情被同伴化解，夕晨愿意继续尝试，雨晴通过照料体验更明确的心动。\",\"time\":\"同日下午\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\"],\"objects\":[\"泳装\"],\"places\":[\"浅海\"]},{\"key\":\"c201\",\"id\":201,\"title\":\"海边别墅（上）\",\"kind\":\"main\",\"volume\":3,\"start\":796,\"end\":798,\"summary\":\"游泳练习不觉持续到傍晚，雨晴舍不得结束这次与夕晨密切相处的下午，却仍未确定如何表达爱情。众人收拾泳具和零食，循莫空指示前往海边别墅旁的大路以赶末班车。思思与莜莜猜测别墅主人身份，提及整片海滩被长期承租；夕晨方向感好、曾带莜莜出林也在此说明。\",\"turn\":\"郊游将结束，四人沿大路返程前意外接近另一条人物线。\",\"time\":\"同日傍晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\"],\"objects\":[\"毛巾\",\"青豆\",\"果冻\",\"豆腐干\",\"背包\"],\"places\":[\"海滩\",\"通往别墅的路\"]},{\"key\":\"c202\",\"id\":202,\"title\":\"海边别墅（下）\",\"kind\":\"main\",\"volume\":3,\"start\":799,\"end\":802,\"summary\":\"四人在别墅门外再次见到步行街与超市的美丽少女，原被保镖催离，却被她邀请入内；她让女仆水水同坐，拒绝交换姓名，只问该不该追回同时爱上两人后放弃选择的男孩。思思和莜莜反对，雨晴认为应见面确认是否仍爱，少女受到触动。客人离开后，她独叹那人已失去过去记忆。\",\"turn\":\"无名少女提出两难爱情，雨晴的理解给她希望；失忆与未揭姓名保留后续悬念。\",\"time\":\"同日傍晚\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"雯雯\",\"水水\",\"别墅保镖\",\"失忆男孩\"],\"objects\":[\"秋千\",\"喷泉\",\"茶水\"],\"places\":[\"海边别墅庭院\"]},{\"key\":\"c203\",\"id\":203,\"title\":\"夜间飙车（上）\",\"kind\":\"main\",\"volume\":3,\"start\":803,\"end\":805,\"summary\":\"离开别墅后思思轻率地评说少女的恋爱烦恼，又泛谈初中生幼稚，雨晴反驳并不慎提到总帮自己的同桌，引来朋友追问。四人搭上返城公交，司机闲聊别墅财富，雨晴独坐后排想起冉空城，既盼对方来电又怕被记挂，离家小半年的矛盾思念仍未得到回应。\",\"turn\":\"外部的爱情问题牵出雨晴自己的旧同桌，她对过去的依恋仍与新关系并存。\",\"time\":\"周日傍晚至夜间\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"冉空城\",\"公交司机\",\"雯雯\"],\"objects\":[\"公交车\",\"手机\"],\"places\":[\"别墅返程路\",\"郊区公交总站\",\"返城公交\"]},{\"key\":\"c204\",\"id\":204,\"title\":\"夜间飙车（下）\",\"kind\":\"main\",\"volume\":3,\"start\":806,\"end\":808,\"summary\":\"陌生来电让雨晴期待是冉空城，接通却只是保险推销，她失落挂断。返城路上飙车者两度逼停公交，司机称领头人是市长之子，敢凭家世压下事故，众人愤怒却只能避让。镜头转向领先轿车，男司机乱扔的烟被一名胡子拉碴的路人踢回烫伤，找不到人便把怒气转向女伴。\",\"turn\":\"雨晴的来电希望落空；街头权势与对弱者泄愤延伸小说的压迫主题。\",\"time\":\"周日晚上约九时\",\"people\":[\"苏雨晴\",\"冉空城\",\"公交司机\",\"张思凡\",\"方莜莜\",\"飙车男子\",\"飙车女伴\",\"胡子路人\"],\"objects\":[\"推销电话\",\"公交车\",\"改装奔驰\",\"中华香烟\",\"对讲机\"],\"places\":[\"小城市夜间公路\"]},{\"key\":\"c205\",\"id\":205,\"title\":\"雌性激素注射针（上）\",\"kind\":\"main\",\"volume\":3,\"start\":809,\"end\":812,\"summary\":\"叙事回到周六中午：阿牛留城的真正要事是去星辰诊所寻求激素注射。外表改变缓慢使他愿意忽略代价，医生孔雀虽宿醉困倦、令他不安，却看透他的拘谨并表示不嘲笑。阿牛坚定接受注射并付费，把这次治疗当成尽快接近女性身体的希望，也开始考虑如何负担长期费用。\",\"turn\":\"阿牛从口服用药推进到私诊注射，追求变化的紧迫感压过风险顾虑。\",\"time\":\"倒叙周六中午，与森林走散同时\",\"people\":[\"胡玉牛\",\"孔雀\"],\"objects\":[\"手机备忘录\",\"钱包\",\"雌性激素注射剂\",\"白大褂\"],\"places\":[\"星辰路\",\"星辰诊所\"]},{\"key\":\"c206\",\"id\":206,\"title\":\"雌性激素注射针（下）\",\"kind\":\"main\",\"volume\":3,\"start\":813,\"end\":816,\"summary\":\"周日下午阿牛再次来到诊所，询问更强的抗雄药；孔雀推介昂贵注射和手术，他因费用与不可逆的恐惧暂时拒绝。回家联系不上尚在海边的同伴，他虽知道是自己选择留下，仍感到被抛弃，便独自去看青春爱情电影。银幕让他触动，身后情侣的不当亲热却破坏美感，引得他出声斥责。\",\"turn\":\"医学和经济限制未解，阿牛以独自观影填补空落，却又将受挫情绪带入陌生关系。\",\"time\":\"周日下午至傍晚，与海边游泳并行\",\"people\":[\"胡玉牛\",\"孔雀\",\"电影院情侣\"],\"objects\":[\"抗雄药\",\"手术报价\",\"电影票\",\"爆米花\",\"啤酒瓶\"],\"places\":[\"星辰诊所\",\"合租住处\",\"电影院\"]},{\"key\":\"c207\",\"id\":207,\"title\":\"一个人上班\",\"kind\":\"main\",\"volume\":3,\"start\":817,\"end\":820,\"summary\":\"暴雨工作日，前夜大夜班已做完多数工作，雨晴被安排独守酒柜早班。她费力逐瓶搬下高处的一箱酒，却仍受顾客责骂；午饭时又见夏伯伯惯被分派污脏破损品处理，替他不平，老人却认为总得有人做。她也注意到阿牛日益寡言敏感，会对绊脚板凳发怒，担心他的精神状态。\",\"turn\":\"雨晴独立处理工作困难；夏伯伯的全名揭为夏仕尼，阿牛的异常已被室友看见。\",\"time\":\"海边归来后的雨天工作日\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"夏仕尼\",\"酒柜促销员\",\"秃头顾客\",\"王海峰\"],\"objects\":[\"纸折玩具\",\"泸州老窖\",\"不稳梯子\",\"破损商品单\"],\"places\":[\"超市酒柜\",\"后仓\",\"员工餐厅\"]},{\"key\":\"c208\",\"id\":208,\"title\":\"孙昊又来了\",\"kind\":\"main\",\"volume\":3,\"start\":821,\"end\":824,\"summary\":\"孙昊突然告知火车将到，思思兴奋请假接站，却因来不及换女装而看到他明显失望，也不适应公共场合的亲昵。回家碰到女装化妆的阿牛，对方受惊后冷淡锁门；孙昊嘲笑其外貌，思思认真要求尊重每个人追梦的权利。孙昊答应住一周，思思仍满怀期待准备大餐。\",\"turn\":\"孙昊对思思男装与阿牛外表的反应，具体暴露他接纳身份的局限；思思为室友立下尊重边界。\",\"time\":\"后续工作日中午\",\"people\":[\"张思凡\",\"孙昊\",\"胡玉牛\",\"王经理\",\"公司女职员\"],\"objects\":[\"请假条\",\"公文包\",\"镜子\",\"女装\"],\"places\":[\"思思公司\",\"火车站\",\"合租住处\"]},{\"key\":\"c209\",\"id\":209,\"title\":\"躁动\",\"kind\":\"main\",\"volume\":3,\"start\":825,\"end\":828,\"summary\":\"孙昊等思思换装时，阿牛独困热房，短暂出现轻生念头又压下，开始意识到自己的抑郁加深。思思精心换女装后重新获得恋人的热烈关注，随后忙做西餐，却被他不断纠缠亲热，她坚决拒绝在厨房继续。夕晨恰好出现，令两人尴尬，也立即吸引了孙昊的目光。\",\"turn\":\"阿牛心理危险上升；思思获得的亲密仍依赖女性形象，孙昊注意力开始转向夕晨。\",\"time\":\"同日下午\",\"people\":[\"张思凡\",\"孙昊\",\"胡玉牛\",\"林夕晨\"],\"objects\":[\"安眠药\",\"淡黄色假发\",\"围裙\",\"西餐材料\"],\"places\":[\"阿牛卧室\",\"思思卧室\",\"厨房\"]},{\"key\":\"c210\",\"id\":210,\"title\":\"童颜巨乳的杀伤力\",\"kind\":\"main\",\"volume\":3,\"start\":829,\"end\":832,\"summary\":\"孙昊靠近夕晨看电视，介绍自己时有意只称思思的朋友；思思察觉不悦仍加以宽容。莜莜下班初次见他后礼貌相待，雨晴则一贯冷淡。西餐席上阿牛不会用刀叉而烦躁，夕晨默学雨晴；孙昊依次敬酒、盯视夕晨并调笑身材，莜莜遂明确告诉他夕晨与大家一样并非出生为女。\",\"turn\":\"孙昊淡化恋人名分并觊觎室友，晚餐上的身份揭示为进一步反应作铺垫。\",\"time\":\"同日下午至晚餐\",\"people\":[\"孙昊\",\"张思凡\",\"林夕晨\",\"苏雨晴\",\"方莜莜\",\"胡玉牛\"],\"objects\":[\"刀叉\",\"牛排\",\"咖啡\",\"果汁\",\"红酒\",\"假发\"],\"places\":[\"合租住处客厅与餐桌\"]},{\"key\":\"c211\",\"id\":211,\"title\":\"舔\",\"kind\":\"main\",\"volume\":3,\"start\":833,\"end\":835,\"summary\":\"得知夕晨身份后孙昊仍关注她，思思明显吃醋、要求他收敛，却把不安当作错觉。晚间夕晨替怕冷的雨晴分盖外衣，两人相拥睡在沙发上，莜莜再为她们盖毯；阿牛反锁房门不回应关心，大家仍相信他身体强壮。夜深后思思与孙昊亲密，叙述确认她曾受富商包养控制与药物伤害。\",\"turn\":\"照顾与隔绝同时发生；思思的旧伤获得叙述确认，阿牛的无回应被低估。\",\"time\":\"来访当日晚间至深夜\",\"people\":[\"张思凡\",\"孙昊\",\"林夕晨\",\"苏雨晴\",\"方莜莜\",\"胡玉牛\",\"富商\"],\"objects\":[\"大衣\",\"薄毯\",\"空调遥控器\",\"安眠药\"],\"places\":[\"合租客厅\",\"阿牛卧室\"]},{\"key\":\"c212\",\"id\":212,\"title\":\"榨干\",\"kind\":\"main\",\"volume\":3,\"start\":836,\"end\":839,\"summary\":\"思思与孙昊彻夜亲密直至极度疲惫，过程中她未充分尊重他想停下休息的意愿。两人睡到次日下午，声音嘶哑、乏力口渴，由夕晨递水照料；思思担心旷工被辞，才发现莜莜早已替她联系领导请假。随后她照顾仍虚弱的孙昊，也追问得知他交往过十几个女友。\",\"turn\":\"热烈亲密造成身体透支，同伴替两人维持生活与工作秩序；恋爱经历差异进一步显露。\",\"time\":\"来访次日凌晨至下午五时\",\"people\":[\"张思凡\",\"孙昊\",\"林夕晨\",\"方莜莜\"],\"objects\":[\"请假短信\",\"手机通话记录\",\"热水壶\",\"水杯\",\"可乐\"],\"places\":[\"合租客厅\",\"浴室\"]},{\"key\":\"c213\",\"id\":213,\"title\":\"散心（上）\",\"kind\":\"main\",\"volume\":3,\"start\":840,\"end\":842,\"summary\":\"叙事回到当天早晨，休假的雨晴醒来发现自己抱着夕晨安睡，既羞怯又高兴。她不愿整天面对思思与孙昊，邀夕晨出门却被专注作画的对方婉拒，于是撑伞随意坐公交散心。车经过初来时露宿的小木屋与三流站，她意识到合租、工作与朋友已改变生活，又不自觉在无名面馆附近下车。\",\"turn\":\"新生活的安稳与旧地的回望相互映照，雨晴尝试整理自己失去和得到的东西。\",\"time\":\"回到来访次日早八时\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"孙昊\",\"胡玉牛\",\"方莜莜\",\"公交司机\"],\"objects\":[\"遮阳伞\",\"进口墨镜\",\"背包\"],\"places\":[\"合租住处\",\"公交车\",\"旧木屋台阶\",\"三流站\",\"无名面馆附近\"]},{\"key\":\"c214\",\"id\":214,\"title\":\"散心（下）\",\"kind\":\"main\",\"volume\":3,\"start\":843,\"end\":845,\"summary\":\"雨晴在无名面馆外看见李叔叔读报、张阿姨午憩，感激当年收留，也想告知如今安顿下来，却因穿裙且怕再遭其儿子般的羞辱而没有进门。她买奶茶沿旧街行走，习惯性寻找早已同住的曲奇，并回想一则能预知未来却每天失忆的故事，逐渐认可未知而不可重来的人生价值。\",\"turn\":\"她未完成旧友重逢，却清楚感受到有家难回的边界，并从寓言中理解未知的意义。\",\"time\":\"同日上午\",\"people\":[\"苏雨晴\",\"张阿姨\",\"李叔\",\"李天明\",\"曲奇\",\"奶茶店老板\",\"预知者及妻子\"],\"objects\":[\"奶茶\",\"招牌\",\"自动售货机\",\"报纸\",\"遮阳伞\"],\"places\":[\"无名面馆门外\",\"奶茶店\",\"旧街\"]},{\"key\":\"c215\",\"id\":215,\"title\":\"夏日的河堤（上）\",\"kind\":\"main\",\"volume\":3,\"start\":846,\"end\":849,\"summary\":\"雨晴独坐旧河堤，想起莫空讲过的鱼与鹰，也困惑于自己越来越模糊的记忆，须反复核查排班。附近两位少年打闹落水又自行游起，她起初未认出他们；两人却认出游乐园唱歌的女孩，互相怂恿着来搭话。她感到被当作喜欢的女孩子看待，既开心又羞涩。\",\"turn\":\"旧游乐园缘分重新出现，雨晴首次体验同龄少年主动搭话的欣喜。\",\"time\":\"同日上午\",\"people\":[\"苏雨晴\",\"莫空\",\"万剑雷\",\"管鹏\"],\"objects\":[\"遮阳伞\",\"手机电视\",\"排班备忘录\"],\"places\":[\"旧河堤\",\"未通车公路\"]},{\"key\":\"c216\",\"id\":216,\"title\":\"夏日的河堤（下）\",\"kind\":\"main\",\"volume\":3,\"start\":850,\"end\":853,\"summary\":\"两位少年正式介绍姓名：浪人发型的是万剑雷，小圆脸是管鹏；玩笑与拘谨逗笑雨晴，也让她允许二人坐在附近。她隐瞒离家和打工，称自己仍在杭州上学、暑假来玩；他们则说即将升入文澜学院高中部。关于学校和未来的闲谈，使早早离校的她重新向往普通的求学生活。\",\"turn\":\"少年身份与关系被补全；雨晴以学生假话维护交往，也暴露她对正常校园生活的失落。\",\"time\":\"同日上午\",\"people\":[\"苏雨晴\",\"万剑雷\",\"管鹏\"],\"objects\":[\"遮阳伞\"],\"places\":[\"旧河堤\",\"文澜学院（谈及）\"]},{\"key\":\"c217\",\"id\":217,\"title\":\"淋雨（上）\",\"kind\":\"main\",\"volume\":3,\"start\":854,\"end\":857,\"summary\":\"管鹏拿万剑雷钱包扇风，翻出配美女图的维修广告名片，误会化解后，三人同步咳嗽又笑，雨晴羡慕两少年的默契。骤起风雨把她吹倒、伞也卷走，两人无需商量便一人扶她、一人追伞。少年们兴奋淋雨，她一边劝找地方避雨，一边向往这种无需顾忌的任性自由。\",\"turn\":\"默契不只停在玩笑中，也化为照料她的行动；保护与自由形成吸引。\",\"time\":\"同日上午突发雷雨\",\"people\":[\"苏雨晴\",\"万剑雷\",\"管鹏\"],\"objects\":[\"钱包\",\"维修广告名片\",\"硬币\",\"遮阳伞\"],\"places\":[\"旧河堤\"]},{\"key\":\"c218\",\"id\":218,\"title\":\"淋雨（下）\",\"kind\":\"main\",\"volume\":3,\"start\":858,\"end\":861,\"summary\":\"雨晴因早产、先天心脏病和童年重病经历不敢随少年淋雨，想起母亲长期照顾。万剑雷忽然决定离开，她又落入难结新友的孤独。之后独往集装箱，看燕子哺雏更思念父母，未坐多久便返程；第二阵暴雨来时，她终于收伞奔跑，虽疲惫打喷嚏，却由衷感到活着与偶尔任性的快乐。\",\"turn\":\"母爱既是保护也是负疚来源；一次主动淋雨使积郁暂时释放，却埋下身体后果。\",\"time\":\"同日上午至午后，两阵暴雨\",\"people\":[\"苏雨晴\",\"苏雨晴的母亲\",\"万剑雷\",\"管鹏\",\"燕子一家\"],\"objects\":[\"遮阳伞\",\"童年冰淇淋\",\"燕巢\"],\"places\":[\"河堤\",\"郊区农田\",\"集装箱屋檐\",\"乡间返程路\"]},{\"key\":\"c219\",\"id\":219,\"title\":\"全身除毛\",\"kind\":\"main\",\"volume\":3,\"start\":862,\"end\":865,\"summary\":\"雨晴淋湿返家已觉头晕发冷，在门口遇到同样晚归的阿牛，发现他做了全身激光除毛，却因仍不像女孩而更加失落。两人沉默同行，她习惯性的“以后会好”也显得无力。阿牛再次锁门独处，雨晴帮他摆好乱踢的鞋，自己洗澡时既预感感冒，又从对照中意识到外表上的幸运。\",\"turn\":\"投入昂贵身体改变未缓解阿牛的自我否定；雨晴的任性则开始付出身体代价。\",\"time\":\"同日下午五时左右\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"张思凡\",\"孙昊\",\"方莜莜\"],\"objects\":[\"激光除毛\",\"帆布鞋\",\"板蓝根\",\"浴室镜子\"],\"places\":[\"合租楼下\",\"住处客厅\",\"浴室\"]},{\"key\":\"c220\",\"id\":220,\"title\":\"后天性天然呆\",\"kind\":\"main\",\"volume\":3,\"start\":866,\"end\":869,\"summary\":\"雨晴洗澡被修后标识颠倒的冷热水开关吓到；夕晨在阳台画简笔画、照料曲奇和咖啡，叙述补充她平时也用复杂线条表达未知情绪。晚餐前莜莜被蚊咬向雨晴借风油精，她先拿成红花油，急着回房又绊倒，坐下后竟忘了借药之事，被思思戏称“后天性天然呆”。\",\"turn\":\"雨晴记忆与反应问题以笑闹呈现，夕晨的画及宠物照料补充其沉默之外的表达。\",\"time\":\"同日傍晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"张思凡\",\"孙昊\",\"曲奇\",\"咖啡\"],\"objects\":[\"冷热颠倒的喷头开关\",\"抽象线条画\",\"风油精\",\"红花油\",\"巫女服\"],\"places\":[\"浴室\",\"阳台\",\"合租客厅\"]},{\"key\":\"c221\",\"id\":221,\"title\":\"龙卷风\",\"kind\":\"main\",\"volume\":3,\"start\":870,\"end\":873,\"summary\":\"天气反常早暗，雨晴感冒疲倦先睡，其他人也陆续回房；迟来的新闻警告海上龙卷风登陆，狂风暴雨造成街道积水、树木倒伏和设施损坏，次日还会有第二波，全城临时停课停工。她在高热梦中被纷乱线条困扰，清晨醒来看见死寂废墟，不知昨夜灾情而以为末日到来。\",\"turn\":\"暴雨后的身体病情与城市灾害并发，把日常住所变成暂时受困之地。\",\"time\":\"同日夜间至次日清晨五点半\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"孙昊\",\"林夕晨\"],\"objects\":[\"板蓝根\",\"电视天气预警\",\"倒树\",\"自行车\",\"广告牌\"],\"places\":[\"合租楼\",\"小城市街道\",\"高热梦境\"]},{\"key\":\"c222\",\"id\":222,\"title\":\"严重发烧\",\"kind\":\"main\",\"volume\":3,\"start\":874,\"end\":877,\"summary\":\"发高烧的雨晴找不到室友回应，误以为只剩自己一人；思思被喊醒后抱住她，解释龙卷风和停工消息，再抱她回床休息。测得三十九点五度，家中退烧药几近用尽、药店未开，思思先用仅剩药物照料并熬姜汤，莜莜起床一起帮忙；她们的关心真实，临时应对却十分仓促。\",\"turn\":\"雨晴确认同伴仍在而重获安全感，有限药品和第二波灾害将考验照护。\",\"time\":\"灾后次日清晨\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\"],\"objects\":[\"医药箱\",\"体温计\",\"退烧药\",\"湿毛巾\",\"姜汤\",\"缺失的安眠药\"],\"places\":[\"合租客厅\",\"雨晴卧室\",\"厨房\"]},{\"key\":\"c223\",\"id\":223,\"title\":\"呓语\",\"kind\":\"main\",\"volume\":3,\"start\":878,\"end\":881,\"summary\":\"第二波大风提前到来，新闻纠正此次实际是台风，购药计划被迫取消。大家吃储备早餐，思思又被孙昊的专一誓言安抚；阿牛仍疏离。众人探望高烧梦中哭喊母亲的雨晴，夕晨握手贴颊使她平静。莜莜借机透露生母早年离开且已失联，如今与继母及父亲也少有亲近。\",\"turn\":\"夕晨的实际陪伴安抚雨晴的失亲恐惧，并引出莜莜不同于她的家庭缺憾。\",\"time\":\"台风日上午七点半后\",\"people\":[\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"张思凡\",\"孙昊\",\"胡玉牛\",\"莜莜生母\",\"方莜莜继母\",\"莜莜父亲\"],\"objects\":[\"储备面包牛奶\",\"电视新闻\",\"姜汤\"],\"places\":[\"合租住处\",\"雨晴病床\"]},{\"key\":\"c224\",\"id\":224,\"title\":\"虚弱\",\"kind\":\"main\",\"volume\":3,\"start\":882,\"end\":885,\"summary\":\"海边别墅少女雯雯在风暴中向女仆水水谈及未来不同阶段的自己，嘱她照顾将来茫然抗拒世界的“我”；女仆长又称水水“小诗”。窗外莫空困惑于她所说的世界线，同时想起雨晴，明确选择不打扰的守护式爱意。另一边雨晴中午仍虚弱，夕晨守候并端来姜汤，一勺一勺照料。\",\"turn\":\"无名少女获得昵称并显出时间悬念；莫空的爱意与夕晨的贴身照料形成不同守护方式。\",\"time\":\"台风日白天至中午\",\"people\":[\"雯雯\",\"水水\",\"女仆长\",\"莫空\",\"苏雨晴\",\"林夕晨\"],\"objects\":[\"落地窗\",\"叫花鸡（计划）\",\"雨伞\",\"姜汤\"],\"places\":[\"海边别墅\",\"台风中的海滩\",\"雨晴卧室\"]},{\"key\":\"c225\",\"id\":225,\"title\":\"喂食\",\"kind\":\"main\",\"volume\":3,\"start\":886,\"end\":889,\"summary\":\"夕晨喂病中的雨晴喝姜汤，以过分亲密却面无表情的方式帮她应对烫口，被思思和莜莜看见后起哄。雨晴脱口而出两人可以都是女朋友，得到她们认真认可，初次为自己的感情找到不必扮男性的解释；但她仍否认已成情侣，夕晨也依她的示意称其妹妹，关系保持含蓄未定。\",\"turn\":\"“两个都是女朋友”松动雨晴的性别角色困惑，但亲密举动尚不等于双方确认恋爱。\",\"time\":\"台风日中午\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\"],\"objects\":[\"姜汤\",\"碗与瓷勺\",\"微波炉\"],\"places\":[\"雨晴卧室\"]},{\"key\":\"c226\",\"id\":226,\"title\":\"停电\",\"kind\":\"main\",\"volume\":3,\"start\":890,\"end\":893,\"summary\":\"台风导致停电，思思因刚掉落的游戏装备未拾取而暴躁，被孙昊答应赔买后安抚；莜莜则提到游戏里有要好的朋友，明确并非男友。雨晴稍有好转，在黑暗中由夕晨牵手、曲奇叫声与尾巴提醒，慢慢走到客厅与大家汇合，莜莜用手机微光引路，众人决定聚着讲鬼故事。\",\"turn\":\"停电中烦躁与温柔同时显现，微光、牵手和猫共同建立集体的临时安全感。\",\"time\":\"台风日中午后\",\"people\":[\"张思凡\",\"孙昊\",\"方莜莜\",\"苏雨晴\",\"林夕晨\",\"曲奇\",\"安念\"],\"objects\":[\"游戏戒指\",\"停电灯泡\",\"枕头\",\"手机微光\"],\"places\":[\"合租住处\",\"雨晴卧室至客厅\"]},{\"key\":\"c227\",\"id\":227,\"title\":\"悬疑鬼故事\",\"kind\":\"main\",\"volume\":3,\"start\":894,\"end\":897,\"summary\":\"雨晴因一杯热水感到同伴关心，也自省近来会因微小玩笑长久难过。莜莜再次邀阿牛出房，他借黑暗穿护士装出来；孙昊暗中嘲笑，思思认真制止。随后思思讲浴室有鬼的故事，用激将法让病中的雨晴去看，她不愿被瞧不起而勉强走入，竟真的见到恐怖景象。\",\"turn\":\"阿牛暂时加入集体，恶作剧却利用雨晴怕被轻视的心理，把她推入惊恐。\",\"time\":\"台风停电期间\",\"people\":[\"苏雨晴\",\"方莜莜\",\"胡玉牛\",\"孙昊\",\"张思凡\",\"林夕晨\"],\"objects\":[\"热水杯\",\"粉色护士装\",\"手机光\"],\"places\":[\"停电客厅\",\"浴室\"]},{\"key\":\"c228\",\"id\":228,\"title\":\"恶作剧\",\"kind\":\"main\",\"volume\":3,\"start\":898,\"end\":901,\"summary\":\"雨晴和莜莜先后被浴室发光鬼脸与尖叫吓坏，阿牛进去查看后也失声，思思、孙昊又相继“消失”。夕晨镇静开手电，照出装鬼的思思：录音机、贴纸和几人配合构成恶作剧，阿牛起初差点动手后才加入。雨晴生气，莜莜要求别再这样；夕晨解释母亲说鬼伤不了人。\",\"turn\":\"鬼故事以人为把戏收束，夕晨的镇定揭开真相，也显出她母亲给予的特殊安慰。\",\"time\":\"同一停电时段\",\"people\":[\"张思凡\",\"孙昊\",\"胡玉牛\",\"林夕晨\",\"苏雨晴\",\"方莜莜\",\"林夕晨母亲\"],\"objects\":[\"发光恐怖贴纸\",\"遥控录音机\",\"大功率手电筒\"],\"places\":[\"合租浴室与客厅\"]},{\"key\":\"c229\",\"id\":229,\"title\":\"融化的冰淇淋\",\"kind\":\"main\",\"volume\":3,\"start\":902,\"end\":905,\"summary\":\"停电使思思为大家买的昂贵进口冰淇淋逐渐融化，众人分吃后仍剩半箱，节俭的莜莜不舍丢弃。雨晴病未愈却吃冰淇淋，引发腹痛呕吐，思思自责道歉、莜莜热粥照料，阿牛沉稳确认医院仍开。朋友们担忧他的身份困境却不敢劝阻，彼此关怀与难以说出的真实想法交织。\",\"turn\":\"奢侈的小礼物因灾害失效，善意照料也会出错；阿牛仍能在他人危急时带来安定。\",\"time\":\"台风停电期间\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"孙昊\",\"林夕晨\"],\"objects\":[\"进口冰淇淋\",\"冰箱\",\"手电筒\",\"生姜米粥\"],\"places\":[\"合租客厅\",\"浴室\"]},{\"key\":\"c230\",\"id\":230,\"title\":\"黑暗中的国王游戏\",\"kind\":\"main\",\"volume\":3,\"start\":906,\"end\":909,\"summary\":\"莜莜提出成语接龙与传递信物结合的国王游戏，失败者由持信物者罚，众人选曲奇作传递对象，并让不擅说话的夕晨免答词。病中的雨晴不愿被排除，仍坚持参加；起初大家认真，后来规则被不断曲解、接龙偏向她难理解的成人笑话，她接连失败，把惩罚暂时累积。\",\"turn\":\"游戏让沉默与疏离者重新同坐，规则滑向越界玩笑也使雨晴的弱势更明显。\",\"time\":\"台风停电期间\",\"people\":[\"方莜莜\",\"张思凡\",\"孙昊\",\"胡玉牛\",\"苏雨晴\",\"林夕晨\",\"曲奇\"],\"objects\":[\"国王游戏\",\"曲奇信物\",\"手电筒\"],\"places\":[\"停电客厅\"]},{\"key\":\"c231\",\"id\":231,\"title\":\"暧昧的惩罚\",\"kind\":\"main\",\"volume\":3,\"start\":910,\"end\":913,\"summary\":\"接龙规则继续漂移，雨晴累积第三次失败，莜莜提出与夕晨亲密互动的惩罚，思思又在她犹豫时推着促成并拍照。阿牛虽曾开口，实际只建议关掉手电，没有真正制止压力。雨晴羞窘起身后头晕，倒在夕晨怀里睡着，众人确认只是困倦才放下心，游戏在疲惫与含蓄心动中停歇。\",\"turn\":\"游戏留下雨晴与夕晨的合照，但起哄和推动越过了明确同意，不能据此认定恋爱。\",\"time\":\"台风日下午\",\"people\":[\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"张思凡\",\"胡玉牛\",\"孙昊\",\"曲奇\"],\"objects\":[\"数码相机\",\"手电筒\",\"亲密合照\",\"蜂蜜水\"],\"places\":[\"停电客厅\"]},{\"key\":\"c232\",\"id\":232,\"title\":\"神清气爽\",\"kind\":\"main\",\"volume\":3,\"start\":914,\"end\":916,\"summary\":\"台风离去的清晨，咖啡翻动雨晴摘抄本，平凡构成人生的句子与灾后安静相映。雨晴退烧醒来异常精神，发现病中已有几天没吃药，短暂向往不用药也能保持女性身体的生活，最终仍因害怕男性化而恢复用药。她看见数次未知号码未接来电，又读到王海峰要求今日复工的短信。\",\"turn\":\"身体轻松引出对长期代价的清醒犹豫；未知来电与复工将她重新带回外部世界。\",\"time\":\"台风离去后清晨四点五十分\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"王海峰\",\"未知来电者\"],\"objects\":[\"摘抄练习本\",\"橘子\",\"药盒\",\"手机未接来电\",\"复工短信\"],\"places\":[\"雨晴卧室\"]},{\"key\":\"c233\",\"id\":233,\"title\":\"台风过后\",\"kind\":\"main\",\"volume\":3,\"start\":917,\"end\":920,\"summary\":\"雨晴早起整理工作物品，阿牛却以要提前上班为由独自先走，继续回避同行。她穿新帆布鞋缓步赴工，看到灾后积水、倒树、涨价早餐及与现实不符的乐观报道；上班者与学生仍须涉水恢复日常。一个把树枝当剑、兴奋玩水的小学生，让她想起自己渐被成长和社会磨去的天真。\",\"turn\":\"阿牛继续退出共同日常，雨晴在城市复工景象中体认成长的失落。\",\"time\":\"同日清晨赴早班\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"玩水小学生\",\"早餐店主\"],\"objects\":[\"工作纸袋\",\"故事会\",\"新浅蓝帆布鞋\",\"灾情报纸\",\"菜包豆浆\",\"树枝\"],\"places\":[\"合租住处\",\"灾后街道\"]},{\"key\":\"c234\",\"id\":234,\"title\":\"芥末味棒棒糖\",\"kind\":\"main\",\"volume\":3,\"start\":921,\"end\":924,\"summary\":\"台风后超市仍供电，因无新货而清闲，王海峰安排雨晴与陈淑艳上班，并说明实习工无需补休。雨晴看两人互损、谈孩子复学与大学经历，感到工作像熟悉校园般轻松，甚至主动笑说不当电灯泡。陈淑艳表面谢主管照顾，递上一支写巧克力的棒棒糖，实际是芥末味，把王海峰辣得咳嗽。\",\"turn\":\"部门互损成为雨晴少有的轻松社交，她也逐渐能主动参与玩笑。\",\"time\":\"灾后复工日清晨\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"陈淑艳儿子\"],\"objects\":[\"芥末味棒棒糖\",\"嵌糕\",\"可乐\",\"霓虹招牌\",\"工作服\"],\"places\":[\"大润发员工通道\",\"更衣室\",\"员工餐厅\"]},{\"key\":\"c235\",\"id\":235,\"title\":\"炙热的艳阳\",\"kind\":\"main\",\"volume\":3,\"start\":925,\"end\":927,\"summary\":\"复工午间员工争抢临期食品茶话会，雨晴不惯抢食而独坐楼梯窗边吃炒面，比较旧日上流宴会的礼仪与底层生活的直接。灾后晴空使她向往历尽磨难后的重生，也意识到苦难未必换来幸福；王海峰受陈淑艳嘱托送来各种食物，以玩笑打断她的沉郁，让平凡同事情谊补回希望。\",\"turn\":\"雨晴对希望的抽象思考被具体关怀接住，部门两位同事共同照顾她。\",\"time\":\"灾后复工日中午\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"苏雨晴父母\",\"超市员工\"],\"objects\":[\"炒面\",\"茶话会食品\",\"楼梯长木椅\"],\"places\":[\"超市员工餐厅\",\"楼梯窗边\",\"灾后街道\"]},{\"key\":\"c236\",\"id\":236,\"title\":\"好烟和劣烟\",\"kind\":\"main\",\"volume\":3,\"start\":928,\"end\":931,\"summary\":\"阿牛独自清理后仓、少吃午餐以求身材变化，感到力气确实下降，旁人却仍只见强壮；复吸香烟也成了缓解孤独的习惯。买烟时他又遇莫空，对方同时买廉价大丰收和中华，先谈清贫与享乐，再说明只是体验笔下人物心理。阿牛从中想起兴趣与被迫工作之别，回头时莫空已离开。\",\"turn\":\"身体变化给阿牛微小希望，莫空以写作体验再度触及自主选择与幸福。\",\"time\":\"同日午后\",\"people\":[\"胡玉牛\",\"莫空\",\"杂货店老板娘\"],\"objects\":[\"白沙香烟\",\"大丰收香烟\",\"中华香烟\",\"后仓货品\"],\"places\":[\"超市后仓\",\"员工通道外杂货店\",\"街边台阶\"]},{\"key\":\"c237\",\"id\":237,\"title\":\"一碗猪肉面（上）\",\"kind\":\"main\",\"volume\":3,\"start\":932,\"end\":934,\"summary\":\"思思带孙昊到公司附近网吧，边上班边频繁联系，既惜短暂相聚也回避他对男装的不适。独处的夕晨通过挂名工作室承接插画，收入浮动却有保障；她不追求电脑，擅手工、布置层次丰富的房间，画出房间及猫鼠时向咖啡露出罕见笑容。因不擅料理，中午抱着曲奇、咖啡出门找饭店。\",\"turn\":\"夕晨作为创作者的自主生活和对动物的柔情浮现，沉默不再等同情感贫乏。\",\"time\":\"同日早晨至中午并行\",\"people\":[\"林夕晨\",\"曲奇\",\"咖啡\",\"张思凡\",\"孙昊\",\"绘画工作室\"],\"objects\":[\"房间剖面画\",\"毛线鱼\",\"手工物\",\"画具与专业书\",\"银行卡\"],\"places\":[\"夕晨卧室与阳台\",\"思思公司\",\"公司附近网吧\",\"外出街道\"]},{\"key\":\"c238\",\"id\":238,\"title\":\"一碗猪肉面（下）\",\"kind\":\"main\",\"volume\":3,\"start\":935,\"end\":938,\"summary\":\"夕晨在灾后涨价的拉面馆点牛肉面，老板却送来猪肉面，她虽注意清真标牌与餐食矛盾，仍不愿追究，只分食给猫鼠并沉入童话幻想。叙述说明她有约三万元存款、内心世界是安全感寄托。店外随后来两派人，以宗教标识和侮辱问题争吵堵门，她仍安静吃面，与惊慌食客形成反差。\",\"turn\":\"幻想、节省与外界冲突并置，揭出夕晨将现实和心灵隔开的生存方式。\",\"time\":\"同日中午\",\"people\":[\"林夕晨\",\"曲奇\",\"咖啡\",\"拉面馆老板\",\"争执双方\",\"食客\"],\"objects\":[\"牛肉面订单\",\"猪肉面\",\"清真标牌\",\"一次性筷子\",\"幻想缩小电筒\"],\"places\":[\"拉面馆\",\"夕晨幻想世界\"]},{\"key\":\"c239\",\"id\":239,\"title\":\"刷墙工\",\"kind\":\"main\",\"volume\":3,\"start\":939,\"end\":941,\"summary\":\"店内两派人终于扭打，夕晨吃完付款，抱猫鼠安然离开。路遇烈日下悠闲刷墙的工人，她想起父亲农闲进城苦工供其读书、把她所赠登山鞋珍藏，以及为唯一儿子取“希望的早晨”之名却把希写成夕。她以创业为由离家，既深爱父亲又不后悔追求女性生活，强烈负疚使冷静面具崩溃，落泪归家。\",\"turn\":\"夕晨的无表情显出自我麻醉功能；父爱、重男轻女、身份与负疚形成深刻冲突。\",\"time\":\"同日中午后；插叙童年与离家\",\"people\":[\"林夕晨\",\"曲奇\",\"咖啡\",\"刷墙工\",\"林夕晨父亲\",\"林夕晨母亲\",\"林夕晨三位姐姐\",\"面馆争执双方\"],\"objects\":[\"登山鞋\",\"草鞋\",\"刷墙工具\",\"油漆桶\",\"大前门香烟\"],\"places\":[\"面馆\",\"缝纫厂围墙\",\"林家乡村与工地回忆\",\"返家街道\"]},{\"key\":\"c240\",\"id\":240,\"title\":\"肯德基\",\"kind\":\"main\",\"volume\":3,\"start\":942,\"end\":945,\"summary\":\"思思忙完任务已近下午一点，与孙昊到肯德基吃午餐。男装的她被恋人当众亲昵称呼，引来顾客厌恶和母亲对孩子的贬斥，只能仓皇打包离开；她又把收银员口误疑作驱赶。孙昊轻描淡写说反正要变女孩，触怒她而挨一巴掌；两人沉默后同时道歉、继续去吃东西，表面和好却已埋下隔阂。\",\"turn\":\"社会羞辱与恋人不能理解她的双重身份引发冲突；相互道歉未能消除关系裂缝。\",\"time\":\"灾后复工日中午十一点半至下午一时后\",\"people\":[\"张思凡\",\"孙昊\",\"王经理\",\"公司女职员\",\"肯德基收银员\",\"年轻母亲与孩子\"],\"objects\":[\"短信\",\"工作任务\",\"肯德基餐食\",\"儿童套餐礼物\"],\"places\":[\"思思办公室\",\"公司楼下\",\"肯德基\",\"店外街道\"]},{\"key\":\"c241\",\"id\":241,\"title\":\"大白腿（上）\",\"kind\":\"main\",\"volume\":3,\"start\":946,\"end\":949,\"summary\":\"方莜莜兼任后勤保全组长、程序开发与英文合同撰写，虽获老板信任，却一人承担多职、周旋于职场关系。她鼓励擅长数学但容易分心的年轻下属朱志杰学习编程。送餐女孩意外打翻饭菜弄脏她的裤子，她温和免于责难，准备请林夕晨送替换衣物。\",\"turn\":\"职场的男性呈现与真实身体之间，因换裤子的意外出现暴露风险。\",\"time\":\"台风后的工作日\",\"people\":[\"方莜莜\",\"朱志杰\",\"公司老板\",\"送餐女孩\"],\"objects\":[\"账号保护软件\",\"英文外贸合同\",\"编程教程\",\"弄脏的裤子\"],\"places\":[\"公司后勤保全办公室\"]},{\"key\":\"c242\",\"id\":242,\"title\":\"大白腿（下）\",\"kind\":\"main\",\"volume\":3,\"start\":950,\"end\":953,\"summary\":\"方莜莜在办公室脱去被汤弄脏的外裤，朱志杰意外注意到她明显女性化的身体，她担心同事把自己视为异类，随后误打开女装网页又加深尴尬。林夕晨送来宽松男裤，朱志杰主动买单、借上厕所避开换衣。方莜莜想以女性身份生活，却仍受手术费用与证件限制。\",\"turn\":\"朱志杰发现反常但尚未追问，双方努力维持同事关系。\",\"time\":\"同 c241 午后\",\"people\":[\"方莜莜\",\"朱志杰\",\"林夕晨\",\"送餐女孩\"],\"objects\":[\"宽松男裤\",\"女装网页\",\"身份证\"],\"places\":[\"公司后勤保全办公室\"]},{\"key\":\"c243\",\"id\":243,\"title\":\"恐怖片（上）\",\"kind\":\"main\",\"volume\":3,\"start\":954,\"end\":957,\"summary\":\"苏雨晴早班回家，短暂不见林夕晨便觉得不安；室友陆续回来，合租屋的热闹重新带来安全感。众人担心胡玉牛越来越疏远，尤其怕他私自寻求危险的身体手术。张思凡和孙昊亲密嬉闹，林夕晨替他们拿衣物却全拿成女装，孙昊被迫短暂配合。\",\"turn\":\"集体日常的温暖，与胡玉牛独自承受压力形成落差。\",\"time\":\"台风后傍晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"孙昊\",\"方莜莜\",\"胡玉牛\",\"曲奇\",\"咖啡\"],\"objects\":[\"画板\",\"融坏的冰淇淋\",\"两套女装\"],\"places\":[\"合租屋\",\"厨房\",\"卫生间\"]},{\"key\":\"c244\",\"id\":244,\"title\":\"恐怖片（下）\",\"kind\":\"main\",\"volume\":3,\"start\":958,\"end\":961,\"summary\":\"孙昊穿女装引起笑闹后换回衣服。晚饭时胡玉牛仍未归，室友担忧却不敢强行干涉。张思凡坚持播放恐怖片，答应把一台 GBA 送给不愿看的苏雨晴。众人逐渐被影片吸引，门突然打开又关闭造成惊吓，最后发现只是胡玉牛回家，他的道歉显得十分生疏。\",\"turn\":\"胡玉牛与室友的隔阂被集体娱乐后的疏离反应再次显现。\",\"time\":\"同日晚间\",\"people\":[\"孙昊\",\"张思凡\",\"方莜莜\",\"苏雨晴\",\"林夕晨\",\"胡玉牛\"],\"objects\":[\"恐怖片影碟\",\"DVD机\",\"GBA游戏机\",\"USB小台灯\"],\"places\":[\"合租屋客厅\"]},{\"key\":\"c245\",\"id\":245,\"title\":\"胡玉牛的爱情（一）\",\"kind\":\"main\",\"volume\":3,\"start\":962,\"end\":965,\"summary\":\"胡玉牛晚归沉默，原因并非工作或用药，而是十六岁顾客柳韵向二十岁的他告白。此前他在超市三次帮忙，让少女因安全感而喜欢上他。河中公园赴约后，胡玉牛既被打动，又害怕自己的女性愿望伤害对方，终于拒绝并逃走，留下柳韵哭泣。\",\"turn\":\"恋爱选择使胡玉牛的性别愿望、自卑与责任感正面冲突。\",\"time\":\"回溯当日下午六点\",\"people\":[\"胡玉牛\",\"柳韵\",\"苏雨晴\",\"张思凡\",\"方莜莜\"],\"objects\":[\"可乐箱\"],\"places\":[\"超市\",\"河中公园\",\"合租屋\"]},{\"key\":\"c246\",\"id\":246,\"title\":\"胡玉牛的爱情（二）\",\"kind\":\"main\",\"volume\":3,\"start\":966,\"end\":969,\"summary\":\"胡玉牛在公交车上反省自己的愿望，承认它包含希望漂亮、受欢迎的成分，又认为梦想不必划分纯粹与否；回家仍拒绝交流，只读心理学书。新闻称面馆冲突嫌疑人已被警方控制。苏雨晴与咖啡相伴入睡，再梦见公园男孩，他哀悼一位未具名朋友，坟碑没有文字。\",\"turn\":\"自我反省没有消除胡玉牛的孤立；无名坟墓构成未解的不祥预示。\",\"time\":\"台风刚过去的第一夜\",\"people\":[\"胡玉牛\",\"苏雨晴\",\"方莜莜\",\"梦中男孩\",\"咖啡\",\"曲奇\"],\"objects\":[\"心理学书\",\"瓜子\",\"毛绒熊\",\"箫\",\"无字墓碑\"],\"places\":[\"公交车\",\"合租屋\",\"梦中公园\"]},{\"key\":\"c247\",\"id\":247,\"title\":\"胡玉牛的爱情（三）\",\"kind\":\"main\",\"volume\":3,\"start\":970,\"end\":973,\"summary\":\"梦中血雨冲开坟墓、露出模糊魁梧身影，苏雨晴惊醒后迅速遗忘。现实中柳韵在河中公园睡着，神秘九尾狐耳少女替她盖上男式外套；她误认是胡玉牛暗中照顾，重燃追求希望。胡玉牛一夜不眠又担心她受伤害，清早独自上班，对苏雨晴仍亲善却因自卑回避同行。\",\"turn\":\"一件来历被误认的外套，让本已被拒绝的恋爱继续发展。\",\"time\":\"翌日清晨\",\"people\":[\"苏雨晴\",\"梦中男孩\",\"柳韵\",\"神秘狐耳少女\",\"胡玉牛\",\"超市主管\"],\"objects\":[\"无字墓碑\",\"男式大衣\",\"闹钟\"],\"places\":[\"梦中公园\",\"河中公园\",\"超市\",\"合租屋\"]},{\"key\":\"c248\",\"id\":248,\"title\":\"胡玉牛的爱情（四）\",\"kind\":\"main\",\"volume\":3,\"start\":974,\"end\":977,\"summary\":\"胡玉牛工作时心神不宁，拒绝与苏雨晴同行，下班受莫名心悸驱使走向与家相反的河边。听见呼救后发现柳韵正遭数名混混围困、面临性侵。他挺身救人，先借谈钱转移持刀者注意，但身体状态下降导致判断失误，最后一刻仍挡下了威胁柳韵的刀。\",\"turn\":\"保护他人的习惯压过退缩；救人使胡玉牛直面身体能力的变化。\",\"time\":\"翌日下班后\",\"people\":[\"胡玉牛\",\"苏雨晴\",\"柳韵\",\"河边混混团伙\"],\"objects\":[\"折叠小刀\"],\"places\":[\"超市\",\"河边柳树林\"]},{\"key\":\"c249\",\"id\":249,\"title\":\"胡玉牛的爱情（五）\",\"kind\":\"main\",\"volume\":3,\"start\":978,\"end\":981,\"summary\":\"胡玉牛击倒六名混混，带柳韵离开后已明显体力透支；少女却把他视为理想英雄，更加主动亲近，自述小名音音来自奶奶的误读。她拿出外套坚信胡玉牛暗中爱护自己，即使他否认也不信。胡玉牛害怕坦白愿望后受鄙视，最终陪她逛步行街，在恋爱与自我追求间摇摆。\",\"turn\":\"救援转成约会，关系已靠近，但身体愿望的核心事实尚未坦白。\",\"time\":\"同日晚间\",\"people\":[\"胡玉牛\",\"柳韵\",\"河边混混团伙\",\"柳韵奶奶\"],\"objects\":[\"男式大衣\"],\"places\":[\"河边柳树林\",\"步行街\"]},{\"key\":\"c250\",\"id\":250,\"title\":\"胡玉牛的爱情（六）\",\"kind\":\"main\",\"volume\":3,\"start\":982,\"end\":985,\"summary\":\"柳韵喜欢巨型白熊却因价高放弃，胡玉牛被她的体谅打动，买下玩偶。她把它视为定情信物，并回赠黑线狮子戒指和黑狮子编织玩偶，自称未婚妻。胡玉牛承认内心幸福，却仍隐瞒脱毛等身体改变；送她回家后提出一个月冷静期，柳韵把它理解为爱情考验。\",\"turn\":\"双方互赠信物却没有共同理解的正式承诺，一个月之约留下悬念。\",\"time\":\"救援约会当晚八点半后\",\"people\":[\"胡玉牛\",\"柳韵\",\"玩具店老板\",\"手工艺品摊主\"],\"objects\":[\"两米白熊玩偶\",\"黑线狮子戒指\",\"黑狮子编织玩偶\"],\"places\":[\"步行街\",\"玩具店\",\"柳韵家楼下\"]},{\"key\":\"c251\",\"id\":251,\"title\":\"苏雨晴在超市工作的日常（上）\",\"kind\":\"main\",\"volume\":3,\"start\":986,\"end\":988,\"summary\":\"2004年8月7日立秋暴雨，苏雨晴梦见幼儿园时母亲来接自己，醒来担心父母已经放弃寻找她。离家四个多月的她仍不敢计划春节返家，只为购电脑、身体手术等愿望存钱。清晨自制肉松鸡蛋泡饭，发现胡玉牛仍失眠恍惚；冰箱里持续出现的蛋糕则体现林夕晨的偏好。\",\"turn\":\"思乡与不敢回家并存，经济目标暂时代替了明确的人生方向。\",\"time\":\"2004年8月7日；离家四个多月\",\"people\":[\"苏雨晴\",\"苏雨晴的母亲\",\"苏榕槐\",\"胡玉牛\",\"林夕晨\",\"曲奇\"],\"objects\":[\"肉松鸡蛋泡饭\",\"蛋糕\",\"雨伞\"],\"places\":[\"合租屋\",\"幼儿园（梦中回忆）\"]},{\"key\":\"c252\",\"id\":252,\"title\":\"苏雨晴在超市工作的日常（下）\",\"kind\":\"main\",\"volume\":3,\"start\":989,\"end\":992,\"summary\":\"胡玉牛难得与苏雨晴共伞上班，试探真正的爱及受到女生告白后该如何选择。苏雨晴说愿尝试喜欢喜欢自己的人，想到若告白者是林夕晨则不能确定会拒绝。到超市后她面对大批货柜；女部门经理把正常轮休的王海峰指责为偷懒，使她看见善良勤劳也会被责难。\",\"turn\":\"胡玉牛向人求助却不明说；苏雨晴第一次具体设想与林夕晨恋爱的可能。\",\"time\":\"2004年8月7日清晨\",\"people\":[\"胡玉牛\",\"苏雨晴\",\"林夕晨\",\"王海峰\",\"女部门经理\",\"翁锡芽\"],\"objects\":[\"雨伞\",\"山楂片货箱\"],\"places\":[\"上班路\",\"大润发超市\"]},{\"key\":\"c253\",\"id\":253,\"title\":\"背锅侠王海峰\",\"kind\":\"main\",\"volume\":3,\"start\":993,\"end\":996,\"summary\":\"苏雨晴帮徐嫂整理沉重货箱，照例接受琐碎差事，用少说话保护身份秘密；筋疲力尽后几经折返才吃上午饭。休息日被叫回的王海峰又遭训斥：数据部把九十九元的酒错录为九元九，经理仍怪他未纠错。他不愿无休止争辩，表示愿承担五瓶酒的损失。\",\"turn\":\"职场权责不对等显形，苏雨晴对王海峰的同情和理解加深。\",\"time\":\"同日午间\",\"people\":[\"苏雨晴\",\"徐嫂\",\"王海峰\",\"女部门经理\",\"翁锡芽\"],\"objects\":[\"梯子\",\"货箱\",\"错误标价的酒\",\"木质长椅\"],\"places\":[\"超市货架区\",\"员工餐厅\",\"楼梯走廊\"]},{\"key\":\"c254\",\"id\":254,\"title\":\"职业打假人\",\"kind\":\"main\",\"volume\":3,\"start\":997,\"end\":1000,\"summary\":\"常务经理老梅愿替王海峰澄清赔钱之事并邀他调去防损部，王海峰嫌工作易得罪人而拒绝。回酒柜后，翁锡芽替苏雨晴写表格。一个在柜前徘徊很久的男人买下一百九十九元红酒，随后到前台投诉商品不合格，王海峰接报判断可能遇上职业打假者。\",\"turn\":\"不合格红酒引出索赔事件，年轻员工担心赔款被转嫁。\",\"time\":\"同日下午\",\"people\":[\"王海峰\",\"老梅\",\"苏雨晴\",\"翁锡芽\",\"红酒索赔者\"],\"objects\":[\"红酒\",\"表格\",\"防盗标签\",\"员工电话本\"],\"places\":[\"超市酒柜\",\"超市前台\"]},{\"key\":\"c255\",\"id\":255,\"title\":\"专业的和业余的\",\"kind\":\"main\",\"volume\":3,\"start\":1001,\"end\":1004,\"summary\":\"苏雨晴被叫到前台证明销售经过，忧虑索赔导致工资受损。王海峰问出对方熟知职业打假圈地盘更替，打电话给已接手本地的老耀；索赔者得知归属后退让。王海峰接回酒，再赠一包中华缓和冲突，使这场投诉在非正式人情与势力关系中被压下。\",\"turn\":\"投诉撤回，实际解决方式并非正式质量或法律裁决。\",\"time\":\"同日下午\",\"people\":[\"苏雨晴\",\"王海峰\",\"老梅\",\"女部门经理\",\"红酒索赔者\",\"老耀\",\"万老板\",\"辉哥\"],\"objects\":[\"不合格红酒\",\"购物小票\",\"中华香烟\",\"手机\"],\"places\":[\"超市前台\"]},{\"key\":\"c256\",\"id\":256,\"title\":\"检查保质期\",\"kind\":\"main\",\"volume\":3,\"start\":1005,\"end\":1008,\"summary\":\"王海峰圆满结束索赔协调，众人以玩笑缓和气氛；其他部门争邀苏雨晴，前台年轻女职员对王海峰流露好感。王海峰回去后要求酒柜促销员核查保质期和缺失厂家信息的商品，又把炒货区域每月检查交给苏雨晴，允许劳累的她当天先休息，次日开始。\",\"turn\":\"事件转化成例行质量检查；苏雨晴增加固定责任。\",\"time\":\"同日下午至下班前\",\"people\":[\"王海峰\",\"苏雨晴\",\"老梅\",\"前台年轻女职员\",\"酒柜促销员\",\"前台主管\",\"玩具部主管\",\"防损部主管\"],\"objects\":[\"保质期记录本\",\"缺失厂家信息的酒\"],\"places\":[\"超市前台\",\"酒柜\",\"炒货区\"]},{\"key\":\"c257\",\"id\":257,\"title\":\"一个人在家\",\"kind\":\"main\",\"volume\":3,\"start\":1009,\"end\":1012,\"summary\":\"下班后室友及宠物都不在家，林夕晨留纸条称有事，张思凡与孙昊外出约会，方莜莜也参加公司活动。已经依恋共同生活的苏雨晴因独处失落，独自做饭、看电视购物打发时间。她注意到眼下新生泪痣，入夜后因怕黑逐处开灯，最后躲回明亮卧室。\",\"turn\":\"她的安全感已深度依赖室友的在场，独处成为情绪引爆条件。\",\"time\":\"2004年8月7日下班后\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"孙昊\",\"方莜莜\",\"胡玉牛\",\"曲奇\",\"咖啡\"],\"objects\":[\"留字条\",\"泪痣\",\"电视购物节目\"],\"places\":[\"合租屋\"]},{\"key\":\"c258\",\"id\":258,\"title\":\"冉空城的电话\",\"kind\":\"main\",\"volume\":3,\"start\":1013,\"end\":1015,\"summary\":\"苏雨晴补写日记，记录打假见闻、宠物习惯并画红酒；游戏机没电又使她无事可做。想让方莜莜带电池时误拨冉空城，旧友回电令她几乎失语。她说不会再打扰便挂断关机，随即因怀念过去与害怕破坏他的生活而大哭，一边责备自己的软弱。\",\"turn\":\"偶然通话重新刺痛旧日关系，冉空城尚未被明确告知身份。\",\"time\":\"同日晚；章内称八点\",\"people\":[\"苏雨晴\",\"冉空城\",\"方莜莜\",\"曲奇\",\"咖啡\",\"阿旺\",\"老伟\"],\"objects\":[\"日记本\",\"GBA游戏机\",\"电池\",\"手机\",\"国产芭比娃娃\"],\"places\":[\"合租屋卧室\"]},{\"key\":\"c259\",\"id\":259,\"title\":\"没有人的公园\",\"kind\":\"main\",\"volume\":3,\"start\":1016,\"end\":1019,\"summary\":\"哭累入睡的苏雨晴再次来到梦中公园，外面热闹却仍被无形屏障隔开，秋千上的男孩首次不见。黑暗推进时她坐上秋千，竟变成那个幼小男孩，思考能力也受限；面对一个似曾相识的女孩，重复以往男孩寻找出路的话。梦境破碎时她又恢复自身，看见男孩在对面微笑。\",\"turn\":\"梦中身份互换将男孩与她的自我关联推到前景，但并未解释机制。\",\"time\":\"同夜梦境\",\"people\":[\"苏雨晴\",\"梦中男孩\",\"梦中女孩\"],\"objects\":[\"秋千\",\"无形屏障\",\"坟墓\"],\"places\":[\"梦中公园\"]},{\"key\":\"c260\",\"id\":260,\"title\":\"热闹的合租房\",\"kind\":\"main\",\"volume\":3,\"start\":1020,\"end\":1023,\"summary\":\"方莜莜回家，扶起从床上跌落又忘记梦境的苏雨晴，分享公司庆祝会带回的零食和奶茶，并温柔替她梳头、谈长发愿望。林夕晨衣着略乱地回来，只说去工作；随后胡玉牛、张思凡和孙昊也归来。合租屋恢复笑声，苏雨晴终于重新感到安心。\",\"turn\":\"照护与陪伴安抚情绪，林夕晨外出工作的具体内容仍未交代。\",\"time\":\"该章称七点半至八点；与 c258 八点有矛盾\",\"people\":[\"苏雨晴\",\"方莜莜\",\"林夕晨\",\"胡玉牛\",\"张思凡\",\"孙昊\"],\"objects\":[\"奶茶\",\"庆祝会零食\",\"梳子\",\"吹风机\"],\"places\":[\"合租屋客厅\"]},{\"key\":\"c261\",\"id\":261,\"title\":\"黑檀木梳\",\"kind\":\"main\",\"volume\":3,\"start\":1024,\"end\":1026,\"summary\":\"苏雨晴首次核查大量炒货保质期，才知同一区域的徽记促销员也应分担，却一直未帮忙；她仍选择认真做完自己的工作。下班寻不到胡玉牛，便按方莜莜推荐去古风梳子店。汉服老板娘介绍材质，并针对她的睡眠和体弱情况推荐黑檀木梳，苏雨晴准备在百元左右挑选。\",\"turn\":\"梳子从日常工具成为改善自我生活的消费选择；同事分工失衡暂未抗争。\",\"time\":\"次日早班至下午三点\",\"people\":[\"苏雨晴\",\"德芙促销员\",\"徽记促销员\",\"梳子店老板娘\",\"王海峰\",\"胡玉牛\"],\"objects\":[\"保质期记录\",\"黑檀木梳\",\"塑料梳\",\"金瓶梅（文化引用）\"],\"places\":[\"超市炒货区\",\"梳子专卖店\"]},{\"key\":\"c262\",\"id\":262,\"title\":\"送给自己的礼物\",\"kind\":\"main\",\"volume\":3,\"start\":1027,\"end\":1030,\"summary\":\"苏雨晴花一百二十元买下双面青莲纹的半圆黑檀木梳，获赠同材质木镜，视它为提醒自己保持本色、善待自己的礼物。回家后见林夕晨替宠物洗澡，又读到冉空城问“你是苏雨晴吗”的短信，最终删去不回。随后回想同桌拍照留念的往事，重温彼此希望美好时刻停留的心情。\",\"turn\":\"她开始主动善待自己，却仍回避旧友伸来的联系。\",\"time\":\"c261 同日下午；校园往事为回忆\",\"people\":[\"苏雨晴\",\"梳子店老板娘\",\"林夕晨\",\"冉空城\",\"曲奇\",\"咖啡\"],\"objects\":[\"青莲黑檀木梳\",\"黑檀木镜\",\"身份询问短信\",\"旧日合影/照片\"],\"places\":[\"梳子专卖店\",\"合租屋\",\"往日教室\"]},{\"key\":\"c263\",\"id\":263,\"title\":\"促销商品\",\"kind\":\"main\",\"volume\":3,\"start\":1031,\"end\":1034,\"summary\":\"王海峰让徽记促销员分担检查，苏雨晴终于查完保质期，午睡后被安排到电梯口推销清仓商品。她怕受关注，始终不敢吆喝，旺旺促销员示范也没令她放开。王海峰亲自招来顾客再交给她应答，她虽紧张，仍认真反复解答老人们的问题，逐渐进入工作状态。\",\"turn\":\"同事分工问题得到介入；被迫面对人群成为社交锻炼。\",\"time\":\"星期五下午\",\"people\":[\"苏雨晴\",\"王海峰\",\"徽记促销员\",\"旺旺促销员\",\"老年顾客们\"],\"objects\":[\"清仓商品\",\"红色价格贴纸\",\"扩音器\"],\"places\":[\"超市炒货区\",\"电梯口\"]},{\"key\":\"c264\",\"id\":264,\"title\":\"被搭讪了\",\"kind\":\"main\",\"volume\":3,\"start\":1035,\"end\":1037,\"summary\":\"清仓商品卖掉半车，苏雨晴留两包进口巧克力准备买回家，想到从优裕家庭到独立谋生后的节俭变化。防损部年轻男员工借挑货与她搭话，随后谎称新规定要求登记所有员工信息。她虽察觉可能是搭讪，却因对其岗位有所顾忌，仍交出姓名和电话号码。\",\"turn\":\"工作身份被周超借作接近渠道，陌生人的追求开始进入日常。\",\"time\":\"同日下午两点半左右\",\"people\":[\"苏雨晴\",\"周超\"],\"objects\":[\"促销进口巧克力\",\"员工电话号码\"],\"places\":[\"超市电梯口\"]},{\"key\":\"c265\",\"id\":265,\"title\":\"短信聊天\",\"kind\":\"main\",\"volume\":3,\"start\":1038,\"end\":1041,\"summary\":\"周六众人在郊外集装箱房赏雨，猫狗燕子相伴，张思凡与孙昊畅想有钱后在乡间共同生活。胡玉牛缺席，室友猜测其恋情与身体选择。苏雨晴收到昨天男员工短信；对方坦承骗取号码，自称周超，用可乐冰淇淋、占卜等话题热情聊天，她因无聊逐渐回应。\",\"turn\":\"周超接近成功；集体对胡玉牛的判断仍建立在猜测上。\",\"time\":\"星期六\",\"people\":[\"苏雨晴\",\"周超\",\"张思凡\",\"孙昊\",\"方莜莜\",\"林夕晨\",\"胡玉牛\",\"曲奇\",\"咖啡\",\"阿灰\",\"燕子一家\",\"郊外猫狗群\"],\"objects\":[\"GBA游戏机\",\"画板\",\"猫薄荷\",\"手机短信\"],\"places\":[\"郊外集装箱房\"]},{\"key\":\"c266\",\"id\":266,\"title\":\"哈士奇到底有多二\",\"kind\":\"main\",\"volume\":3,\"start\":1042,\"end\":1045,\"summary\":\"雨停后大家到河边，看哈士奇抓鱼却叼回石头，发现一只大草龟载着曲奇和咖啡游水；苏雨晴吹箫，心情趋于平静。周超连续邀请她去寺院、步行街，最后用新开的猫咖啡馆打动她。她怕单独赴约出现告白尴尬，提出带朋友同行，对方接受。\",\"turn\":\"好奇与谨慎同时起作用，约会以携带朋友的条件成立。\",\"time\":\"同一星期六\",\"people\":[\"苏雨晴\",\"周超\",\"张思凡\",\"孙昊\",\"方莜莜\",\"林夕晨\",\"曲奇\",\"咖啡\",\"阿灰\",\"大草龟\"],\"objects\":[\"箫\",\"鹅卵石\",\"短信\"],\"places\":[\"郊外河边\",\"流庆寺（提议未去）\",\"步行街（拟赴约）\"]},{\"key\":\"c267\",\"id\":267,\"title\":\"和林夕晨一起去\",\"kind\":\"main\",\"volume\":3,\"start\":1046,\"end\":1049,\"summary\":\"张思凡和方莜莜都不愿陪苏雨晴赴约，林夕晨则默默答应。听见周超可能转而追林夕晨的玩笑，她立刻紧张，室友察觉其占有欲。郊外晚餐后哈士奇阿灰随猎人主人老王回家；翌日苏雨晴七点才醒，匆匆与林夕晨乘公交赴约，带着对迟到的担忧。\",\"turn\":\"林夕晨成为陪伴者；苏雨晴对她的感情通过吃醋间接显露。\",\"time\":\"星期六晚至星期日清晨\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\",\"孙昊\",\"阿灰\",\"猎人老王\",\"扛农具的村民\",\"曲奇\"],\"objects\":[\"泡面\",\"猎弓\",\"兔子\"],\"places\":[\"郊外集装箱房\",\"村路\",\"公交车\"]},{\"key\":\"c268\",\"id\":268,\"title\":\"可乐味的冰淇淋\",\"kind\":\"main\",\"volume\":3,\"start\":1050,\"end\":1053,\"summary\":\"公交堵车使苏雨晴与林夕晨迟到，周超耐心等候并体贴招待。叙述补充他热爱追求、喜新厌旧，却通常在关系结束后才寻找下一位对象。三人买可乐味冰淇淋，周超的从容渐渐缓解苏雨晴紧张；她同时想到父母期待与自己的负罪感，随后同意去占卜店。\",\"turn\":\"苏雨晴对周超的戒备有所减轻，尚未形成恋爱承诺。\",\"time\":\"星期日上午九点半后\",\"people\":[\"苏雨晴\",\"林夕晨\",\"周超\",\"苏雨晴父母\"],\"objects\":[\"可乐味冰淇淋\",\"餐巾纸\"],\"places\":[\"步行街东入口\",\"冰淇淋店\"]},{\"key\":\"c269\",\"id\":269,\"title\":\"占卜（上）\",\"kind\":\"main\",\"volume\":3,\"start\":1054,\"end\":1057,\"summary\":\"三人进入以船舱、六芒阵和灯光营造神秘气氛的占卜店。苏雨晴一面识破舞台机关，一面期待对未来的安慰。黑袍占卜师说她前路虽有迷雾仍可通行，困难在受束缚的心而非不完整的身体，钥匙在她自己的天空。她震惊于话语仿佛洞悉身份，却追问不到具体答案。\",\"turn\":\"“天空中的钥匙”成为解开心结的主题伏笔，非已验证的预言。\",\"time\":\"同日上午\",\"people\":[\"苏雨晴\",\"林夕晨\",\"周超\",\"莫空\"],\"objects\":[\"门票扑克牌\",\"六芒阵\",\"煤油灯\",\"星空水晶球\"],\"places\":[\"步行街占卜店\"]},{\"key\":\"c270\",\"id\":270,\"title\":\"占卜（下）\",\"kind\":\"main\",\"volume\":3,\"start\":1058,\"end\":1061,\"summary\":\"苏雨晴获赠星空水晶球；林夕晨沉默占卜，得到血色火焰、尸骸与鬼脸的立体卡片；周超问两人谁能成为女友，收下八音盒和正反写“你好美”“想得美”的双面卡。午休后揭示黑袍人其实是莫空，老店主正式让他主持占卜工作，苏雨晴等人尚不知道。\",\"turn\":\"读者得知熟人身份；三份赠物各自留下人物命运的暗示。\",\"time\":\"同日中午\",\"people\":[\"苏雨晴\",\"林夕晨\",\"周超\",\"莫空\",\"占卜店老店主\",\"占卜店售票搭档\"],\"objects\":[\"星空水晶球\",\"血色火焰尸骸卡\",\"你好美/想得美卡\",\"红楼梦曲调八音盒\"],\"places\":[\"步行街占卜店\"]},{\"key\":\"c271\",\"id\":271,\"title\":\"深夜的星空\",\"kind\":\"main\",\"volume\":3,\"start\":1062,\"end\":1064,\"summary\":\"莫空深夜在天台观察众生、回忆技术与时代变化，仍珍视想象力和保持内在本色。他生于1982年，现把占卜工作当人生旅程的一段；曲奇和咖啡每晚来陪伴。困倦中他仿佛见到佩脚铃的少女从星空走来，指触额头后沉沉睡去，现实与幻觉界限未明。\",\"turn\":\"旁观世界的莫空也被纳入神秘线索；曲奇的双重家庭生活得到交代。\",\"time\":\"深夜至凌晨一点后；莫空生于1982年\",\"people\":[\"莫空\",\"曲奇\",\"咖啡\",\"广场唱歌的孩子\",\"天台幻见少女\"],\"objects\":[\"香烟\",\"猫粮\",\"脚铃\",\"李宁广告牌\"],\"places\":[\"莫空住处天台\",\"远处广场\"]},{\"key\":\"c272\",\"id\":272,\"title\":\"不能说话的少女\",\"kind\":\"main\",\"volume\":3,\"start\":1065,\"end\":1068,\"summary\":\"莫空醒后赶去占卜店，向年轻女房东提醒股市风险，回忆自己曾放弃家主位置以选择自由。开店时一位无法说话的少女静坐门口，眼神异样，最终递给他一张绘有狐狸与山水的精薄木卡后离去。他感到她与昨夜幻见少女相似，却不能解释来意。\",\"turn\":\"狐狸卡由神秘来客送到莫空手中，身份与含义均待后文。\",\"time\":\"翌日工作日上午八点半至九点后\",\"people\":[\"莫空\",\"莫空女房东\",\"不能说话的少女\",\"占卜店售票搭档\"],\"objects\":[\"狐狸山水木卡\",\"报纸\"],\"places\":[\"莫空租住楼房\",\"占卜店门口\"]},{\"key\":\"c273\",\"id\":273,\"title\":\"付账\",\"kind\":\"main\",\"volume\":3,\"start\":1069,\"end\":1071,\"summary\":\"周末约会平静结束后，周一超市忙碌，陈淑艳照顾疲惫的苏雨晴，周超解释自己是便衣暗保并邀请午餐。苏雨晴不愿欠人情，也珍惜为身体改变所存的钱，选择价廉的沙县小吃；周超要一并付账时，她坚持各付各的，努力维持清楚的相处界限。\",\"turn\":\"交往持续但付账边界明确，苏雨晴的节俭、独立与犹豫同时显现。\",\"time\":\"周一中午；承接昨日约会\",\"people\":[\"苏雨晴\",\"周超\",\"陈淑艳\",\"翁锡芽\",\"王海峰\",\"沙县小吃老板\"],\"objects\":[\"炒面\",\"工作服\",\"餐费\"],\"places\":[\"超市\",\"沙县小吃店\"]},{\"key\":\"c274\",\"id\":274,\"title\":\"划破手指\",\"kind\":\"main\",\"volume\":3,\"start\":1072,\"end\":1075,\"summary\":\"苏雨晴坚持午餐各自付账，周超最终尊重。回超市处理破包垃圾时，她遇见同样常被派脏累活的夏仕尼；周超负责监督，主动帮她拆包，还叫来废品老板加快处理。她连续开启易拉罐划伤手指，周超急忙拿消毒用品与创可贴，照顾让二人的距离缩短。\",\"turn\":\"拒绝经济依赖的边界成立，实际照护却令新关系更亲近。\",\"time\":\"周一午后\",\"people\":[\"苏雨晴\",\"周超\",\"夏仕尼\",\"张燕\",\"废品回收老板\",\"沙县小吃老板\"],\"objects\":[\"易拉罐\",\"剪刀\",\"终端机\",\"创可贴\",\"消毒用品\"],\"places\":[\"沙县小吃店\",\"超市破包处理处\"]},{\"key\":\"c275\",\"id\":275,\"title\":\"准备迎接大人物的小城市\",\"kind\":\"main\",\"volume\":3,\"start\":1076,\"end\":1079,\"summary\":\"小城市为迎接高级官员及外国考察团，整饰市容、关闭店铺、增加身份证盘查和通行收费。占卜店停业，莫空重回写作生活；他决定外出，因郊区公交骤减只能坐出租车，被加收高价仍接受。途中看到店主、居民与管理人员的冲突，城市发展愿景与普通人的生活损失并置。\",\"turn\":\"公共事件中断工作并限制出行，促成莫空郊游及后续假期。\",\"time\":\"考察团抵达前约二十天\",\"people\":[\"莫空\",\"占卜店老店主\",\"占卜店售票搭档\",\"出租车司机\",\"清扫大伯\",\"小城市管理人员\",\"受影响店主居民\"],\"objects\":[\"身份证\",\"出租车\",\"停业补偿\"],\"places\":[\"小城市中心街道\",\"听雨路公交终点站\"]},{\"key\":\"c276\",\"id\":276,\"title\":\"回忆里的老仆人\",\"kind\":\"main\",\"volume\":3,\"start\":1080,\"end\":1083,\"summary\":\"莫空赴郊外海边，村民兄弟互动触发少年家族回忆：父死母失踪后，奶奶被逼自尽、如祖父般的老仆遭毒害；他以派系斗争报复，眼看能继家主却选择离开。回到当下，他绕熟悉森林路来到别墅附近准备露营，远望体弱大小姐在女仆、管家陪同下乘帆船。\",\"turn\":\"莫空的克制与自由选择获得悲剧背景，别墅线再次接入主叙事。\",\"time\":\"停业假期；家族旧事为回忆\",\"people\":[\"莫空\",\"莫空父母\",\"莫空奶奶\",\"莫空老仆人\",\"莫家争权者\",\"小越及哥哥\",\"二狗子及母亲\",\"海边大小姐\",\"别墅管家\",\"别墅女仆们\"],\"objects\":[\"帐篷\",\"背包\",\"帆船\"],\"places\":[\"郊外村落\",\"森林通车小路\",\"海边别墅\",\"海滩\"]},{\"key\":\"c277\",\"id\":277,\"title\":\"莫空和大小姐\",\"kind\":\"main\",\"volume\":3,\"start\":1084,\"end\":1087,\"summary\":\"莫空海边夜钓时，大小姐谈重复人生与死亡，自称来自未来、将由另一个自己接替身体；影响未来的信会被抹除，他便建议留下信物。她归家发高烧，要求女仆水水称自己雯雯，并托其照顾未来变稚嫩的自己。水水坚持陪伴，女仆长落姨与厨师一起照料。\",\"turn\":\"未来来客与身体接替成为核心谜团，目前只是角色陈述与异常症状。\",\"time\":\"当夜\",\"people\":[\"莫空\",\"海边大小姐\",\"水水\",\"女仆长落姨\",\"厨师长\",\"别墅女仆们\"],\"objects\":[\"鱼竿\",\"篝火\",\"帐篷\",\"拟留的信物\",\"大狗熊玩偶\"],\"places\":[\"海滩\",\"海边别墅\"]},{\"key\":\"c278\",\"id\":278,\"title\":\"苏雨晴和创可贴\",\"kind\":\"main\",\"volume\":3,\"start\":1088,\"end\":1091,\"summary\":\"超市将于24日停业，城中顾客开始储备物资。苏雨晴两天前的指伤仍包着创可贴，周超继续关心并常来聊天；防损部员工指导起哄撮合，让她难以回应。王海峰及时插入玩笑解围，强调她太小，不存在自己的追求意图。周超看见她自在拌嘴的一面，愈发觉得可爱。\",\"turn\":\"照顾累积熟悉感，旁人把普通交往推向恋爱解读。\",\"time\":\"指伤两日后；通知8月24日下周二停业\",\"people\":[\"苏雨晴\",\"周超\",\"王海峰\",\"防损部员工指导\"],\"objects\":[\"创可贴\",\"棒棒糖\",\"停业通知\"],\"places\":[\"超市酒柜\"]},{\"key\":\"c279\",\"id\":279,\"title\":\"快开学了，你还会来吗？\",\"kind\":\"main\",\"volume\":3,\"start\":1092,\"end\":1095,\"summary\":\"独自午餐时，冉空城发短信问快开学是否回来，并追问离家出走传言。苏雨晴感到被挂念的温暖，也怕失去唯一旧友，谎称自己已转去外地学校。耐不住连续来电接通后，冉空城热情邀见面、同考大学，提到女班长曾护她；她却故作冷淡让他忘记自己。\",\"turn\":\"她主动切断关心以保护秘密，这种舍弃并非旧友拒绝她。\",\"time\":\"接近开学的午间；周超休息日\",\"people\":[\"苏雨晴\",\"冉空城\",\"旧校女班长\",\"旧日欺凌同学\"],\"objects\":[\"泡芙\",\"手机短信\"],\"places\":[\"超市门前广场\",\"育才中学（回忆）\"]},{\"key\":\"c280\",\"id\":280,\"title\":\"苏雨晴和平凡的少年\",\"kind\":\"main\",\"volume\":3,\"start\":1096,\"end\":1099,\"summary\":\"苏雨晴挂断冉空城、关机哭泣，又用工作压住情绪。胡玉牛来告知回乡几日，她劝他放弃女性化道路，遭冷眼后才反省：自己坚持相同愿望，却要求朋友妥协。下班绕路经过中学，看见独自练羽毛球的平凡少年，想起自己曾为免冉空城受嘲笑而拒绝陪伴。\",\"turn\":\"对胡玉牛的劝说适得其反；孤独少年使她看见自己拒绝帮助的旧模式。\",\"time\":\"同日下午至下班\",\"people\":[\"苏雨晴\",\"冉空城\",\"胡玉牛\",\"平凡少年\"],\"objects\":[\"练习点钞纸\",\"羽毛球拍\",\"羽毛球\"],\"places\":[\"超市酒柜\",\"住处旁中学操场\"]},{\"key\":\"c281\",\"id\":281,\"title\":\"胡玉牛村里的家（上）\",\"kind\":\"main\",\"volume\":3,\"start\":1100,\"end\":1103,\"summary\":\"父母多次催回家，胡玉牛仍怕秘密暴露，先在无名面馆逗留。食客抱怨城市封店，老板额外加面的小善意却让他重新看见温暖。傍晚河堤遇莫空，二人分享烤蟹、小黄鱼与啤酒，保持不追问隐私的分寸。谈及家族压力时，莫空说责任先要值得自己承担。\",\"turn\":\"与莫空的无压迫交谈缓冲焦虑，为直面家庭创造心理空间。\",\"time\":\"回乡当日下午至傍晚\",\"people\":[\"胡玉牛\",\"胡玉牛父母\",\"无名面馆老板夫妇\",\"面馆食客\",\"莫空\"],\"objects\":[\"炒面\",\"小城日报\",\"烤蟹\",\"小黄鱼\",\"啤酒\"],\"places\":[\"回乡公交车\",\"无名面馆\",\"河堤\"]},{\"key\":\"c282\",\"id\":282,\"title\":\"胡玉牛村里的家（下）\",\"kind\":\"main\",\"volume\":3,\"start\":1104,\"end\":1107,\"summary\":\"胡玉牛与莫空饮酒后梦见自己孤独悬在深海，醒来独自穿越幽暗山间小路，竟再度恐惧。归家时母亲热情关心他消瘦，父亲则察觉肌肉与体毛改变，责备缺乏锻炼；他谎称文员工作忙、服从公司形象要求。父亲意外没有继续动手干预，承认他该有自己的想法。\",\"turn\":\"家带来安全感又威胁秘密；父亲短暂让步并未触及核心身份问题。\",\"time\":\"回乡首夜八点后\",\"people\":[\"胡玉牛\",\"莫空\",\"胡玉牛父母\"],\"objects\":[\"啤酒\",\"熄灭篝火\",\"手机\"],\"places\":[\"河堤\",\"入村山间小路\",\"胡玉牛村中家\"]},{\"key\":\"c283\",\"id\":283,\"title\":\"快点找个女朋友\",\"kind\":\"main\",\"volume\":3,\"start\":1108,\"end\":1111,\"summary\":\"在家安睡后，胡玉牛看见荒废道馆与旧武术用品，理解父亲怀念家族昔日兴盛。父亲让他演醉拳，他借内心苦楚超常表现，虽耐力不足仍获肯定。母亲清晨精心做海鲜丸子，父母接着催他找女友、结婚，并把身体虚弱误解为需要进补，亲情和男性期待再次重叠。\",\"turn\":\"他感动于照料却必须隐瞒愿望；父母婚恋期待为柳韵线增加压力。\",\"time\":\"回乡次日清晨\",\"people\":[\"胡玉牛\",\"胡玉牛父母\",\"胡玉牛大伯\"],\"objects\":[\"李小龙海报\",\"生锈双截棍\",\"海鲜丸子\",\"虎鞭酒（角色拟用）\"],\"places\":[\"胡家道馆\",\"胡玉牛村中家\"]},{\"key\":\"c284\",\"id\":284,\"title\":\"妹子的声音！\",\"kind\":\"main\",\"volume\":3,\"start\":1112,\"end\":1115,\"summary\":\"孙昊临近开学离城，张思凡送站后发现方莜莜正与网友安念在游戏里逃避大公会追杀：两人抢到稀有麻痹戒指，而追兵恰属自己所在公会。她想协助逃脱，误打开语音使女声暴露，方莜莜急忙关麦；操作中断导致两人角色死亡，幸好戒指仍在。\",\"turn\":\"网友性别呈现危机打开新亲密关系，同时孙昊结束本次同住。\",\"time\":\"八月底、孙昊返校前\",\"people\":[\"方莜莜\",\"安念\",\"张思凡\",\"孙昊\",\"张思凡经理\",\"经理女友\"],\"objects\":[\"传奇游戏\",\"麻痹戒指\",\"耳麦\"],\"places\":[\"合租屋阳台\",\"火车站（送别）\",\"游戏世界\"]},{\"key\":\"c285\",\"id\":285,\"title\":\"安念的追问\",\"kind\":\"main\",\"volume\":3,\"start\":1116,\"end\":1120,\"summary\":\"安念追问声音，方莜莜起初否认，终于因渴望在网上以女性身份相处而开麦。二人从紧张变回熟悉，她婉拒照片请求与亲昵称呼。安念承诺分她一半戒指收入，张思凡转达经理出价三千元被拒；聊及女友时，安念坦言自己虽已上大学却未恋爱，双方气氛开始暧昧。\",\"turn\":\"方莜莜主动接受女性网络身份，但真实情况尚未向安念说明。\",\"time\":\"同日\",\"people\":[\"方莜莜\",\"安念\",\"张思凡\",\"张思凡经理\"],\"objects\":[\"耳麦\",\"麻痹戒指\",\"交易网站\"],\"places\":[\"合租屋\",\"网络游戏语音\"]},{\"key\":\"c286\",\"id\":286,\"title\":\"给林夕晨当模特\",\"kind\":\"main\",\"volume\":3,\"start\":1121,\"end\":1124,\"summary\":\"封店及外来人口清退使城市空荡，合租者靠本地二房东暂避影响；林夕晨挂在张思凡暂住证下，丢失身份证的苏雨晴最缺保障。林夕晨邀她外出写生，途中主动牵手。到公园后山土丘，她让苏雨晴面向天空做模特；苏沉浸被专注注视的幸福，却怕表白会失去朋友。\",\"turn\":\"含蓄的双向亲近开始明确可见，苏仍以朋友解释林的主动。\",\"time\":\"停业准备期间清晨\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"合租屋二房东\"],\"objects\":[\"身份证\",\"暂住证\",\"画板\"],\"places\":[\"空荡街道\",\"绿化公园\",\"公园后山土丘\"]},{\"key\":\"c287\",\"id\":287,\"title\":\"林夕晨的拥抱\",\"kind\":\"main\",\"volume\":3,\"start\":1125,\"end\":1128,\"summary\":\"林夕晨认真画成苏雨晴的肖像，又坚持请她给自己作画。苏担心水平不够，仍超常完成素描，并一度看见她温柔含笑。两人互赠各自画作后继续看城市；松子砸疼苏的头，林忽然将她拥入怀中抚慰。直接的关心令苏害羞，也让她对这段感情更难放下。\",\"turn\":\"互赠肖像和拥抱成为关系转折，尚无正式口头告白。\",\"time\":\"同日写生期间\",\"people\":[\"苏雨晴\",\"林夕晨\"],\"objects\":[\"苏雨晴彩色肖像\",\"林夕晨素描\",\"画板\",\"松子\"],\"places\":[\"公园后山土丘\"]},{\"key\":\"c288\",\"id\":288,\"title\":\"小混混们的善良\",\"kind\":\"main\",\"volume\":3,\"start\":1129,\"end\":1132,\"summary\":\"莫空逛待拆旧小区，看见一群年轻混混因狭隘的民族情绪弃玩游戏王、改学围棋，想起自己曾引导类似青年读书、学艺。河边少女失足落水，为首的狗哥立即跳水，众人合力救起她；少女起初仍害怕他们。莫空解释救援经过时，胡玉牛冲来误以为有人欺负她。\",\"turn\":\"外貌标签被实际善行打破，胡玉牛的二分判断即将受考验。\",\"time\":\"秋日清晨\",\"people\":[\"莫空\",\"黄枸\",\"狗头帮成员\",\"柳韵\",\"胡玉牛\",\"莫空曾帮助的青年们\"],\"objects\":[\"游戏王卡牌\",\"围棋\",\"报纸\"],\"places\":[\"待拆旧小区\",\"后门河边\"]},{\"key\":\"c289\",\"id\":289,\"title\":\"再相遇\",\"kind\":\"main\",\"volume\":3,\"start\":1133,\"end\":1136,\"summary\":\"莫空及时拦住胡玉牛，说明柳韵是被混混们救起。她亲近胡玉牛并继续自称未婚妻，狗头帮主动结交，帮主黄枸逐一介绍金毛狮王、剑鱼、凤凰、青蛙、鼠标、彩虹和赤脚大仙等成员及特长。胡玉牛承认对方有善意，礼貌交友，随后抱湿衣的柳韵回家。\",\"turn\":\"误会解除，胡玉牛与狗头帮建立联系，并再度与柳韵单独相处。\",\"time\":\"同日救援后\",\"people\":[\"莫空\",\"胡玉牛\",\"柳韵\",\"黄枸\",\"金毛狮王\",\"剑鱼\",\"凤凰\",\"青蛙\",\"鼠标\",\"彩虹\",\"赤脚大仙\"],\"objects\":[\"金脚项链\"],\"places\":[\"待拆旧小区河边\"]},{\"key\":\"c290\",\"id\":290,\"title\":\"闺房\",\"kind\":\"main\",\"volume\":3,\"start\":1137,\"end\":1140,\"summary\":\"胡玉牛抱柳韵走回家，虽累也想维持可靠形象。她邀请他进闺房，他从白熊玩偶与写满爱语的纸张看到她持续的心意，开始真心想以男友身份陪伴，却仍不肯面对身体选择。柳韵换好衣物后说一个月考验已过，重申认真爱情并主动亲吻，让他无法再假装未被打动。\",\"turn\":\"亲密关系转向需要明确答复，秘密却仍被拖延。\",\"time\":\"一个月约定届期附近；具体日期未写\",\"people\":[\"胡玉牛\",\"柳韵\"],\"objects\":[\"白熊玩偶\",\"暑假作业\",\"写满阿牛我爱你的纸\"],\"places\":[\"柳韵家\",\"柳韵卧室\"]},{\"key\":\"c291\",\"id\":291,\"title\":\"我……喜欢你\",\"kind\":\"main\",\"volume\":3,\"start\":1141,\"end\":1144,\"summary\":\"柳韵要求胡玉牛正视自己，明确说若他不喜欢便不强求。胡玉牛终于承认喜欢她，却只答应以后再解释此前拒绝的苦衷。柳韵快乐地要做午餐，并让他替自己扎头发；他关心她是否会被厨房器具弄伤。这份平凡的关怀令短暂幸福更真切，也掩住了尚未解决的冲突。\",\"turn\":\"双方明确彼此喜欢，恋爱成立，但知情程度不对等。\",\"time\":\"c290 同日\",\"people\":[\"胡玉牛\",\"柳韵\"],\"objects\":[\"粉蓝手帕\",\"发带\",\"电视节目\"],\"places\":[\"柳韵家\"]},{\"key\":\"c292\",\"id\":292,\"title\":\"柳韵的黑暗料理\",\"kind\":\"main\",\"volume\":3,\"start\":1145,\"end\":1149,\"summary\":\"柳韵精心尝试的蝴蝶面难以下咽，胡玉牛先顾及她的心情，待她自己尝过才改为教做面点。两人共同做爱心形状的面，失败料理化成合作的温馨午餐。胡玉牛称她是自己的救赎并说爱她，仍把是否停止身体改变的问题留给以后，幸福和逃避同时加深。\",\"turn\":\"共同生活的想象初步成形，核心抉择依然悬置。\",\"time\":\"同日午餐\",\"people\":[\"胡玉牛\",\"柳韵\"],\"objects\":[\"蝴蝶面\",\"面粉\",\"爱心面\",\"筷子与调羹\"],\"places\":[\"柳韵家厨房与客厅\"]},{\"key\":\"c293\",\"id\":293,\"title\":\"趴在大腿上睡着了\",\"kind\":\"main\",\"volume\":3,\"start\":1150,\"end\":1152,\"summary\":\"写生归家后，方莜莜与安念语聊，张思凡用游戏里的不同账号调节男女声身份。苏雨晴和林夕晨看动画，渴望永远支持自己的伴侣，靠着她睡去；林轻放她枕在腿上、替她理发。苏梦见两人乘巴士、火车、飞机一直同行，被张思凡逗醒时发现林腿麻仍无怨言。\",\"turn\":\"无言照护进一步加深依恋，同行之梦直接呈现她的亲密愿望。\",\"time\":\"写生当日下午至晚餐前\",\"people\":[\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"安念\",\"张思凡\"],\"objects\":[\"传奇双账号\",\"热茶\",\"哆啦A梦（文化引用）\"],\"places\":[\"合租屋客厅\",\"梦中交通工具\"]},{\"key\":\"c294\",\"id\":294,\"title\":\"蹭胸\",\"kind\":\"main\",\"volume\":3,\"start\":1153,\"end\":1156,\"summary\":\"张思凡做牛排、鹅肝，方莜莜做糕点汤，室友一起吃西餐。张把红酒说成黑莓汁，苏雨晴识破后为逞强接连饮酒而醉；方莜莜责怪玩笑过火并劝止。醉中的苏直接说最喜欢林夕晨、主动寻求拥抱与亲昵，最后被妥善安置在沙发，梦呓请求她不要离开。\",\"turn\":\"酒后直接表达依恋，但不能把醉态当双方清醒确认的恋爱承诺。\",\"time\":\"写生日晚餐\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\"],\"objects\":[\"西餐\",\"红酒\",\"高脚杯\"],\"places\":[\"合租屋餐厅与客厅\"]},{\"key\":\"c295\",\"id\":295,\"title\":\"失去了蛋蛋的人生\",\"kind\":\"main\",\"volume\":3,\"start\":1157,\"end\":1160,\"summary\":\"曾带人侵害柳韵的混混头目住院，回忆被胡玉牛重击后因逞强拖延就医，最终必须切除坏死的生殖器官。他不想失去原有男性生活，深感恐惧羞耻，并怨恨施伤者；父母照料又寻人无果。母亲改口小遥使他愤怒，父母暂仍叫小天，孩子否认哭泣却止不住眼泪。\",\"turn\":\"伤害造成长久创伤并埋下报复支线，原有生活和身份均遭撼动。\",\"time\":\"回忆河边冲突后，当前仍住院\",\"people\":[\"天语遥\",\"天语遥父母\",\"胡玉牛\",\"柳韵\",\"原混混手下\",\"医院医生\"],\"objects\":[\"病床\",\"手术同意书\"],\"places\":[\"小城市第一医院\"]},{\"key\":\"c296\",\"id\":296,\"title\":\"天语遥\",\"kind\":\"main\",\"volume\":3,\"start\":1161,\"end\":1164,\"summary\":\"父母提议今后进行女性化手术，天语遥先激烈拒绝，后在心理辅导中减少冲突，却依然痛苦。父亲办休学和新身份证，将名字改成天语遥；母亲梳头、设想乖巧女儿。父母一面说支持选择，一面认定女性生活更好。天语遥沉默接受新证件，心中仍以报复胡玉牛维系情绪。\",\"turn\":\"外在转变伴随家庭推动，沉默不等于原本身份愿望得到尊重。\",\"time\":\"住院半月左右\",\"people\":[\"天语遥\",\"天语遥父母\",\"心理医生\"],\"objects\":[\"新身份证\",\"激素药物\",\"桂花糕\",\"梳子\"],\"places\":[\"小城市第一医院\"]},{\"key\":\"c297\",\"id\":297,\"title\":\"开学季\",\"kind\":\"main\",\"volume\":3,\"start\":1165,\"end\":1168,\"summary\":\"会议到八月底结束，小城市和超市恢复运作。九月开学清晨，苏雨晴穿父母买的猫耳卫衣上班，路过中学看家长学生聚集，强烈怀念校园与冉空城。她渴望重新读书，却认为经济和身体愿望难以兼顾；被新生错认作学姐后，她温柔道别，也像在告别已失去的道路。\",\"turn\":\"停业结束，生活恢复；教育机会的损失成为她自立道路上的清晰代价。\",\"time\":\"2004年9月初开学\",\"people\":[\"苏雨晴\",\"冉空城\",\"中学新生女孩\",\"学生家长们\"],\"objects\":[\"黑色猫耳卫衣\",\"发糕\",\"豆奶\"],\"places\":[\"上班路\",\"中学校门\"]},{\"key\":\"c298\",\"id\":298,\"title\":\"刁难\",\"kind\":\"main\",\"volume\":3,\"start\":1169,\"end\":1172,\"summary\":\"王海峰延长休假，部门由翁锡芽负责。苏雨晴被派去领软标，途中看见陈淑艳以与老梅吃早餐回避迟到责难。防损部一名胖女员工从开门、说明流程到借笔、字迹都刻薄挑刺，还把失窃怪到她们部门；苏始终礼貌完成登记拿走软标，出来才松口气。\",\"turn\":\"缺少熟悉主管庇护时，小职权与部门敌意直接压向新人。\",\"time\":\"恢复营业后的早晨\",\"people\":[\"苏雨晴\",\"翁锡芽\",\"陈淑艳\",\"王海峰\",\"老梅\",\"防损部刻薄女员工\"],\"objects\":[\"软标\",\"领取表格\",\"水笔\",\"失窃红酒\"],\"places\":[\"超市酒柜\",\"防损部办公室\"]},{\"key\":\"c299\",\"id\":299,\"title\":\"刻薄\",\"kind\":\"main\",\"volume\":3,\"start\":1173,\"end\":1176,\"summary\":\"翁锡芽劝苏雨晴别与防损部冲突，派她去酒仓协助盘点。她看到胡玉牛在后仓睡觉，得知其整个假期没回合租屋。陈淑艳只给她轻松扫码工作；刻薄防损女员工来核对时不断讥讽，陈当面反击，酒柜促销员调停，拖延一小时才结束，让苏更厌倦职场争斗。\",\"turn\":\"对不同同事的亲疏更清晰；胡玉牛与合租群体继续脱离。\",\"time\":\"同日上午\",\"people\":[\"苏雨晴\",\"翁锡芽\",\"陈淑艳\",\"胡玉牛\",\"防损部刻薄女员工\",\"酒柜促销员\"],\"objects\":[\"库存终端机\",\"贵重酒\",\"盘点表\"],\"places\":[\"超市后仓\",\"酒柜独立仓库\"]},{\"key\":\"c300\",\"id\":300,\"title\":\"小弟们的看望\",\"kind\":\"main\",\"volume\":3,\"start\":1177,\"end\":1180,\"summary\":\"出院休学后的天语遥沉迷网络，面对父亲给出的两种激素方向仍痛苦难决。旧部带花果篮探望，狗头帮黄枸也携蛇酒为早前地盘冲突赔礼；众人误以为伤势已好，谈女人与报仇反让其更难堪。临别时他强撑旧口吻自称天冲云，明确揭示天语遥改名前的姓名。\",\"turn\":\"旧友关心与不知情话语相互冲突，黄枸成为两条混混关系线的交点。\",\"time\":\"出院后、开学前后\",\"people\":[\"天语遥\",\"天语遥父母\",\"黄枸\",\"天冲云旧部\"],\"objects\":[\"网络账号\",\"两类激素药物\",\"花篮\",\"水果篮\",\"蛇酒\"],\"places\":[\"天语遥家\"]},{\"key\":\"c301\",\"id\":301,\"title\":\"自残\",\"kind\":\"main\",\"volume\":3,\"start\":1181,\"end\":1184,\"summary\":\"访客离开后天语遥因被迫选择与失去旧身份而崩溃，自伤后失去意识，父母及时回家呼救送医。昏迷中他梦见狐耳少女温柔引导自己离开黑暗，醒来才知仍活着。父亲承认不该逼迫，愿改回名字并寻找治疗；天语遥疲惫拒绝折腾，说就这样，创伤尚未消失。\",\"turn\":\"自伤危机获救，父亲反思控制；人物的妥协与生存愿望仍需继续辨别。\",\"time\":\"探病同日其后\",\"people\":[\"天语遥\",\"天语遥父母\",\"梦中狐耳少女\",\"急救人员\"],\"objects\":[\"身份证\",\"救护车\"],\"places\":[\"天语遥家\",\"医院\",\"昏迷梦境\"]},{\"key\":\"c302\",\"id\":302,\"title\":\"选择\",\"kind\":\"main\",\"volume\":3,\"start\":1185,\"end\":1188,\"summary\":\"获救后的天语遥清醒表示选择成为听话女儿，请父母叫自己小遥，并要求父亲多陪家人、不要再为昂贵治疗拼命挣钱。她承诺不再自伤，仍拒绝回校；母亲喂巧克力、谈小时给她穿裙，父亲买清淡饭和她喜欢的零食，也买来女士香烟。家庭开始重新对话，但接受新身份不等于创伤消失。\",\"turn\":\"父母开始尊重孩子意愿；小遥主动选择新的家庭身份，痛苦仍待修复。\",\"time\":\"自伤获救后\",\"people\":[\"天语遥\",\"天语遥父母\"],\"objects\":[\"绷带\",\"巧克力\",\"泡椒凤爪\",\"女士香烟\"],\"places\":[\"医院\"]},{\"key\":\"c303\",\"id\":303,\"title\":\"是他们吗？\",\"kind\":\"main\",\"volume\":3,\"start\":1189,\"end\":1192,\"summary\":\"苏雨晴担心整日昏睡、不吃饭的胡玉牛，劝他不适就请假。她在柜台打盹，梦见父母来无条件接纳自己，醒后似见二人背影却被陈淑艳打断。章末父母真实对话证实曾来探望：父亲决定尊重孩子选择、帮助她并等她自愿回家，母亲建议准备女孩礼物。苏本人尚不知道这场态度转变。\",\"turn\":\"梦中团聚未现实发生，但父母现实态度已转向接纳，苏仍孤独猜测。\",\"time\":\"c298—c299同日午后\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"陈淑艳\",\"苏雨晴父母\"],\"objects\":[\"米袋\"],\"places\":[\"超市酒柜\",\"超市后仓\"]},{\"key\":\"c304\",\"id\":304,\"title\":\"接柳韵放学\",\"kind\":\"main\",\"volume\":3,\"start\":1193,\"end\":1196,\"summary\":\"夏仕尼提醒后胡玉牛才惊醒，发现睡过班且已迟到接柳韵的时间。他打车到小城市第一高中，故意不回催促短信以制造惊喜，放学时迎上并抱起她。柳韵提父母不在家，胡只提议吃饭；两人在沙县小吃分享饮料与食物。胡异常疲倦的原因未解，也继续隐瞒自身变化。\",\"turn\":\"恋爱进入接送和共餐日常，秘密与异常困倦仍被搁置。\",\"time\":\"当日16:30醒、17:00高中放学\",\"people\":[\"胡玉牛\",\"柳韵\",\"夏仕尼\"],\"objects\":[\"手机短信\",\"雪碧\",\"馄饨\"],\"places\":[\"超市后仓\",\"小城市第一高中\",\"沙县小吃\"]},{\"key\":\"c305\",\"id\":305,\"title\":\"亲亲我我\",\"kind\":\"main\",\"volume\":3,\"start\":1197,\"end\":1200,\"summary\":\"胡玉牛喂柳韵馄饨，答应亲手做小笼包。店内中年妇女嘲讽他们的亲昵，柳韵反击，胡劝她不要耗在争吵中，对方最终离开。二人沿河散步，柳跳起小时候学过的舞，又因心疼胡而放弃让他表演劈砖。她憧憬浪漫长久的爱情，他享受被爱却仍犹豫如何坦白秘密。\",\"turn\":\"两人的体贴与性格差异更鲜明，公开亲密也招来外部目光。\",\"time\":\"同日晚间\",\"people\":[\"胡玉牛\",\"柳韵\",\"刻薄中年食客\"],\"objects\":[\"馄饨\",\"小笼包\"],\"places\":[\"沙县小吃\",\"河边\"]},{\"key\":\"c306\",\"id\":306,\"title\":\"在我这里……过夜吧\",\"kind\":\"main\",\"volume\":3,\"start\":1201,\"end\":1204,\"summary\":\"柳韵记起作业后带胡玉牛回家，两人用贡丸馅合作做小笼包，吃完已近十点。胡帮她抄写语文作业，回忆小时被罚抄家规练出的速度，见她手酸又帮忙揉按。共同料理和学习让柳韵更不舍分别；胡准备返回合租屋时，她主动邀请他留下过夜。\",\"turn\":\"家庭式相处强化依恋，过夜邀请使胡面对隐瞒与责任的顾虑。\",\"time\":\"晚20:00回家、近22:00吃完\",\"people\":[\"胡玉牛\",\"柳韵\"],\"objects\":[\"贡丸小笼包\",\"语文作业\",\"家规\"],\"places\":[\"河边\",\"柳韵家\"]},{\"key\":\"c307\",\"id\":307,\"title\":\"钻进怀里的小猫咪\",\"kind\":\"main\",\"volume\":3,\"start\":1205,\"end\":1208,\"summary\":\"胡玉牛怕未坦白就把关系推进太深，起初拒绝留下，最终因柳韵独自在家害怕而睡客厅。他梦见说出秘密后获得支持，但现实并未坦白；清晨醒来发现柳韵已依偎在沙发怀里，昨夜没有性行为。二人起身吃早餐，她换上校服准备上学，胡此前的异常困倦暂时消失。\",\"turn\":\"梦境表达坦白愿望，现实的秘密继续延后；日常亲密与依赖加深。\",\"time\":\"次日05:00醒、约05:30早餐\",\"people\":[\"胡玉牛\",\"柳韵\"],\"objects\":[\"沙发\",\"校服\",\"早餐米糕\"],\"places\":[\"柳韵家\",\"早餐摊\"]},{\"key\":\"c308\",\"id\":308,\"title\":\"送柳韵上学\",\"kind\":\"main\",\"volume\":3,\"start\":1209,\"end\":1212,\"summary\":\"柳韵带胡玉牛走连接超市后山与学校后山的小路，看野花而不摘，畅想有菜地禽畜的山居生活。他背她沿山路前行，宁肯上班迟到也坚持送到校门，依恋越发强烈。两人约周六去流庆寺求签、购买刻双方名字的爱情锁；到校后门胡帮助她翻墙进校，再匆忙跑去上班。\",\"turn\":\"未来共同生活的想象与寺庙约定建立，实际赴约及坦白仍未发生。\",\"time\":\"次日06:40仍在送学；约周六午后出游\",\"people\":[\"胡玉牛\",\"柳韵\"],\"objects\":[\"野花\",\"爱情锁（计划购买）\"],\"places\":[\"市中心相连后山\",\"第一高中后门\",\"流庆寺（计划）\"]},{\"key\":\"c309\",\"id\":309,\"title\":\"吕布闪卡\",\"kind\":\"main\",\"volume\":3,\"start\":1213,\"end\":1215,\"summary\":\"教师节当天学校半日放假，超市因上级检查让未成年和证件不齐员工提前下班，苏雨晴获得午后闲暇。她仍收到冉空城问候却不回复，回忆他与女班长给予的不同保护。走到学校小店买童年零食时抽出稀有吕布闪卡，引来学生围观；一名男生出五十元求购，交易尚未决定。\",\"turn\":\"旧友与求学生活再度进入当下，一张卡片触发新的偶遇。\",\"time\":\"2004年9月10日星期五，教师节\",\"people\":[\"苏雨晴\",\"冉空城\",\"女班长\",\"求购卡片男生\",\"围观学生\"],\"objects\":[\"手机短信\",\"辣条\",\"干脆面\",\"吕布闪卡\"],\"places\":[\"超市\",\"学校小店\"]},{\"key\":\"c310\",\"id\":310,\"title\":\"彩色小鸡\",\"kind\":\"main\",\"volume\":3,\"start\":1216,\"end\":1219,\"summary\":\"求购吕布闪卡的出价从五十涨到两百，一位文澜学院腼腆高中男生认真求卡，苏雨晴却免费送给他后跑开。她路过学院再次向往高中生活，走进步行街，想起尚未把玩的星空球。看见染色雏鸡，她花一元买下红色小鸡，取名朱雀；叙述先提示这类小鸡生命脆弱，她本人尚不知情。\",\"turn\":\"卡片带来无偿善意的新联系，朱雀进入苏的照护生活。\",\"time\":\"2004年9月10日午后\",\"people\":[\"苏雨晴\",\"文澜学院腼腆男生\",\"卖小鸡商贩\",\"朱雀\"],\"objects\":[\"吕布闪卡\",\"星空水晶球\",\"染色小鸡\"],\"places\":[\"学校小店\",\"文澜学院门口\",\"步行街\"]},{\"key\":\"c311\",\"id\":311,\"title\":\"病怏怏的大小姐\",\"kind\":\"main\",\"volume\":3,\"start\":1220,\"end\":1222,\"summary\":\"苏雨晴在步行街喂朱雀，羡慕橱窗中的昂贵人偶，也认出愈发虚弱的海边别墅大小姐。暴雨将至，其他人避雨，大小姐却独坐树下说终于来了，短暂闭眼。雷暴忽来忽止，她醒后对地点、电子钟和自己的身体震惊，举止已明显不同；苏旁观感到困惑，接替身份的机制尚未明说。\",\"turn\":\"大小姐预告的转变疑似到来；叙述展示行为突变而未直接解释时间机制。\",\"time\":\"教师节午后雷暴\",\"people\":[\"苏雨晴\",\"朱雀\",\"雯雯\",\"暗中保护的男子\"],\"objects\":[\"BJD人偶\",\"电子钟\",\"桂花糕\"],\"places\":[\"步行街河边\",\"奶茶店\",\"人偶店\"]},{\"key\":\"c312\",\"id\":312,\"title\":\"在步行街巧遇张思凡\",\"kind\":\"main\",\"volume\":3,\"start\":1223,\"end\":1226,\"summary\":\"相貌近似大小姐的年轻女人买来等身毛绒熊，将仍迷惘的她抱上跑车离开；苏雨晴感到时间似被截断，黑蝶又重新出现。她偶遇同样因检查提前下班的张思凡，陪她选孙昊生日礼物。张被游戏厅吸引，双人射击几乎独自通关，苏转玩抓娃娃；玩兴中张终于想到送模型手枪。\",\"turn\":\"大小姐离开，礼物支线转入模型枪；张对孙的重视和贪玩消费习惯显露。\",\"time\":\"9月10日；孙昊生日9月15日\",\"people\":[\"苏雨晴\",\"张思凡\",\"雯雯\",\"相似年轻女人\",\"孙昊（谈及）\"],\"objects\":[\"等身毛绒熊\",\"跑车\",\"游戏币\",\"模型枪（计划）\"],\"places\":[\"步行街\",\"游戏厅\"]},{\"key\":\"c313\",\"id\":313,\"title\":\"林夕晨寄信\",\"kind\":\"main\",\"volume\":3,\"start\":1227,\"end\":1230,\"summary\":\"张思凡买下一百元毛瑟观赏模型枪并附贺卡寄给孙昊，在邮局巧遇寄钱家书的林夕晨。林已一年多未回偏远山村，家人不知她的女性生活；她仍牵挂父母，却刻意不写回址，怕极度重男轻女的父亲发现。父亲曾粗暴对待几个姐姐。张追问未来打算，也被苏指出自己同样回避家里问题。\",\"turn\":\"林与原生家庭的经济牵挂和身份隔阂被揭明；张寄出了生日礼物。\",\"time\":\"教师节14:00—15:00\",\"people\":[\"张思凡\",\"孙昊\",\"苏雨晴\",\"林夕晨\",\"林夕晨父母\",\"林夕晨的姐姐们\",\"邮局工作人员\"],\"objects\":[\"毛瑟模型枪\",\"生日贺卡\",\"现金家书\",\"邮票\"],\"places\":[\"模型枪店\",\"邮局\",\"林夕晨故乡（述及）\"]},{\"key\":\"c314\",\"id\":314,\"title\":\"陶艺\",\"kind\":\"main\",\"volume\":3,\"start\":1231,\"end\":1233,\"summary\":\"天语遥伤未全愈便回家，把自己裹在宽大外套中，减少与旧日兄弟联系却又舍不得彻底断开。网上寻找独处能做的事时，她被制陶广告启发，想起小时随爷爷做糖人的爱好，考虑学习可自主塑形的陶艺，甚至日后独立谋生。母亲邀她去游乐园，她首次答应出门，并问哪里能买材料。\",\"turn\":\"旧社交圈逐渐疏离，陶艺为恢复主动性和新的生活道路提供起点。\",\"time\":\"自伤出院后数日\",\"people\":[\"天语遥\",\"天语遥母亲\",\"旧日部下\",\"天语遥爷爷（回忆）\"],\"objects\":[\"宽大外套\",\"QQ\",\"制陶广告\"],\"places\":[\"天语遥家\"]},{\"key\":\"c315\",\"id\":315,\"title\":\"当我们老去\",\"kind\":\"main\",\"volume\":3,\"start\":1234,\"end\":1237,\"summary\":\"苏雨晴、张思凡与林夕晨沿街听老人争论时代、子孙和入学，苏因老去而焦虑，担心未来形象不再符合愿望。张以未经证实的短寿说法回应，又提醒人会因牵挂而不愿死去；这只能视为角色认知。三人继续买菜，合租者各尽所能补充食材的默契展现共同生活的支持。\",\"turn\":\"苏的青春与死亡焦虑显露，张的看似轻佻回应内含对牵挂的理解。\",\"time\":\"教师节午后返家途中\",\"people\":[\"苏雨晴\",\"张思凡\",\"林夕晨\",\"街边老人\"],\"objects\":[\"蔬菜\",\"日常药物（谈及）\"],\"places\":[\"小城市街道\",\"路边菜摊\"]},{\"key\":\"c316\",\"id\":316,\"title\":\"抢猫粮的小红鸡\",\"kind\":\"main\",\"volume\":3,\"start\":1238,\"end\":1240,\"summary\":\"工作日渐忙碌，合租采购改为各人零散补充，胡玉牛常不在家，大家感到隔阂。苏雨晴购买廉价火龙果分享，体现独立后学会节俭及珍惜小幸福；胡难得笑着归来主动做饭，却以加班解释晚间外出。朱雀被介绍给曲奇和咖啡，大胆抢猫粮，温顺的曲奇忍让后向苏求安慰。\",\"turn\":\"胡的恋爱改变家庭出勤，伙伴仍关心；朱雀开始融入人与动物的小家庭。\",\"time\":\"教师节下午至傍晚\",\"people\":[\"苏雨晴\",\"张思凡\",\"林夕晨\",\"胡玉牛\",\"方莜莜（谈及）\",\"曲奇\",\"咖啡\",\"朱雀\"],\"objects\":[\"火龙果\",\"猫粮\",\"冰箱食材\"],\"places\":[\"路边菜摊\",\"合租屋\"]},{\"key\":\"c317\",\"id\":317,\"title\":\"爱的便当\",\"kind\":\"main\",\"volume\":3,\"start\":1241,\"end\":1243,\"summary\":\"胡玉牛装好便当六点出门，苏雨晴留下收拾并给加班的方莜莜留饭。林夕晨首次主动帮她整理和洗碗，说要一起做，随后从背后拥抱怕冷的苏，两人不善言说的依恋再次加深。胡冒冷雨去第一高中，等数学补习的柳韵近一小时；他把保温饭盒护在怀里，盼她放学。\",\"turn\":\"苏林以共同家务与拥抱表达关爱；胡持续把恋情置于日常优先位置。\",\"time\":\"教师节18:00以后\",\"people\":[\"苏雨晴\",\"林夕晨\",\"胡玉牛\",\"柳韵\",\"方莜莜（谈及）\"],\"objects\":[\"保温便当盒\",\"留下的晚饭\"],\"places\":[\"合租屋厨房\",\"小城第一高中保安亭\"]},{\"key\":\"c318\",\"id\":318,\"title\":\"喂你吃\",\"kind\":\"main\",\"volume\":3,\"start\":1244,\"end\":1247,\"summary\":\"柳韵数学补习测验过关，欢快扑进等候的胡玉牛怀中；胡先前因害羞对保安谎称接妹妹，只好故作兄长。离校后他撑伞抱她到公园亭子分享亲手做的便当，二人轮流照顾进食。柳说明父母忙筹电脑配件店、近日晚归，谈父亲像孩子般亲近；胡由此看见与自己严父不同的家庭相处。\",\"turn\":\"数学补习阶段过关，双方用体贴与家庭分享深化关系；父母开店为真实计划。\",\"time\":\"教师节夜间\",\"people\":[\"胡玉牛\",\"柳韵\",\"学校保安\",\"柳韵父母（谈及）\"],\"objects\":[\"便当盒\",\"雨伞\",\"手机短信\"],\"places\":[\"第一高中\",\"公园亭子\"]},{\"key\":\"c319\",\"id\":319,\"title\":\"垃圾食品的副作用\",\"kind\":\"main\",\"volume\":3,\"start\":1248,\"end\":1250,\"summary\":\"朱雀与曲奇、咖啡同处，猫让出饼干，小鼠帮咬成小块，动物间形成照护。苏雨晴夜里受空城噩梦与胡晚归洗澡声影响，继而腹痛腹泻，猜是白天零食所致但未就医确诊。她忆及早产、多病和童年电梯受困，担忧身体妨碍自由，仍不愿放弃选择；折腾后才短暂睡稳，次晨腿酸。\",\"turn\":\"身体脆弱、童年恐惧与梦想代价交织；动物照护与苏孤独噩梦形成并置。\",\"time\":\"教师节深夜至次晨\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"曲奇\",\"咖啡\",\"朱雀\"],\"objects\":[\"猫饼干\",\"辣条\",\"干脆面\"],\"places\":[\"合租屋\",\"童年故障电梯（回忆）\"]},{\"key\":\"c320\",\"id\":320,\"title\":\"天语遥和游乐园\",\"kind\":\"main\",\"volume\":3,\"start\":1251,\"end\":1254,\"summary\":\"连续秋雨中天语遥再度冒出自毁念头，被母亲邀约打断，仍决定去人少的游乐园。父亲因出差缺席，实际努力工作是为她未来生活预留保障。出租车司机对其性别称呼变化令天心绪复杂，她既躲开母亲拥抱又渴望理解。到园后高危露天项目停开，她选择射气球，母亲买币陪同。\",\"turn\":\"生存危机尚未解除；首次母女外出成为重新接触世界的尝试。\",\"time\":\"次日雨中\",\"people\":[\"天语遥\",\"天语遥母亲\",\"天语遥父亲\",\"出租车司机\"],\"objects\":[\"宽大外套\",\"出租车\",\"游艺枪\"],\"places\":[\"天语遥家\",\"游乐园\",\"叶族博物馆（未去）\"]},{\"key\":\"c321\",\"id\":321,\"title\":\"天语遥和小白兔\",\"kind\":\"main\",\"vol");
